window.KH_SURA(24, {"sura": "النور", "n": 24, "ayat": {"1": "سُورَةٌ أَنْزَلْنَاهَا وَفَرَضْنَاهَا وَأَنْزَلْنَا فِيهَا آيَاتٍ بَيِّنَاتٍ لَعَلَّكُمْ تَذَكَّرُونَ", "2": "الزَّانِيَةُ وَالزَّانِي فَاجْلِدُوا كُلَّ وَاحِدٍ مِنْهُمَا مِائَةَ جَلْدَةٍ وَلَا تَأْخُذْكُمْ بِهِمَا رَأْفَةٌ فِي دِينِ اللَّهِ إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَلْيَشْهَدْ عَذَابَهُمَا طَائِفَةٌ مِنَ الْمُؤْمِنِينَ", "3": "الزَّانِي لَا يَنْكِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَةً وَالزَّانِيَةُ لَا يَنْكِحُهَا إِلَّا زَانٍ أَوْ مُشْرِكٌ وَحُرِّمَ ذَلِكَ عَلَى الْمُؤْمِنِينَ", "4": "وَالَّذِينَ يَرْمُونَ الْمُحْصَنَاتِ ثُمَّ لَمْ يَأْتُوا بِأَرْبَعَةِ شُهَدَاءَ فَاجْلِدُوهُمْ ثَمَانِينَ جَلْدَةً وَلَا تَقْبَلُوا لَهُمْ شَهَادَةً أَبَدًا وَأُولَئِكَ هُمُ الْفَاسِقُونَ", "5": "إِلَّا الَّذِينَ تَابُوا مِنْ بَعْدِ ذَلِكَ وَأَصْلَحُوا فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ", "6": "وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُنْ لَهُمْ شُهَدَاءُ إِلَّا أَنْفُسُهُمْ فَشَهَادَةُ أَحَدِهِمْ أَرْبَعُ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الصَّادِقِينَ", "7": "وَالْخَامِسَةُ أَنَّ لَعْنَتَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ", "8": "وَيَدْرَأُ عَنْهَا الْعَذَابَ أَنْ تَشْهَدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الْكَاذِبِينَ", "9": "وَالْخَامِسَةَ أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنَ الصَّادِقِينَ", "10": "وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ وَأَنَّ اللَّهَ تَوَّابٌ حَكِيمٌ", "11": "إِنَّ الَّذِينَ جَاءُوا بِالْإِفْكِ عُصْبَةٌ مِنْكُمْ لَا تَحْسَبُوهُ شَرًّا لَكُمْ بَلْ هُوَ خَيْرٌ لَكُمْ لِكُلِّ امْرِئٍ مِنْهُمْ مَا اكْتَسَبَ مِنَ الْإِثْمِ وَالَّذِي تَوَلَّى كِبْرَهُ مِنْهُمْ لَهُ عَذَابٌ عَظِيمٌ", "12": "لَوْلَا إِذْ سَمِعْتُمُوهُ ظَنَّ الْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بِأَنْفُسِهِمْ خَيْرًا وَقَالُوا هَذَا إِفْكٌ مُبِينٌ", "13": "لَوْلَا جَاءُوا عَلَيْهِ بِأَرْبَعَةِ شُهَدَاءَ فَإِذْ لَمْ يَأْتُوا بِالشُّهَدَاءِ فَأُولَئِكَ عِنْدَ اللَّهِ هُمُ الْكَاذِبُونَ", "14": "وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ فِي الدُّنْيَا وَالْآخِرَةِ لَمَسَّكُمْ فِي مَا أَفَضْتُمْ فِيهِ عَذَابٌ عَظِيمٌ", "15": "إِذْ تَلَقَّوْنَهُ بِأَلْسِنَتِكُمْ وَتَقُولُونَ بِأَفْوَاهِكُمْ مَا لَيْسَ لَكُمْ بِهِ عِلْمٌ وَتَحْسَبُونَهُ هَيِّنًا وَهُوَ عِنْدَ اللَّهِ عَظِيمٌ", "16": "وَلَوْلَا إِذْ سَمِعْتُمُوهُ قُلْتُمْ مَا يَكُونُ لَنَا أَنْ نَتَكَلَّمَ بِهَذَا سُبْحَانَكَ هَذَا بُهْتَانٌ عَظِيمٌ", "17": "يَعِظُكُمُ اللَّهُ أَنْ تَعُودُوا لِمِثْلِهِ أَبَدًا إِنْ كُنْتُمْ مُؤْمِنِينَ", "18": "وَيُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ وَاللَّهُ عَلِيمٌ حَكِيمٌ", "19": "إِنَّ الَّذِينَ يُحِبُّونَ أَنْ تَشِيعَ الْفَاحِشَةُ فِي الَّذِينَ آمَنُوا لَهُمْ عَذَابٌ أَلِيمٌ فِي الدُّنْيَا وَالْآخِرَةِ وَاللَّهُ يَعْلَمُ وَأَنْتُمْ لَا تَعْلَمُونَ", "20": "وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ وَأَنَّ اللَّهَ رَءُوفٌ رَحِيمٌ", "21": "يَاأَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ وَمَنْ يَتَّبِعْ خُطُوَاتِ الشَّيْطَانِ فَإِنَّهُ يَأْمُرُ بِالْفَحْشَاءِ وَالْمُنْكَرِ وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ مَا زَكَى مِنْكُمْ مِنْ أَحَدٍ أَبَدًا وَلَكِنَّ اللَّهَ يُزَكِّي مَنْ يَشَاءُ وَاللَّهُ سَمِيعٌ عَلِيمٌ", "22": "وَلَا يَأْتَلِ أُولُو الْفَضْلِ مِنْكُمْ وَالسَّعَةِ أَنْ يُؤْتُوا أُولِي الْقُرْبَى وَالْمَسَاكِينَ وَالْمُهَاجِرِينَ فِي سَبِيلِ اللَّهِ وَلْيَعْفُوا وَلْيَصْفَحُوا أَلَا تُحِبُّونَ أَنْ يَغْفِرَ اللَّهُ لَكُمْ وَاللَّهُ غَفُورٌ رَحِيمٌ", "23": "إِنَّ الَّذِينَ يَرْمُونَ الْمُحْصَنَاتِ الْغَافِلَاتِ الْمُؤْمِنَاتِ لُعِنُوا فِي الدُّنْيَا وَالْآخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ", "24": "يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُمْ بِمَا كَانُوا يَعْمَلُونَ", "25": "يَوْمَئِذٍ يُوَفِّيهِمُ اللَّهُ دِينَهُمُ الْحَقَّ وَيَعْلَمُونَ أَنَّ اللَّهَ هُوَ الْحَقُّ الْمُبِينُ", "26": "الْخَبِيثَاتُ لِلْخَبِيثِينَ وَالْخَبِيثُونَ لِلْخَبِيثَاتِ وَالطَّيِّبَاتُ لِلطَّيِّبِينَ وَالطَّيِّبُونَ لِلطَّيِّبَاتِ أُولَئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ لَهُمْ مَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ", "27": "يَاأَيُّهَا الَّذِينَ آمَنُوا لَا تَدْخُلُوا بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّى تَسْتَأْنِسُوا وَتُسَلِّمُوا عَلَى أَهْلِهَا ذَلِكُمْ خَيْرٌ لَكُمْ لَعَلَّكُمْ تَذَكَّرُونَ", "28": "فَإِنْ لَمْ تَجِدُوا فِيهَا أَحَدًا فَلَا تَدْخُلُوهَا حَتَّى يُؤْذَنَ لَكُمْ وَإِنْ قِيلَ لَكُمُ ارْجِعُوا فَارْجِعُوا هُوَ أَزْكَى لَكُمْ وَاللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ", "29": "لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَدْخُلُوا بُيُوتًا غَيْرَ مَسْكُونَةٍ فِيهَا مَتَاعٌ لَكُمْ وَاللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ", "30": "قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ", "31": "وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَانُهُنَّ أَوِ التَّابِعِينَ غَيْرِ أُولِي الْإِرْبَةِ مِنَ الرِّجَالِ أَوِ الطِّفْلِ الَّذِينَ لَمْ يَظْهَرُوا عَلَى عَوْرَاتِ النِّسَاءِ وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِنْ زِينَتِهِنَّ وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ", "32": "وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ وَاللَّهُ وَاسِعٌ عَلِيمٌ", "33": "وَلْيَسْتَعْفِفِ الَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّى يُغْنِيَهُمُ اللَّهُ مِنْ فَضْلِهِ وَالَّذِينَ يَبْتَغُونَ الْكِتَابَ مِمَّا مَلَكَتْ أَيْمَانُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا وَآتُوهُمْ مِنْ مَالِ اللَّهِ الَّذِي آتَاكُمْ وَلَا تُكْرِهُوا فَتَيَاتِكُمْ عَلَى الْبِغَاءِ إِنْ أَرَدْنَ تَحَصُّنًا لِتَبْتَغُوا عَرَضَ الْحَيَاةِ الدُّنْيَا وَمَنْ يُكْرِهْهُنَّ فَإِنَّ اللَّهَ مِنْ بَعْدِ إِكْرَاهِهِنَّ غَفُورٌ رَحِيمٌ", "34": "وَلَقَدْ أَنْزَلْنَا إِلَيْكُمْ آيَاتٍ مُبَيِّنَاتٍ وَمَثَلًا مِنَ الَّذِينَ خَلَوْا مِنْ قَبْلِكُمْ وَمَوْعِظَةً لِلْمُتَّقِينَ", "35": "اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ مَثَلُ نُورِهِ كَمِشْكَاةٍ فِيهَا مِصْبَاحٌ الْمِصْبَاحُ فِي زُجَاجَةٍ الزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّيٌّ يُوقَدُ مِنْ شَجَرَةٍ مُبَارَكَةٍ زَيْتُونَةٍ لَا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ يَكَادُ زَيْتُهَا يُضِيءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ نُورٌ عَلَى نُورٍ يَهْدِي اللَّهُ لِنُورِهِ مَنْ يَشَاءُ وَيَضْرِبُ اللَّهُ الْأَمْثَالَ لِلنَّاسِ وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ", "36": "فِي بُيُوتٍ أَذِنَ اللَّهُ أَنْ تُرْفَعَ وَيُذْكَرَ فِيهَا اسْمُهُ يُسَبِّحُ لَهُ فِيهَا بِالْغُدُوِّ وَالْآصَالِ", "37": "رِجَالٌ لَا تُلْهِيهِمْ تِجَارَةٌ وَلَا بَيْعٌ عَنْ ذِكْرِ اللَّهِ وَإِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ يَخَافُونَ يَوْمًا تَتَقَلَّبُ فِيهِ الْقُلُوبُ وَالْأَبْصَارُ", "38": "لِيَجْزِيَهُمُ اللَّهُ أَحْسَنَ مَا عَمِلُوا وَيَزِيدَهُمْ مِنْ فَضْلِهِ وَاللَّهُ يَرْزُقُ مَنْ يَشَاءُ بِغَيْرِ حِسَابٍ", "39": "وَالَّذِينَ كَفَرُوا أَعْمَالُهُمْ كَسَرَابٍ بِقِيعَةٍ يَحْسَبُهُ الظَّمْآنُ مَاءً حَتَّى إِذَا جَاءَهُ لَمْ يَجِدْهُ شَيْئًا وَوَجَدَ اللَّهَ عِنْدَهُ فَوَفَّاهُ حِسَابَهُ وَاللَّهُ سَرِيعُ الْحِسَابِ", "40": "أَوْ كَظُلُمَاتٍ فِي بَحْرٍ لُجِّيٍّ يَغْشَاهُ مَوْجٌ مِنْ فَوْقِهِ مَوْجٌ مِنْ فَوْقِهِ سَحَابٌ ظُلُمَاتٌ بَعْضُهَا فَوْقَ بَعْضٍ إِذَا أَخْرَجَ يَدَهُ لَمْ يَكَدْ يَرَاهَا وَمَنْ لَمْ يَجْعَلِ اللَّهُ لَهُ نُورًا فَمَا لَهُ مِنْ نُورٍ", "41": "أَلَمْ تَرَ أَنَّ اللَّهَ يُسَبِّحُ لَهُ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ وَالطَّيْرُ صَافَّاتٍ كُلٌّ قَدْ عَلِمَ صَلَاتَهُ وَتَسْبِيحَهُ وَاللَّهُ عَلِيمٌ بِمَا يَفْعَلُونَ", "42": "وَلِلَّهِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ وَإِلَى اللَّهِ الْمَصِيرُ", "43": "أَلَمْ تَرَ أَنَّ اللَّهَ يُزْجِي سَحَابًا ثُمَّ يُؤَلِّفُ بَيْنَهُ ثُمَّ يَجْعَلُهُ رُكَامًا فَتَرَى الْوَدْقَ يَخْرُجُ مِنْ خِلَالِهِ وَيُنَزِّلُ مِنَ السَّمَاءِ مِنْ جِبَالٍ فِيهَا مِنْ بَرَدٍ فَيُصِيبُ بِهِ مَنْ يَشَاءُ وَيَصْرِفُهُ عَنْ مَنْ يَشَاءُ يَكَادُ سَنَا بَرْقِهِ يَذْهَبُ بِالْأَبْصَارِ", "44": "يُقَلِّبُ اللَّهُ اللَّيْلَ وَالنَّهَارَ إِنَّ فِي ذَلِكَ لَعِبْرَةً لِأُولِي الْأَبْصَارِ", "45": "وَاللَّهُ خَلَقَ كُلَّ دَابَّةٍ مِنْ مَاءٍ فَمِنْهُمْ مَنْ يَمْشِي عَلَى بَطْنِهِ وَمِنْهُمْ مَنْ يَمْشِي عَلَى رِجْلَيْنِ وَمِنْهُمْ مَنْ يَمْشِي عَلَى أَرْبَعٍ يَخْلُقُ اللَّهُ مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", "46": "لَقَدْ أَنْزَلْنَا آيَاتٍ مُبَيِّنَاتٍ وَاللَّهُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ", "47": "وَيَقُولُونَ آمَنَّا بِاللَّهِ وَبِالرَّسُولِ وَأَطَعْنَا ثُمَّ يَتَوَلَّى فَرِيقٌ مِنْهُمْ مِنْ بَعْدِ ذَلِكَ وَمَا أُولَئِكَ بِالْمُؤْمِنِينَ", "48": "وَإِذَا دُعُوا إِلَى اللَّهِ وَرَسُولِهِ لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِيقٌ مِنْهُمْ مُعْرِضُونَ", "49": "وَإِنْ يَكُنْ لَهُمُ الْحَقُّ يَأْتُوا إِلَيْهِ مُذْعِنِينَ", "50": "أَفِي قُلُوبِهِمْ مَرَضٌ أَمِ ارْتَابُوا أَمْ يَخَافُونَ أَنْ يَحِيفَ اللَّهُ عَلَيْهِمْ وَرَسُولُهُ بَلْ أُولَئِكَ هُمُ الظَّالِمُونَ", "51": "إِنَّمَا كَانَ قَوْلَ الْمُؤْمِنِينَ إِذَا دُعُوا إِلَى اللَّهِ وَرَسُولِهِ لِيَحْكُمَ بَيْنَهُمْ أَنْ يَقُولُوا سَمِعْنَا وَأَطَعْنَا وَأُولَئِكَ هُمُ الْمُفْلِحُونَ", "52": "وَمَنْ يُطِعِ اللَّهَ وَرَسُولَهُ وَيَخْشَ اللَّهَ وَيَتَّقْهِ فَأُولَئِكَ هُمُ الْفَائِزُونَ", "53": "وَأَقْسَمُوا بِاللَّهِ جَهْدَ أَيْمَانِهِمْ لَئِنْ أَمَرْتَهُمْ لَيَخْرُجُنَّ قُلْ لَا تُقْسِمُوا طَاعَةٌ مَعْرُوفَةٌ إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ", "54": "قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِنْ تَوَلَّوْا فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُمْ مَا حُمِّلْتُمْ وَإِنْ تُطِيعُوهُ تَهْتَدُوا وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلَاغُ الْمُبِينُ", "55": "وَعَدَ اللَّهُ الَّذِينَ آمَنُوا مِنْكُمْ وَعَمِلُوا الصَّالِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ كَمَا اسْتَخْلَفَ الَّذِينَ مِنْ قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِي ارْتَضَى لَهُمْ وَلَيُبَدِّلَنَّهُمْ مِنْ بَعْدِ خَوْفِهِمْ أَمْنًا يَعْبُدُونَنِي لَا يُشْرِكُونَ بِي شَيْئًا وَمَنْ كَفَرَ بَعْدَ ذَلِكَ فَأُولَئِكَ هُمُ الْفَاسِقُونَ", "56": "وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ", "57": "لَا تَحْسَبَنَّ الَّذِينَ كَفَرُوا مُعْجِزِينَ فِي الْأَرْضِ وَمَأْوَاهُمُ النَّارُ وَلَبِئْسَ الْمَصِيرُ", "58": "يَاأَيُّهَا الَّذِينَ آمَنُوا لِيَسْتَأْذِنْكُمُ الَّذِينَ مَلَكَتْ أَيْمَانُكُمْ وَالَّذِينَ لَمْ يَبْلُغُوا الْحُلُمَ مِنْكُمْ ثَلَاثَ مَرَّاتٍ مِنْ قَبْلِ صَلَاةِ الْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُمْ مِنَ الظَّهِيرَةِ وَمِنْ بَعْدِ صَلَاةِ الْعِشَاءِ ثَلَاثُ عَوْرَاتٍ لَكُمْ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌ بَعْدَهُنَّ طَوَّافُونَ عَلَيْكُمْ بَعْضُكُمْ عَلَى بَعْضٍ كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ وَاللَّهُ عَلِيمٌ حَكِيمٌ", "59": "وَإِذَا بَلَغَ الْأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا كَمَا اسْتَأْذَنَ الَّذِينَ مِنْ قَبْلِهِمْ كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ وَاللَّهُ عَلِيمٌ حَكِيمٌ", "60": "وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ وَاللَّهُ سَمِيعٌ عَلِيمٌ", "61": "لَيْسَ عَلَى الْأَعْمَى حَرَجٌ وَلَا عَلَى الْأَعْرَجِ حَرَجٌ وَلَا عَلَى الْمَرِيضِ حَرَجٌ وَلَا عَلَى أَنْفُسِكُمْ أَنْ تَأْكُلُوا مِنْ بُيُوتِكُمْ أَوْ بُيُوتِ آبَائِكُمْ أَوْ بُيُوتِ أُمَّهَاتِكُمْ أَوْ بُيُوتِ إِخْوَانِكُمْ أَوْ بُيُوتِ أَخَوَاتِكُمْ أَوْ بُيُوتِ أَعْمَامِكُمْ أَوْ بُيُوتِ عَمَّاتِكُمْ أَوْ بُيُوتِ أَخْوَالِكُمْ أَوْ بُيُوتِ خَالَاتِكُمْ أَوْ مَا مَلَكْتُمْ مَفَاتِحَهُ أَوْ صَدِيقِكُمْ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَأْكُلُوا جَمِيعًا أَوْ أَشْتَاتًا فَإِذَا دَخَلْتُمْ بُيُوتًا فَسَلِّمُوا عَلَى أَنْفُسِكُمْ تَحِيَّةً مِنْ عِنْدِ اللَّهِ مُبَارَكَةً طَيِّبَةً كَذَلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَعْقِلُونَ", "62": "إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ آمَنُوا بِاللَّهِ وَرَسُولِهِ وَإِذَا كَانُوا مَعَهُ عَلَى أَمْرٍ جَامِعٍ لَمْ يَذْهَبُوا حَتَّى يَسْتَأْذِنُوهُ إِنَّ الَّذِينَ يَسْتَأْذِنُونَكَ أُولَئِكَ الَّذِينَ يُؤْمِنُونَ بِاللَّهِ وَرَسُولِهِ فَإِذَا اسْتَأْذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَأْذَنْ لِمَنْ شِئْتَ مِنْهُمْ وَاسْتَغْفِرْ لَهُمُ اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ", "63": "لَا تَجْعَلُوا دُعَاءَ الرَّسُولِ بَيْنَكُمْ كَدُعَاءِ بَعْضِكُمْ بَعْضًا قَدْ يَعْلَمُ اللَّهُ الَّذِينَ يَتَسَلَّلُونَ مِنْكُمْ لِوَاذًا فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ", "64": "أَلَا إِنَّ لِلَّهِ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ قَدْ يَعْلَمُ مَا أَنْتُمْ عَلَيْهِ وَيَوْمَ يُرْجَعُونَ إِلَيْهِ فَيُنَبِّئُهُمْ بِمَا عَمِلُوا وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ"}, "units": [{"aya": 2, "title": "في المنهي عنه المؤمنون من أخذ الرأفة بهما", "tabari": {"page": "17/139", "sarih": 1, "tarjih": "وأولى القولين في ذلك بالصواب قول من قال: معنى ذلك: ولا تأخذكم بهما رأفة في إقامة حد الله عليهما، الذي افترض عليكم إقامته عليهما.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "هو ترك إقامة حد الله عليهما، فأما إذا أقيم عليهما الحد، فلم تأخذهم", "taqdim": 0, "n_athar": 11, "qailun": [["نافع", "تابعي"], ["مجاهد", "تابعي"], ["ابن جريج", "تابع التابعين"], ["سعيد بن جبير", "تابعي"], ["إبراهيم", "تابعي"], ["ابن زيد", "تابع التابعين"], ["عطاء", "تابعي"], ["عامر", "تابعي"]], "athar": [52251, 52269, 52270, 52271, 52272, 52275, 52276, 52277, 52278, 52283, 52293, 52294, 52298, 52301, 52309, 52310, 52312, 52316, 52317, 52326]}, {"n": 2, "t": "بل معنى ذلك: ولا تأخذكم بهما رأفة فتخففوا الضرب عنهما، ولكن أوجعوهما ضربا", "taqdim": 0, "n_athar": 2, "qailun": [["الحسن وسعيد بن المسيب", "تابعي"], ["الزهري", "تابعي"]], "athar": []}]}, "mawaqif": [{"taliq": 4593, "mi": 1, "aya": 2, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 144", "qawl": "الأول", "nass": "إنما قلنا ذلك أولى التأويلين بالصواب لدلالة قول الله بعده: {في دين الله}، يعني: في طاعة الله التي أمركم بها. ومعلوم أن دين الله الذي أمر به في الزانيين: إقامة الحد عليهما على ما أمر من جلد كل واحد منهما مائة جلدة، مع أن الشدة في الضرب لا حد لها يوقف عليه، وكل ضرب أوجع فهو شديد، وليس للذي يوجع في الشدة حد لا زيادة فيه فيؤمر به. وغير جائز وصفه -جل ثناؤه- بأنه أمر بما لا سبيل للمأمور به إلى معرفته، وإذا كان ذلك كذلك فالذي للمأمورين إلى معرفته السبيل هو عدد الجلد على ما أمر به، وذلك هو إقامة الحد على ما قلنا", "qawaid": ["ظاهر الآية ولفظها", "الدلالة العقلية", "أقوال السلف"], "tabi": ""}], "mushid": {"i": 1, "imgs": ["024_001_1.png"], "pages": [378], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 4593, "masala": "الرأفة المنهي عنها في الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها الرأفة التي تؤدي إلى ترك إقامة حد الله عليهما، والمعنى: لا بد من إقامة الحد", "ashab": "", "athar": []}, {"n": 2, "t": "أنها الرأفة التي تؤدي إلى تخفيف الضرب عنهما، والمعنى: أوجعوهما ضربا", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["ظاهر الآية ولفظها", "الدلالة العقلية", "أقوال السلف"]}, "rulesD": {}}}, {"aya": 2, "title": "في مبلغ عدد الطائفة الذي أمر الله بشهود عذاب الزانيين البكرين", "tabari": {"page": "17/145", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب قول من قال: أقل ما ينبغى حضور ذلك من عدد المسلمين: الواحد فصاعدا. وذلك أن الله عم بقوله: ﴿وليشهد عذابهما طائفة﴾. والطائفة قد تقع عند العرب على الواحد فصاعدا. فإذا كان ذلك كذلك، ولم يكن الله تعالى ذكره وضع دلالة على أن مراده من ذلك خاص من العدد - كان معلوما أن حضور ما وقع عليه أدنى اسم الطائفة ذلك المحضر مخرج مقيم الحد مما أمره الله به بقوله: ﴿وليشهد عذابهما طائفة من المؤمنين﴾. غير أني وإن كان الأمر على ما وصفت، أستحب ألا يقصر بعدد من يحضر ذلك الموضع عن أربعة أنفس، عدد من تقبل شهادته على الزنى؛ لأن ذلك إذا كان كذلك، فلا خلاف بين الجميع أنه قد أدى المقيم الحد ما عليه في ذلك، وهم فيما دون ذلك مختلفون.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "أقله واحد", "taqdim": 0, "n_athar": 9, "qailun": [["مجاهد", "تابعي"], ["ابن أبي نجيح", "تابع التابعين"], ["مجاهد في هذه الآية", "تابعي"], ["حماد وإبراهيم", ""]], "athar": [52275, 52312]}, {"n": 2, "t": "أقله في هذا الموضع رجلان", "taqdim": 0, "n_athar": 2, "qailun": [["ابن جريج", "تابع التابعين"]], "athar": [52293]}, {"n": 3, "t": "أقل ذلك ثلاثة فصاعدا", "taqdim": 0, "n_athar": 5, "qailun": [["الزهري", "تابعي"], ["قتادة", "تابعي"]], "athar": [52284, 52285, 52286, 52303, 52318, 52319]}, {"n": 4, "t": "بل أقل ذلك أربعة", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [52294, 52326]}]}, "mawaqif": [{"taliq": 4594, "mi": 1, "aya": 2, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 149", "qawl": "الأول", "nass": "ذلك أن الله عم بقوله: {وليشهد عذابهما طائفة}، والطائفة: قد تقع عند العرب على الواحد فصاعدا. فإذا كان ذلك كذلك، ولم يكن الله -تعالى ذكره- وضع دلالة على أن مراده من ذلك خاص من العدد؛ كان معلوما أن حضور ما وقع عليه أدنى اسم الطائفة ذلك المحضر مخرج مقيم الحد مما أمره الله به بقوله: {وليشهد عذابهما طائفة من المؤمنين}", "qawaid": ["غير ذلك", "اللغة"], "tabi": ""}], "mushid": {"i": 2, "imgs": ["024_002_1.png"], "pages": [378], "n": 4, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 4594, "masala": "عدد الطائفة التي يجزئ شهادتها", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "واحد فصاعدا", "ashab": "", "athar": []}, {"n": 2, "t": "اثنان فصاعدا", "ashab": "", "athar": []}, {"n": 3, "t": "ثلاثة فصاعدا", "ashab": "", "athar": []}, {"n": 4, "t": "أربعة فصاعدا", "ashab": "", "athar": []}, {"n": 5, "t": "عشرة فصاعدا", "ashab": "", "athar": []}, {"n": 6, "t": "جماع من المسلمين", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["غير ذلك", "اللغة"]}, "rulesD": {}}}, {"aya": 2, "title": "الناسخ", "mawsua": {"taliq": 4592, "masala": "الناسخ", "sigha": "حكاية خلاف", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "الناسخ السنة المتواترة في الرجم", "ashab": "", "athar": []}, {"n": 2, "t": "بل القرآن الذي ارتفع لفظه وبقي حكمه، وهو الذي قرأه عمر على المنبر بمحضر الصحابة: (الشيخ والشيخة إذا زنيا فارجموهما البتة). وقال: إنا قرأناه في كتاب الله. واتفق الجميع على أن لفظه رفع وبقي حكمه", "ashab": "", "athar": []}, {"n": 3, "t": "ليس في هذه الآية نسخ، بل سنة الرجم جاءت بزيادة. فالمحصن على رأي هذه الفرقة يجلد ثم يرجم", "ashab": "الحسن بن أبي الحسن، وابن راهويه", "athar": []}, {"n": 4, "t": "هذه الآية خاصة في البكرين", "ashab": "ابن سلام وغيره", "athar": []}]}, "mawaqif": [{"taliq": 4592, "mi": 0, "aya": 2, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 331 - 333", "qawl": "", "nass": "الألف واللام في قوله: {الزانية والزاني} للجنس، وذلك يعطي أنها عامة في جميع الزناة. وهذه الآية باتفاق ناسخة لآية الحبس وآية الآذى اللتين في سورة النساء. وجماعة العلماء على عموم هذه الآية، وأن حكم المحصنين منسوخ منها، واختلفوا في الناسخ: فقالت فرقة: الناسخ السنة المتواترة في الرجم. وقالت فرقة: بل القرآن الذي ارتفع لفظه وبقي حكمه، وهو الذي قرأه عمر على المنبر بمحضر الصحابة: (الشيخ والشيخة إذا زنيا فارجموهما البتة). وقال: إنا قرأناه في كتاب الله. واتفق الجميع على أن لفظه رفع وبقي حكمه. وقال الحسن بن أبي الحسن، وابن راهويه: ليس في هذه الآية نسخ، بل سنة الرجم جاءت بزيادة. فالمحصن على رأي هذه الفرقة يجلد ثم يرجم، وهو قول علي بن أبي طالب، وفعله بشراحة، ودليلهم قول النبي صلى الله عليه وسلم: «والثيب بالثيب جلد مائة والرجم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 3, "title": "في تأويل ذلك ﴿الزاني لا ينكح إلا زانية أو مشركة والزانية لا ينكحها إلا زان أو مشرك وحرم ذلك على المؤمنين﴾", "tabari": {"page": "17/149", "sarih": 1, "tarjih": "قال أبو جعفر: وأولى الأقوال في ذلك عندى بالصواب قول من قال: عنى بالنكاح في هذا الموضع الوطء، وأن الآية نزلت في البغايا المشركات ذوات الرايات. وذلك لقيام الحجة على أن الزانية من المسلمات حرام على كل مشرك، وأن الزانى من المسلمين حرام عليه كل مشركة من عبدة الأوثان. فمعلوم إذ كان ذلك كذلك، أنه لم يعن بالآية أن الزاني من المؤمنين لا يعقد عقد نكاح على عفيفة من المسلمات، ولا ينكح إلا زانية أو مشركة. وإذ كان ذلك كذلك، فبين أن معنى الآية: الزانى لا يزنى إلا بزانية [لا تستحل] الزنى، أو بمشركة تستحله.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "نزلت هذه الآية في بعض من استأذن رسول الله ﷺ في نكاح نسوة كن معروفات بالزنى من أهل الشرك، وكن أصحاب رايات يكرين أنفسهن، فأنزل الله تحريمهن على المؤمنين، فقال: الزانى من المؤمنين لا يتزوج إلا زانية أو مشركة؛ لأنهن كذلك، والزانية من أولئك البغايا لا ينكحها إلا زان من المؤمنين أو المشركين ، أو مشرك مثلها؛ لأنهن كن مشركات، ﴿وحرم ذلك على المؤمنين﴾ فحرم الله نكاحهن في قول أهل هذه المقالة بهذه الآية", "taqdim": 0, "n_athar": 21, "qailun": [["لها", ""], ["عبد الله بن عمرو", "صحابي"], ["عمرو بن شعيب", "تابعي"], ["مجاهد", "تابعي"], ["ابن عباس", "صحابي"], ["عطاء", "تابعي"], ["ابن أبي نجيح", "تابع التابعين"], ["سعيد بن المسيب", "تابعي"], ["الشعبي", "تابعي"]], "athar": [52329, 52331, 52332, 52333, 52334, 52338, 52339, 52340, 52341, 52342, 52343, 52346, 52351, 52352, 52354, 52355, 52356, 52357, 52360, 52366, 52380]}, {"n": 2, "t": "معنى ذلك: الزانى لا يزنى إلا بزانية أو مشركة، والزانية لا يزنى بها إلا زان أو مشرك. قالوا: ومعنى النكاح في هذا الموضع الجماع", "taqdim": 0, "n_athar": 8, "qailun": [["ابن عباس", "صحابي"], ["سعيد بن جبير", "تابعي"], ["سعيد بن جبير وعكرمة", "تابعي"], ["معمر", "تابع التابعين"], ["ابن زيد", "تابع التابعين"]], "athar": [52331, 52335, 52352, 52354, 52355, 52356, 52359, 52362, 52376]}, {"n": 3, "t": "كان هذا حكم الله في كل زان وزانية، حتى نسخه بقوله: ﴿وأنكحوا الأيامى منكم﴾ [النور: ٣٢]. فأحل نكاح كل مسلمة، وإنكاح كل مسلم", "taqdim": 0, "n_athar": 5, "qailun": [["سعيد بن المسيب", "تابعي"], ["ابن جريج", "تابع التابعين"], ["معمر", "تابع التابعين"], ["يحيى", "تابعي"]], "athar": [52334, 52379, 52380, 52381]}]}, "mawaqif": [{"taliq": 4597, "mi": 1, "aya": 3, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 160 - 161", "qawl": "الثاني", "nass": "أولى الأقوال في ذلك عندي بالصواب قول من قال: عني بالنكاح في هذا الموضع: الوطء، وأن الآية نزلت في البغايا المشركات ذوات الرايات؛ وذلك لقيام الحجة على أن الزانية من المسلمات حرام على كل مشرك، وأن الزاني من المسلمين حرام عليه كل مشركة من عبدة الأوثان. فمعلوم إذا كان ذلك كذلك أنه لم يعن بالآية: أن الزاني من المؤمنين لا يعقد عقد نكاح على عفيفة من المسلمات، ولا ينكح إلا زانية أو مشركة. وإذ كان ذلك كذلك فبين أن معنى الآية: الزاني لا يزني إلا بزانية لا تستحل الزنا، أو بمشركة تستحله", "qawaid": ["أقوال السلف", "الدلالة العقلية", "ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 4597, "mi": 1, "aya": 3, "alam": "ابن عطية", "fil": "اختاره", "kind": "ترجيح", "ref": "6/ 336", "qawl": "", "nass": "اتصال هذا المعنى بما قبل حسن بليغ", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 4597, "mi": 1, "aya": 3, "alam": "ابن كثير", "fil": "ومثله", "kind": "موافقة", "ref": "10/ 165", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}, {"taliq": 4597, "mi": 1, "aya": 3, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "6/ 338", "qawl": "", "nass": "وذكر الإشراك في الآية يضعف هذه المناحي", "qawaid": [], "tabi": ""}, {"taliq": 4597, "mi": 1, "aya": 3, "alam": "ابن تيمية", "fil": "اختار", "kind": "ترجيح", "ref": "4/ 488 - 489", "qawl": "الأول", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 4597, "mi": 1, "aya": 3, "alam": "ابن القيم", "fil": "وكذا", "kind": "موافقة", "ref": "2/ 233 - 234", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن تيمية"}, {"taliq": 4597, "mi": 1, "aya": 3, "alam": "ابن تيمية", "fil": "انتقد", "kind": "نقد", "ref": "4/ 486 - 487، 570 - 571 بتصرف", "qawl": "الثاني", "nass": "1 - ليس في القرآن لفظ نكاح إلا ولا بد أن يراد به العقد، وإن دخل فيه الوطء أيضا، فأما أن يراد به مجرد الوطء فهذا لا يوجد في كتاب الله قط. 2 - أن سبب نزول الآية إنما هو استفتاء النبي صلى الله عليه وسلم في التزوج بزانية، فكيف يكون سبب النزول خارجا من اللفظ؟! 3 - أن الزاني قد يستكره امرأة فيطؤها؛ فيكون زانيا ولا تكون زانية، وكذلك المرأة قد تزني بنائم ومكره -على أحد القولين- ولا يكون زانيا. 4 - أن تحريم الزنا قد علمه المسلمون بآيات نزلت بمكة، وتحريمه أشهر من أن تنزل هذه الآية بتحريمه. 5 - قال: {لا ينكحها إلا زان أو مشرك}، فلو أريد الوطء لم يكن حاجة إلى ذكر المشرك؛ فإنه زان، وكذلك المشركة إذا زنى بها رجل فهي زانية فلا حاجة إلى التقسيم. 6 - أنه قد قال قبل ذلك: {الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة}، فأي حاجة إلى أن يذكر تحريم الزنا بعد ذلك؟!", "qawaid": ["سبب النزول وأحواله", "الدلالة العقلية"], "tabi": ""}, {"taliq": 4597, "mi": 1, "aya": 3, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "وجهها -والله أعلم- أن المتزوج أمر أن يتزوج المحصنة العفيفة، وإنما أبيح له نكاح المرأة بهذا الشرط، كما ذكر ذلك سبحانه في سورتي النساء والمائدة، والحكم المعلق على الشرط ينتفي عند انتفائه، والإباحة قد علقت على شرط الإحصان، فإذا انتفى الإحصان انتفت الإباحة المشروطة به، فالمتزوج إما أن يلتزم حكم الله وشرعه الذي شرعه على لسان رسوله، أو لا يلتزمه، فإن لم يلتزمه فهو مشرك لا يرضى بنكاحه إلا من هو مشرك مثله، وإن التزمه وخالفه ونكح ما حرم عليه لم يصح النكاح فيكون زانيا، فظهر معنى قوله: {لا ينكح إلا زانية أو مشركة}، وتبين غاية البيان، وكذلك حكم المرأة. وكما أن هذا الحكم هو موجب القرآن وصريحه فهو موجب الفطرة ومقتضى العقل؛ فإن الله سبحانه حرم على عبده أن يكون قرنانا ديوثا زوج بغي، فإن الله تعالى فطر الناس على استقباح ذلك واستهجانه، ولهذا إذا بالغوا في سب الرجل قالوا: زوج قحبة. فحرم الله على المسلم أن يكون كذلك، فظهرت حكمة التحريم، وبان معنى الآية", "qawaid": [], "tabi": ""}, {"taliq": 4597, "mi": 1, "aya": 3, "alam": "ابن القيم", "fil": "انتقد", "kind": "نقد", "ref": "2/ 234 بتصرف", "qawl": "", "nass": "هذا فاسد؛ فإن هذه الصورة المعينة وإن كانت سبب النزول فالقرآن لا يقتصر به على محال أسبابه، ولو كان كذلك لبطل الاستدلال به على غيرها", "qawaid": [], "tabi": ""}], "mushid": {"i": 3, "imgs": ["024_003_1.png"], "pages": [378], "n": 3, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 4597, "masala": "تأويل {ينكح}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه الزواج. ثم هم بعد ذلك على ثلاثة أقوال: الأول: أنها نزلت في بعض من استأذن رسول الله صلى الله عليه وسلم في نكاح نسوة كن معروفات بالزنا من أهل الشرك، فأنزل الله تحريمهن على المؤمنين. فهو عام مراد به الخصوص", "ashab": "", "athar": []}, {"n": 2, "t": "أنها مخصوصة في الزاني المحدود لا يتزوج إلا زانية محدودة، ولا يتزوج غير محدودة ولا عفيفة، والزانية المحدودة لا يتزوجها إلا زان محدود، ولا يتزوجها غير محدود ولا عفيف. والثالث: أن هذا قد كان حكم الله في كل زان وزانية، حتى نسخه الله عز وجل، فأحل نكاح كل مسلمة، وإنكاح كل مسلم. ومعنى النكاح في هذا القول: الزواج. وثانيها: أنه الجماع. ومعناها: الزاني لا يزني إلا بزانية أو مشركة، والزانية لا يزني بها إلا زان أو مشرك. ومقصدها تشنيع وتبشيع أمر الزنا وأنه شأن هؤلاء ومن خلقهم", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"], ["ابن عطية", "r"], ["ابن كثير", "r"], ["ابن تيمية", "d"]], "1": [["ابن تيمية", "r"], ["ابن القيم", "r"]]}, "t": {"2": [["ابن جرير", "r"], ["ابن عطية", "r"], ["ابن كثير", "r"], ["ابن تيمية", "d"]], "1": [["ابن تيمية", "r"], ["ابن القيم", "r"]]}, "gen": [], "rules": {"ابن جرير": ["أقوال السلف", "الدلالة العقلية", "ظاهر الآية ولفظها"]}, "rulesD": {"ابن تيمية": ["سبب النزول وأحواله", "الدلالة العقلية"]}}}, {"aya": 3, "title": "حكم هذه الآية", "mawsua": {"taliq": 4598, "masala": "حكم هذه الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها محكمة", "ashab": "", "athar": []}, {"n": 2, "t": "أنها منسوخة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 4598, "mi": 1, "aya": 3, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 160 - 161", "qawl": "الأول", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 4598, "mi": 1, "aya": 3, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "6/ 336 - 338", "qawl": "الأول", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 4598, "mi": 1, "aya": 3, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "الصواب: القول بأن هذه الآية محكمة يعمل بها، لم ينسخها شيء، وهي مشتملة على خبر وتحريم، ولم يأت من ادعى نسخها بحجة ألبتة", "qawaid": [], "tabi": ""}, {"taliq": 4598, "mi": 1, "aya": 3, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن القيم"}], "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن عطية", "r"]]}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 5, "title": "في الذي استثنى منه قوله: ﴿إلا الذين تابوا من بعد ذلك وأصلحوا﴾", "tabari": {"page": "17/162", "sarih": 1, "tarjih": "والصواب من القول في ذلك عندنا أن الاستثناء من المعنيين جميعا؛ أعنى من قوله: ﴿ولا تقبلوا لهم شهادة أبدا﴾. ومن قوله: ﴿وأولئك هم الفاسقون﴾. وذلك أنه لا خلاف بين الجميع أن ذلك كذلك إذا لم يحد في القذف حتى تاب:", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "استثنى من قوله: ﴿ولا تقبلوا لهم شهادة أبدا وأولئك هم الفاسقون﴾. وقالوا: إذا تاب القاذف قبلت شهادته، وزال عنه اسم الفسق، حد فيه أولم يحد", "taqdim": 0, "n_athar": 18, "qailun": [["لأبي بكرة", ""], ["سعيد بن المسيب", "تابعي"], ["الشعبي", "تابعي"], ["عامر", "تابعي"], ["أبو موسى", "صحابي"], ["سليمان بن يسار والشعبي", ""], ["قتادة", "تابعي"], ["الشعبي لإبراهيم", "تابعي"], ["الحكم", "تابعي"], ["عمران ابن عمير", ""], ["الضحاك", "تابعي"], ["ابن المسيب", ""], ["معمر", "تابع التابعين"]], "athar": [52417, 52420, 52421, 52423, 52428, 52430, 52436, 52440, 52445, 52446, 52447, 52448, 52465]}, {"n": 2, "t": "الاستثناء في ذلك من قوله : ﴿وأولئك هم الفاسقون﴾. وأما قوله: ﴿ولا تقبلوا لهم شهادة أبدا﴾. فقد وصل بالأبد، ولا يجوز قبولها أبدا", "taqdim": 0, "n_athar": 16, "qailun": [["شريح", ""], ["شريح في القاذف", ""], ["الشعبي", "تابعي"], ["أنه كان", ""], ["إبراهيم", "تابعي"], ["سعيد بن المسيب", "تابعي"], ["الحسن", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [52414, 52415, 52416, 52417, 52419, 52428, 52430, 52435, 52436, 52437, 52441, 52445, 52446, 52465, 52469]}]}, "mawaqif": [{"taliq": 4600, "mi": 0, "aya": 5, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 172 - 173", "qawl": "الأول", "nass": "ذلك أنه لا خلاف بين الجميع أن ذلك كذلك إذا لم يحد في القذف حتى تاب؛ إما بأن لم يرفع إلى السلطان بعفو المقذوفة عنه، وإما بأن ماتت قبل المطالبة بحدها ولم يكن لها طالب يطلب بحدها، فإذ كان ذلك كذلك وحدثت منه توبة صحت له بها العدالة. فإذ كان من الجميع إجماعا، ولم يكن الله -تعالى ذكره- شرط في كتابه أن لا تقبل شهادته أبدا بعد الحد في رميه، بل نهى عن قبول شهادته في الحال التي أوجب عليه فيها الحد، وسماه فيها فاسقا؛ كان معلوما بذلك أن إقامة الحد عليه في رميه لا تحدث في شهادته مع التوبة من ذنبه ما لم يكن حادثا فيها قبل إقامته عليه، بل توبته بعد إقامة الحد عليه من ذنبه أحرى أن تكون شهادته معها أجوز منها قبل إقامته عليه؛ لأن الحد يزيد المحدود عليه تطهيرا من جرمه الذي استحق عليه الحد", "qawaid": ["الإجماع", "الدلالة العقلية"], "tabi": ""}, {"taliq": 4600, "mi": 0, "aya": 5, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "5/ 491 - 492، 591", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}], "mushid": {"i": 4, "imgs": ["024_004_1.png"], "pages": [379], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["الإجماع", "الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 5, "title": "في صفة توبة القاذف التي تقبل معها شهادته", "tabari": {"page": "17/174", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "هي إكذابه نفسه فيه. وقد ذكرنا بعض قائلى ذلك فيما مضى قبل، ونحن نذكر بعض ما حضرنا ذكره مما لم نذكره قبل", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "توبته من ذلك [صلاح حاله، وندمه على ما فرط منه من ذلك، و] الاستغفار منه، وتركه العود في مثل ذلك من الجرم. وذلك قول جماعة من التابعين وغيرهم، وقد ذكرنا بعض قائليه فيما مضى، وهو قول مالك بن أنس", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 4601, "mi": 0, "aya": 5, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 175 - 176", "qawl": "الثاني", "nass": "لأن الله -تعالى ذكره- جعل توبة كل ذي ذنب من أهل الإيمان تركه العود منه، والندم على ما سلف منه، واستغفار ربه منه، فيما كان من ذنب بين العبد وبينه، دون ما كان من حقوق عباده ومظالمهم بينهم، والقاذف إذا أقيم عليه فيه الحد، أو عفي عنه، فلم يبق عليه إلا توبته من جرمه بينه وبين ربه، فسبيل توبته منه سبيل توبته من سائر إجرامه", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 6, "title": "العذاب الذي عناه الله في هذا الموضع", "mawsua": {"taliq": 4603, "masala": "العذاب الذي عناه الله في هذا الموضع", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه الحد", "ashab": "", "athar": []}, {"n": 2, "t": "أنه الحبس", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 4603, "mi": 1, "aya": 6, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 187 - 188", "qawl": "الأول", "nass": "إنما قلنا: الواجب عليها إذا هي امتنعت من الالتعان بعد التعان الزوج الحد الذي وصفنا. قياسا على إجماع الجميع على أن الحد إذا زال عن الزوج بالشهادات الأربع على تصديقه فيما رماها به؛ أن الحد عليها واجب، فجعل الله أيمانه الأربع والتعانه في الخامسة مخرجا له من الحد الذي يجب لها برميه إياها، كما جعل الشهداء الأربعة مخرجا له منه في ذلك وزائلا به عنه الحد، فكذلك الواجب أن يكون بزوال الحد عنه بذلك واجبا عليها حدها، كما كان بزواله عنه بالشهود واجبا عليها، لا فرق بين ذلك", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 4603, "mi": 1, "aya": 6, "alam": "ابن عطية", "fil": "ذهب", "kind": "قول", "ref": "6/ 348", "qawl": "", "nass": "والعذاب المدرأ في قول جمهور العلماء: الحد. وحكى الطبري عن آخرين: أنه الحبس -وهو قول أصحاب الرأي-، وأنه لا حد عليها -إن لم تلاعن-، وليس يوجبه عليها قول الزوج … وظاهر الحديث الوقفة في الخامسة حين تلكأت ثم مرت في لعانها أنها كانت تحد لقول النبي صلى الله عليه وسلم لها: «فعذاب الدنيا أيسر من عذاب الآخرة»", "qawaid": [], "tabi": ""}], "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 11, "title": "تأويل: ﴿إن الذين جاءوا بالإفك عصبة منكم لا تحسبوه شرا لكم بل هو خير لكم لكل امرئ منهم ما اكتسب من ﴾", "tabari": {"page": "17/189", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: إن الذين جاءوا بالكذب والبهتان ﴿عصبة منكم﴾. يقول: جماعة منكم أيها الناس، ﴿لا تحسبوه شرا لكم بل هو خير لكم﴾. يقول: لا تظنوا ما جاءوا به من الإفك شرا لكم عند الله وعند الناس، بل ذلك خير لكم عنده وعند المؤمنين؛ وذلك أن الله يجعل ذلك كفارة للمرمي به، ويظهر براءته مما رمي به، وبجعل له منه مخرجا.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "إن الذين عنى الله بقوله: ﴿إن الذين جاءوا بالإفك عصبة منكم﴾. جماعة منهم حسان بن ثابت، ومسطح بن أثاثة، وحمنة بنت جحش", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 4610, "mi": 1, "aya": 11, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 197", "qawl": "الأول", "nass": "ذلك أنه لا خلاف بين أهل العلم بالسير أن الذي بدأ بذكر الإفك، وكان يجمع أهله ويحدثهم؛ عبد الله بن أبي ابن سلول، وفعله ذلك على ما وصفت كان توليه كبر ذلك الأمر", "qawaid": ["الإجماع", "السنة", "الدلالة العقلية", "السنة"], "tabi": ""}], "mushid": {"i": 5, "imgs": ["024_005_1.png"], "pages": [379], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 4610, "masala": "المعني بقوله تعالى: {والذي تولى كبره}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه عبد الله بن أبي بن سلول", "ashab": "", "athar": []}, {"n": 2, "t": "أنه حسان بن ثابت", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["الإجماع", "السنة", "الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 11, "title": "في المعني بقوله: ﴿والذي تولى كبره منهم﴾ الآية", "tabari": {"page": "17/193", "sarih": 1, "tarjih": "وأولى القولين في ذلك بالصواب قول من قال: الذي تولى كبره من عصبة الإفك، كان عبد الله بن أبي. وذلك أنه لا خلاف بين أهل العلم بالسير، أن الذي بدأ بذكر الإفك، وكان يجمع أهله ويحدثهم، عبد الله بن أبي ابن سلول، وفعله ذلك على ما وصفت، كان توليه كبر ذلك الأمر.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "هو حسان بن ثابت", "taqdim": 0, "n_athar": 3, "qailun": [["عامر", "تابعي"], ["مسروق", "تابعي"]], "athar": [52573, 52581]}, {"n": 2, "t": "هو عبد الله بن أبي ابن سلول", "taqdim": 0, "n_athar": 7, "qailun": [["عائشة", "صحابي"], ["ابن جريج", "تابع التابعين"], ["ابن زيد", "تابع التابعين"], ["مجاهد", "تابعي"]], "athar": [52523, 52524, 52530, 52531, 52539, 52540, 52541, 52544, 52545, 52559, 52567, 52575, 52580, 52585, 52593]}]}, "mawaqif": [], "mushid": {"i": 6, "imgs": ["024_006_1.png"], "pages": [379], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 23, "title": "في المحصنات اللاتى هذا حكمهن", "tabari": {"page": "17/226", "sarih": 1, "tarjih": "وأولى هذه الأقوال في ذلك عندى بالصواب قول من قال: نزلت هذه الآية في شأن عائشة، والحكم بها عام في كل من كان بالصفة التي وصفه الله بها فيها.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "إنما ذلك لعائشة خاصة، وحكم من الله فيها وفى من رماها، دون سائر نساء أمة نبينا ﷺ", "taqdim": 0, "n_athar": 2, "qailun": [], "athar": []}, {"n": 2, "t": "بل ذلك لأزواج رسول الله ﷺ خاصة دون سائر النساء غيرهن", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}, {"n": 3, "t": "نزلت هذه الآية في شأن عائشة، وعنى بها كل من كان بالصفة التي وصف الله في هذه الآية. قالوا: فذلك حكم كل من رمى محصنة لم تقارف سوءا", "taqdim": 0, "n_athar": 3, "qailun": [["جعفر بن برقان", "تابع التابعين"], ["ابن عباس", "صحابي"], ["ابن زيد", "تابع التابعين"]], "athar": [52729, 52730, 52731, 52741, 52742, 52746]}, {"n": 4, "t": "نزلت هذه الآية في أزواج النبي ﷺ، فكان ذلك كذلك حتى نزلت الآية التي في أول السورة، فأوجب الجلد وقبل التوبة", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [52729, 52730, 52731, 52742]}]}, "mawaqif": [{"taliq": 4620, "mi": 1, "aya": 23, "alam": "ابن كثير", "fil": "وجه", "kind": "توجيه", "ref": "10/ 199", "qawl": "الأول", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 4620, "mi": 1, "aya": 23, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 230", "qawl": "العموم", "nass": "لأن الله عم بقوله: {إن الذين يرمون المحصنات الغافلات المؤمنات} كل محصنة غافلة مؤمنة رماها رام بالفاحشة، من غير أن يخص بذلك بعضا دون بعض، فكل رام محصنة بالصفة التي ذكر الله -جل ثناؤه- في هذه الآية فملعون في الدنيا والآخرة، وله عذاب عظيم، إلا أن يتوب من ذنبه ذلك قبل وفاته", "qawaid": ["العموم"], "tabi": ""}, {"taliq": 4620, "mi": 1, "aya": 23, "alam": "ابن كثير", "fil": "رجحه", "kind": "ترجيح", "ref": "10/ 200", "qawl": "", "nass": "وهو الصحيح، ويعضد العموم ما رواه ابن أبي حاتم …", "qawaid": ["السنة"], "tabi": "ابن جرير"}, {"taliq": 4620, "mi": 1, "aya": 23, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 364 - 365", "qawl": "", "nass": "وعلى من قال: إن هذه الآية خاصة لعائشة. تترتب هذه الشدائد في جانب عبد الله بن أبي وأشباهه", "qawaid": [], "tabi": ""}, {"taliq": 4620, "mi": 1, "aya": 23, "alam": "ابن تيمية", "fil": "علق", "kind": "تعليق", "ref": "4/ 502 - 503", "qawl": "بالعموم بقوله", "nass": "هذا قول كثير من الناس، ووجه ظاهر الخطاب؛ فإنه عام، فيجب إجراؤه على عمومه، إذ لا موجب لخصوصه، وليس هو مختصا بنفس السبب بالاتفاق؛ لأن حكم غير عائشة من أزواج النبي صلى الله عليه وسلم داخل في العموم، وليس هو من السبب، ولأنه لفظ جمع، والسبب في واحدة؛ ولأن قصر عمومات القرآن على أسباب نزولها باطل، فإن عامة الآيات نزلت بأسباب اقتضت ذلك، وقد علم أن شيئا منها لم يقصر على سببه. والفرق بين الآيتين أنه في أول السورة ذكر العقوبات المشروعة على أيدي المكلفين من الجلد ورد الشهادة والتفسيق، وهنا ذكر العقوبة الواقعة من الله سبحانه، وهي اللعنة في الدارين والعذاب العظيم. وقد روي عن النبي صلى الله عليه وسلم من غير وجه وعن أصحابه أن قذف المحصنات من الكبائر، وفي لفظ في الصحيح: «قذف المحصنات الغافلات المؤمنات", "qawaid": [], "tabi": ""}], "mushid": {"i": 7, "imgs": ["024_007_1.png"], "pages": [379], "n": 4, "rajih": [3], "daif": [], "match": true}, "mawsua": {"taliq": 4620, "masala": "المعني بهذه الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "إنما ذلك لعائشة خاصة", "ashab": "", "athar": []}, {"n": 2, "t": "أزواج النبي صلى الله عليه وسلم خاصة", "ashab": "", "athar": []}, {"n": 3, "t": "نزلت هذه الآية في أزواج النبي صلى الله عليه وسلم، فكان ذلك كذلك حتى نزلت الآية التي في أول السورة فأوجب الجلد، وقبل التوبة", "ashab": "", "athar": []}, {"n": 4, "t": "نزلت في شأن عائشة، وهي عامة", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن كثير", "w"]], "4": [["ابن جرير", "r"]]}, "t": {"1": [["ابن كثير", "w"]], "3": [["ابن جرير", "r"]]}, "gen": [["ابن جرير", "رجّح العموم"], ["ابن كثير", "رجّح العموم"]], "rules": {"ابن جرير": ["العموم"], "ابن كثير": ["السنة"]}, "rulesD": {}}}, {"aya": 25, "title": "قراءة قوله: {يوفيهم الله دينهم الحق}", "mawsua": {"taliq": 4622, "masala": "قراءة قوله: {يوفيهم الله دينهم الحق}", "sigha": "حكاية خلاف", "nasib": "", "aqwal": [{"n": 1, "t": "{دينهم الحق} بالنصب", "ashab": "", "athar": []}, {"n": 2, "t": "{الحق} بالرفع", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 4622, "mi": 1, "aya": 25, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "17/ 231 - 232", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 4622, "mi": 1, "aya": 25, "alam": "ابن عطية", "fil": "وبنحوه", "kind": "موافقة", "ref": "6/ 366", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 4622, "mi": 1, "aya": 25, "alam": "ابن كثير", "fil": "وكذا", "kind": "موافقة", "ref": "10/ 202", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}, {"taliq": 4622, "mi": 1, "aya": 25, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 332", "qawl": "", "nass": "والصواب من القراءة في ذلك عندنا ما عليه قراء الأمصار، وهو نصب {الحق} على إتباعه إعراب الدين؛ لإجماع الحجة عليه", "qawaid": ["الإجماع"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["الإجماع"]}, "rulesD": {}}}, {"aya": 26, "title": "في تأويل ذلك ﴿الخبيثات للخبيثين والخبيثون للخبيثات والطيبات للطيبين والطيبون للطيبات أولئك مبرءون مما يق﴾", "tabari": {"page": "17/232", "sarih": 1, "tarjih": "وأولى هذه الأقوال في تأويل الآية قول من قال: عنى بالخبيثات: الخبيثات من القول، وذلك قبيحه وسيئه، للخبيثين من الرجال والنساء، والخبيثون من الناس للخبيثات من القول هم بها أولى؛ لأنهم أهلها، والطيبات من القول، وذلك حسنه وجميله، للطيبين من الناس، والطيبون من الناس للطيبات من القول؛ لأنهم أهلها وأحق بها.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه: الخبيثات من القول للخبيثين من الرجال، والخبيثون من الرجال للخبيثات من القول، والطيبات من القول للطيبين من الناس، والطيبون من الناس للطيبات من القول", "taqdim": 0, "n_athar": 10, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["الضحاك", "تابعي"], ["عطاء", "تابعي"]], "athar": [52776, 52777, 52778, 52779, 52782, 52783, 52784, 52785, 52791, 52792, 52796, 52802]}, {"n": 2, "t": "بل معنى ذلك: الخبيثات من النساء للخبيثين من الرجال، والخبيثون من الرجال للخبيثات من النساء", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [52799]}]}, "mawaqif": [{"taliq": 4624, "mi": 1, "aya": 26, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 238", "qawl": "الأول", "nass": "لأن الآيات قبل ذلك إنما جاءت بتوبيخ الله للقائلين في عائشة الإفك، والرامين المحصنات الغافلات المؤمنات، وإخبارهم ما خصهم به على إفكهم، فكان ختم الخبر عن أولى الفريقين بالإفك من الرامي والمرمي به أشبه من الخبر عن غيرهم", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 4624, "mi": 1, "aya": 26, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "6/ 366", "qawl": "الثاني", "nass": "فمعنى هذه: التفريق بين حكم عبد الله بن أبي وأشباهه وبين حكم النبي صلى الله عليه وسلم وفضلاء صحابته -رضوان الله عليهم- وأمته، أي: النبي صلى الله عليه وسلم طيب فلم يجعل الله له إلا كل طيبة، وأولئك خبيثون فهم أهل النساء الخبائث", "qawaid": [], "tabi": ""}, {"taliq": 4624, "mi": 1, "aya": 26, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "10/ 202 - 203", "qawl": "الثاني", "nass": "وهذا أيضا يرجع إلى ما قاله أولئك باللازم، أي: ما كان الله ليجعل عائشة زوجة لرسول الله صلى الله عليه وسلم إلا وهي طيبة؛ لأنه أطيب من كل طيب من البشر، ولو كانت خبيثة لما صلحت له لا شرعا ولا قدرا؛ ولهذا قال: {أولئك مبرؤون مما يقولون} أي: هم بعداء عما يقوله أهل الإفك والعدوان، {لهم مغفرة} أي: بسبب ما قيل فيهم من الكذب، {ورزق كريم} أي: عند الله في جنات النعيم. وفيه وعد بأن تكون زوجة النبي صلى الله عليه وسلم في الجنة", "qawaid": [], "tabi": ""}], "mushid": {"i": 8, "imgs": ["024_008_1.png"], "pages": [380], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 4624, "masala": "معنى قوله: {الطيبات للطيبين والطيبون للطيبات والخبيثات للخبيثين والخبيثون للخبيثات}", "sigha": "حكاية خلاف", "nasib": "", "aqwal": [{"n": 1, "t": "الخبيثات من القول للخبيثين من الرجال، والخبيثون من الرجال للخبيثات من القول، والطيبات من القول للطيبين من الناس، والطيبون من الناس للطيبات من القول", "ashab": "", "athar": []}, {"n": 2, "t": "الخبيثات من النساء للخبيثين من الرجال، والخبيثون من الرجال للخبيثات من النساء", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق"]}, "rulesD": {}}}, {"aya": 27, "title": "في ذلك ﴿ياأيها الذين آمنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا وتسلموا على أهلها ذلكم خير لكم ﴾", "tabari": {"page": "17/239", "sarih": 1, "tarjih": "والصواب من القول في ذلك عندى أن يقال: إن الاستئناس الاستفعال من الأنس، وهو أن يستأذن أهل البيت في الدخول عليهم، مخبرا بذلك من فيه، وهل فيه أحد، وليؤذنهم أنه داخل عليهم، فيأنس إلى إذنهم له في ذلك، ويأنسوا إلى استئذانه إياهم. وقد حكى عن العرب سماعا: اذهب فاستأنس، هل ترى أحدا في الدار؟ بمعنى: انظر هل ترى فيها أحدا؟", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "تأويله: يأيها الذين آمنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأذنوا", "taqdim": 0, "n_athar": 11, "qailun": [["ابن عباس", "صحابي"], ["الأعمش", "تابع التابعين"], ["إبراهيم", "تابعي"], ["ابن جريج", "تابع التابعين"], ["قتادة", "تابعي"], ["ابن مسعود", "صحابي"]], "athar": [52807, 52808, 52809, 52811, 52817, 52818, 52819, 52821, 52825, 52826, 52837, 52844, 52849, 52859, 52860]}, {"n": 2, "t": "معنى ذلك: حتى تؤنسوا أهل البيت بالتنحنح والتنخم وما أشبهه؛ حتى يعلموا أنكم تريدون الدخول عليهم", "taqdim": 0, "n_athar": 7, "qailun": [["مجاهد", "تابعي"], ["ابن جريج", "تابع التابعين"], ["زينب", "صحابي"], ["ابن زيد", "تابع التابعين"]], "athar": [52822, 52823, 52831, 52849, 52853, 52854, 52859, 52860]}]}, "mawaqif": [{"taliq": 4630, "mi": 0, "aya": 27, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 245 - 246", "qawl": "الأول", "nass": "والصواب من القول في ذلك عندي أن يقال: إن الاستئناس: الاستفعال من الأنس، وهو أن يستأذن أهل البيت في الدخول عليهم، مخبرا بذلك من فيه، وهل فيه أحد؟ وليؤذنهم أنه داخل عليهم، فليأنس إلى إذنهم له في ذلك، ويأنسوا إلى استئذانه إياهم، وقد حكي عن العرب سماعا: اذهب فاستأنس، هل ترى أحدا في الدار؟ بمعنى: انظر هل ترى فيها أحدا؟ فتأويل الكلام إذن إذا كان ذلك معناه: يا أيها الذين آمنوا، لا تدخلوا بيوتا غير بيوتكم حتى تسلموا وتستأذنوا، وذلك أن يقول أحدكم: السلام عليكم، أدخل؟ وهو من المقدم الذي معناه التأخير، إنما هو: حتى تسلموا وتستأذنوا، كما ذكرنا من الرواية عن ابن عباس", "qawaid": ["اللغة", "الدلالة العقلية"], "tabi": ""}, {"taliq": 4630, "mi": 0, "aya": 27, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "6/ 369", "qawl": "", "nass": "وتصريف الفعل يأبى أن يكون من أنس", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 4635, "mi": 0, "aya": 28, "alam": "ابن جرير", "fil": "انتقد", "kind": "نقد", "ref": "17/ 248 بتصرف", "qawl": "مجاهد مستندا", "nass": "وهذا القول الذي قاله مجاهد قول بعيد من مفهوم كلام العرب؛ لأن العرب لا تكاد تقول: ليس بمكان كذا أحد، إلا وهي تعني: ليس بها أحد من بني آدم. وأما الأمتعة وسائر الأشياء غير بني آدم ومن كان سبيله سبيلهم، فلا تقول ذلك فيها", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 4635, "mi": 0, "aya": 28, "alam": "ابن عطية", "fil": "انتقده", "kind": "نقد", "ref": "6/ 371", "qawl": "", "nass": "هو في غاية الضعف، وكأن مجاهدا رأى أن البيوت غير المسكونة إنما تدخل دون إذن. إذا كان فيها للداخل متاع، ورأى لفظة", "qawaid": [], "tabi": "ابن جرير"}], "mushid": {"i": 9, "imgs": ["024_009_1.png"], "pages": [380], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {"2": [["ابن جرير", "d"]]}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["اللغة", "الدلالة العقلية"]}, "rulesD": {"ابن عطية": ["اللغة"], "ابن جرير": ["اللغة"]}}}, {"aya": 29, "title": "تأويل: ﴿ليس عليكم جناح أن تدخلوا بيوتا غير مسكونة فيها متاع لكم والله يعلم ما تبدون وما تكتمون﴾", "tabari": {"page": "17/250", "sarih": 0, "tarjih": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله عم بقوله: ﴿ليس عليكم جناح أن تدخلوا بيوتا غير مسكونة فيها متاع لكم﴾ كل بيت لا ساكن به ، لنا فيه متاع، ندخله بغير إذن؛ لأن الإذن إنما يكون ليؤنس المأذون عليه قبل الدخول، أو ليأذن للداخل إن كان له مالكا، أو كان فيه ساكنا. فأما إن كان لا مالك له فيحتاج إلى إذنه لدخوله، ولا ساكن فيه فيحتاج الداخل إلى إيناسه والتسليم عليه؛ لئلا يهجم على ما لا يحب رؤيته منه - فلا معنى للاستئذان فيه. فإذ كان ذلك، فلا وجه لتخصيص بعض ذلك دون بعض، فكل بيت لا مالك له ولا ساكن من بيت مبني ببعض الطرق للمارة والسابلة ليأووا إليه، أو بيت خراب قد باد أهله ولا ساكن فيه حيث كان ذلك، فإن لمن أراد دخوله أن يدخل بغير استئذان لمتاع له يؤويه إليه، أو للاستمتاع به لقضاء حقه؛ من بول أو غائط أو غير ذلك. وأما بيوت التجار، فإنه ليس لأحد دخولها إلا بإذن أربابها وسكانها.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: ليس عليكم أيها الناس إثم وحرج أن تدخلوا بيوتا لا ساكن بها، بغير استئذان.", "taqdim": 1, "n_athar": 8, "qailun": [["محمد ابن الحنفية", ""], ["مجاهد", "تابعي"]], "athar": [52887, 52888, 52889, 52893, 52895, 52896, 52913]}, {"n": 2, "t": "هي بيوت مكة", "taqdim": 0, "n_athar": 1, "qailun": [["محمد ابن الحنفية في", ""]], "athar": []}, {"n": 3, "t": "هي البيوت الخربة، والمتاع التي قال الله فيها لكم، قضاء الحاجة؛ من الخلاء والبول فيها", "taqdim": 0, "n_athar": 2, "qailun": [["أبيه في هذه الآية", ""]], "athar": []}, {"n": 4, "t": "بل عنى بذلك بيوت التجار التي فيها أمتعة الناس", "taqdim": 0, "n_athar": 3, "qailun": [["ابن زيد", "تابع التابعين"], ["ابن جريج", "تابع التابعين"], ["عكرمة", "تابعي"]], "athar": [52910]}]}, "mawaqif": [{"taliq": 4639, "mi": 1, "aya": 29, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 252 - 253", "qawl": "العموم", "nass": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله عم بقوله: {ليس عليكم جناح أن تدخلوا بيوتا غير مسكونة فيها متاع لكم} كل بيت لا ساكن به لنا فيه متاع ندخله بغير إذن؛ لأن الإذن إنما يكون ليؤنس المأذون عليه قبل الدخول، أو ليأذن للداخل إن كان له مالكا، أو كان فيه ساكنا. فأما إن كان لا مالك له؛ فيحتاج إلى إذنه لدخوله، ولا ساكن فيه؛ فيحتاج الداخل إلى إيناسه، والتسليم عليه، لئلا يهجم على ما لا يحب رؤيته منه، فلا معنى للاستئذان فيه. فإذا كان ذلك فلا وجه لتخصيص بعض ذلك دون بعض، فكل بيت لا مالك له ولا ساكن من بيت مبني ببعض الطرق للمارة والسابلة ليأووا إليه، أو بيت خراب قد باد أهله ولا ساكن فيه حيث كان ذلك، فإن لمن أراد دخوله أن يدخل بغير استئذان لمتاع له يؤويه إليه، أو للاستمتاع به لقضاء حقه من بول أو غائط أو غير ذلك", "qawaid": ["العموم"], "tabi": ""}, {"taliq": 4639, "mi": 1, "aya": 29, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 371", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}], "mushid": {"i": 11, "imgs": ["024_011_1.png"], "pages": [380], "n": 4, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 4639, "masala": "البيوت التي عنتها الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "حوانيت التجار", "ashab": "", "athar": []}, {"n": 2, "t": "منازل الأسفار ومناخات الرجال التي يرتفق بها مارة الطريق في أسفارهم", "ashab": "", "athar": []}, {"n": 3, "t": "الخرابات العاطلات", "ashab": "", "athar": []}, {"n": 4, "t": "بيوت مكة", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح العموم"]], "rules": {"ابن جرير": ["العموم"]}, "rulesD": {}}}, {"aya": 31, "title": "تأويل: ﴿ولا يبدين زينتهن﴾", "tabari": {"page": "17/258", "sarih": 0, "tarjih": "وأولى الأقوال في ذلك بالصواب قول من قال: عنى بذلك الوجه والكفان. يدخل في ذلك إذا كان كذلك، الكحل والخاتم والسوار والخضاب [والثياب] .", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "﴿ولا يبدين زينتهن﴾. يقول تعالى ذكره: ولا يظهرن للناس الذين ليسوا لهن بمحرم زينتهن، وهما زينتان؛ إحداهما: ما خفى، وذلك كالخلخالين والسوارين والقرطين والقلائد. والأخرى: ما ظهر منها، وذلك مختلف في المعني منه بهذه الآية؛ فكان بعضهم يقول: زينة الثياب الظاهرة.", "taqdim": 1, "n_athar": 7, "qailun": [["ابن مسعود", "صحابي"], ["عبد الله", "صحابي"], ["الحسن", "تابعي"]], "athar": [52954, 52967, 52968, 52969, 52977, 52978, 52979, 52980, 52981, 52982, 52983, 52987, 53007, 53008, 53028, 53035, 53036, 53051, 53064, 53085, 53093, 53095, 53099, 53100, 53101, 53102, 53120, 53121, 53122, 53153, 53155, 53169, 53170]}, {"n": 2, "t": "الظاهر من الزينة التي أبيح لها أن تبديه: الكحل والخاتم والسواران والوجه", "taqdim": 0, "n_athar": 15, "qailun": [["ابن عباس", "صحابي"], ["سعيد بن جبير", "تابعي"], ["عطاء", "تابعي"], ["قتادة", "تابعي"], ["المسور بن مخرمة", "صحابي"], ["ابن جريج", "تابع التابعين"], ["عامر", "تابعي"], ["ابن زيد", "تابع التابعين"], ["الضحاك", "تابعي"]], "athar": [52954, 52955, 52960, 52973, 52974, 52977, 52978, 52979, 52980, 52981, 52982, 52987, 52988, 52994, 52995, 52996, 53002, 53006, 53011, 53012, 53019, 53024, 53028, 53029, 53036, 53037, 53043, 53044, 53046, 53051, 53052, 53057, 53062, 53065, 53072, 53073, 53074, 53078, 53085, 53090, 53091, 53093, 53094, 53096, 53098, 53099, 53100, 53101, 53102, 53108, 53109, 53117, 53118, 53119, 53123, 53124, 53138, 53140, 53151, 53155, 53156, 53158, 53160, 53162, 53170]}, {"n": 3, "t": "عنى به الوجه والثياب", "taqdim": 0, "n_athar": 2, "qailun": [["يونس", ""], ["الحسن", "تابعي"]], "athar": [53007, 53008, 53064, 53095, 53120, 53121, 53122]}]}, "mawaqif": [{"taliq": 4646, "mi": 1, "aya": 31, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 261 - 262", "qawl": "الأخير", "nass": "وأولى الأقوال في ذلك بالصواب قول من قال: عني بذلك: الوجه، والكفان، يدخل في ذلك إذا كان كذلك: الكحل، والخاتم، والسوار، والخضاب. وإنما قلنا ذلك أولى الأقوال في ذلك بالتأويل لإجماع الجميع على أن على كل مصل أن يستر عورته في صلاته، وأن للمرأة أن تكشف وجهها وكفيها في صلاتها، وأن عليها أن تستر ما عدا ذلك من بدنها، إلا ما روي عن النبي صلى الله عليه وسلم أنه أباح لها أن تبديه من ذراعها إلى قدر النصف؛ فإذ كان ذلك من جميعهم إجماعا كان معلوما بذلك أن لها أن تبدي من بدنها ما لم يكن عورة كما ذلك للرجال؛ لأن ما لم يكن عورة فغير حرام إظهاره. وإذا كان لها إظهار ذلك كان معلوما أنه مما استثناه الله -تعالى ذكره- بقوله: {إلا ما ظهر منها}؛ لأن كل ذلك ظاهر منها", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 4646, "mi": 1, "aya": 31, "alam": "ابن تيمية", "fil": "انتقد", "kind": "نقد", "ref": "الفتاوى 22/ 109، 115", "qawl": "", "nass": "إن طائفة من الفقهاء ظنوا أن الذي يستر في الصلاة هو الذي يستر عن أعين الناظرين، وهو العورة، وأخذوا ما يستر في الصلاة من قوله: {ولا يبدين زينتهن إلا ما ظهر منها وليضربن بخمرهن على جيوبهن ولا يبدين زينتهن إلا لبعولتهن} الآية … يسمون ذلك: باب ستر العورة، وليس هذا من ألفاظ الرسول ولا في الكتاب والسنة أن ما يستره المصلي فهو عورة، بل قال تعالى: {خذوا زينتكم عند كل مسجد} [الأعراف: 31]", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "mushid": {"i": 12, "imgs": ["024_012_1.png"], "pages": [381], "n": 3, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 4646, "masala": "الزينة الظاهرة", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "هي الثياب", "ashab": "", "athar": []}, {"n": 2, "t": "الكحل، والخاتم، والسواران، والوجه", "ashab": "", "athar": []}, {"n": 3, "t": "الوجه، والكفان", "ashab": "", "athar": []}]}, "tags": {"m": {"3": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية"]}, "rulesD": {"ابن تيمية": ["الدلالة العقلية"]}}}, {"aya": 31, "title": "في تأويل ذلك ﴿أو ما ملكت أيمانهن﴾", "tabari": {"page": "17/265", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "أو مماليكهن، فإنه لا بأس عليها أن تظهر لهم من زينتها ما تظهره لهؤلاء", "taqdim": 0, "n_athar": 1, "qailun": [["ابن جريج", "تابع التابعين"]], "athar": [52973, 52974, 53057, 53072, 53073, 53078]}, {"n": 2, "t": "بل معنى ذلك: أو ما ملكت أيمانهن من إماء المشركين. كما قد ذكرنا عن ابن جريج قبل، من أنه لما قال: ﴿أو نسائهن﴾ عنى بهن النساء المسلمات دون المشركات. ثم قال: أو ما ملكت أيمانهن من الإماء المشركات", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 13, "imgs": ["024_013_1.png"], "pages": [381], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 33, "title": "في وجه مكاتبة الرجل عبده الذي قد علم فيه خيرا، وهل قوله: ﴿فكاتبوهم إن علمتم فيهم خيرا﴾ على وجه الفرض، أم هو على وجه الندب", "tabari": {"page": "17/276", "sarih": 1, "tarjih": "وأولى هذه الأقوال بالصواب في معنى ذلك عندى قول من قال: معناه: ﴿فكاتبوهم إن علمتم فيهم خيرا﴾ أي: قوة على الاحتراف والاكتساب، ووفاء بما أوجب على نفسه وألزمها، وصدق لهجة. وذلك أن هذه المعانى هي الأسباب التي بمولى العبد الحاجة إليها إذا كاتب عبده، مما يكون في العبد؛ فأما المال وإن كان من الخير، فإنه لا يكون في العبد، وإنما يكون عنده أو له، لا فيه، والله إنما أوجب علينا مكاتبة العبد إذا علمنا فيه خيرا، لا إذا علمنا عنده أو له، فلذلك لم نقل: إن الخير في هذا الموضع معني به المال.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "فرض على الرجل أن يكاتب عبده الذي قد علم فيه خيرا، إذا سأله العبد ذلك", "taqdim": 0, "n_athar": 3, "qailun": [["أنس بن مالك", "صحابي"], ["ابن عباس", "صحابي"]], "athar": [53199, 53208, 53209, 53226, 53227, 53228, 53283, 53286, 53287, 53334, 53335, 53349, 53358, 53368, 53370]}, {"n": 2, "t": "ذلك غير واجب على السيد، وإنما قوله: ﴿فكاتبوهم﴾ ندب من الله سادة العبيد إلى كتابة من علم فيه منهم خيرا، لا إيجاب", "taqdim": 0, "n_athar": 7, "qailun": [["مالك بن أنس", "تابع التابعين"], ["ابن زيد", "تابع التابعين"], ["ابن عمر", "صحابي"], ["ابن عباس", "صحابي"], ["قوله", ""], ["أبيه قول الله", ""]], "athar": [53199, 53209, 53217, 53218, 53226, 53227, 53228, 53229, 53269, 53283, 53286, 53287, 53290, 53315, 53321, 53326, 53334, 53335, 53349, 53358, 53368, 53370, 53380]}, {"n": 3, "t": "بل معنى ذلك: إن علمتم فيهم صدقا ووفاء وأداء", "taqdim": 0, "n_athar": 7, "qailun": [["الحسن", "تابعي"], ["أبي صالح", "تابعي"], ["المغيرة", ""], ["عطاء", "تابعي"], ["عمرو بن دينار", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [53218, 53233, 53249, 53250, 53251, 53254, 53256, 53257, 53261, 53269, 53297, 53298, 53299, 53301, 53305, 53315, 53373, 53376, 53380]}, {"n": 4, "t": "بل معني ذلك: إن علمتم لهم مالا", "taqdim": 0, "n_athar": 10, "qailun": [["ابن عباس", "صحابي"], ["ابن جريج", "تابع التابعين"], ["مجاهد", "تابعي"], ["عطاء بن أبي رباح", "تابعي"]], "athar": [53199, 53209, 53212, 53222, 53225, 53226, 53227, 53228, 53241, 53242, 53243, 53244, 53256, 53257, 53259, 53283, 53286, 53287, 53294, 53295, 53296, 53297, 53301, 53334, 53335, 53336, 53337, 53349, 53350, 53358, 53368, 53370, 53371]}]}, "mawaqif": [{"taliq": 4655, "mi": 0, "aya": 33, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 278", "qawl": "الأول", "nass": "وذلك أن ظاهر قوله: {فكاتبوهم} ظاهر أمر، وأمر الله فرض الانتهاء إليه، ما لم يكن دليل من كتاب أو سنة على أنه ندب", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}], "mushid": {"i": 14, "imgs": ["024_014_1.png"], "pages": [381], "n": 2, "rajih": [], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["ظاهر الآية ولفظها"]}, "rulesD": {}}}, {"aya": 33, "title": "في المأمور بإعطائه من مال الله الذي أعطاه", "tabari": {"page": "17/283", "sarih": 1, "tarjih": "وأولى القولين بالصواب في ذلك عندى القول الثاني، وهو قول من قال: عنى به إيتاءهم سهمهم من الصدقة المفروضة.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "الذي أمر بإعطاء المكاتب من مال الله هو مولى العبد المكاتب، ومال الله الذي أمر بإعطائه منه هو مال الكتابة، والقدر الذي أمر أن يعطيه منه الربع. وقال آخرون: بل ما شاء من ذلك المولى", "taqdim": 0, "n_athar": 15, "qailun": [["علي", "صحابي"], ["عبد الملك بن أعين", ""], ["أبي عبد الرحمن السلمي", "تابعي"], ["ابن عباس", "صحابي"], ["عطاء", "تابعي"], ["مجاهد", "تابعي"], ["سعيد بن جبير", "تابعي"], ["نافع", "تابعي"]], "athar": [53199, 53206, 53209, 53223, 53224, 53225, 53226, 53227, 53228, 53237, 53241, 53242, 53243, 53244, 53256, 53257, 53272, 53275, 53280, 53282, 53283, 53284, 53286, 53287, 53288, 53289, 53294, 53295, 53296, 53297, 53301, 53305, 53333, 53334, 53335, 53336, 53337, 53349, 53350, 53358, 53359, 53366, 53368, 53369, 53370, 53371, 53376]}, {"n": 2, "t": "بل ذلك حض من الله أهل الأموال على أن يعطوهم سهمهم الذي جعله الله لهم من الصدقات المفروضة لهم في أموالهم بقوله: ﴿إنما الصدقات للفقراء والمساكين والعاملين عليها والمؤلفة قلوبهم وفي الرقاب﴾ [التوبة: ٦٠]. قال: فالرقاب التي جعل فيها أحد سهمان الصدقة الثمانية هم المكاتبون. قال: وإياه عنى جل ثناؤه بقوله: ﴿وآتوهم من مال الله الذي آتاكم﴾. أي: سهمهم من الصدقة", "taqdim": 0, "n_athar": 6, "qailun": [["الحسن", "تابعي"], ["إبراهيم", "تابعي"]], "athar": [53232, 53240, 53249, 53250, 53251, 53254, 53293, 53298, 53299, 53373]}]}, "mawaqif": [{"taliq": 4659, "mi": 0, "aya": 33, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 289 بتصرف", "qawl": "الثاني", "nass": "لأن قوله: {وآتوهم من مال الله الذي آتاكم} أمر من الله -تعالى ذكره- بإيتاء المكاتبين من ماله الذي آتى أهل الأموال، وأمر الله فرض على عباده الانتهاء إليه، ما لم يخبرهم أن مراده الندب … فإذ كان ذلك كذلك، ولم يكن أخبرنا في كتابه ولا على لسان رسوله صلى الله عليه وسلم أنه ندب؛ ففرض واجب. وإذ كان ذلك كذلك، وكانت الحجة قد قامت أن لا حق لأحد في مال أحد غيره من المسلمين إلا ما أوجبه الله لأهل سهمان الصدقة في أموال الأغنياء منهم، وكانت الكتابة التي يقتضيها سيد المكاتب من مكاتبه مالا من مال سيد المكاتب؛ فيفاد أن الحق الذي أوجب الله له على المؤمنين أن يؤتوه من أموالهم هو ما فرض على الأغنياء في أموالهم له من الصدقة المفروضة، إذ كان لا حق في أموالهم لأحد سواها", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 4659, "mi": 0, "aya": 33, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "10/ 230", "qawl": "الأول", "nass": "", "qawaid": [], "tabi": ""}], "mushid": {"i": 16, "imgs": ["024_016_1.png", "024_016_2.png"], "pages": [381, 382], "n": 3, "rajih": [3], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 33, "title": "الخير الذي أمر الله تعالى عباده بكتابة عبيدهم إذا علموه فيهم", "mawsua": {"taliq": 4657, "masala": "الخير الذي أمر الله تعالى عباده بكتابة عبيدهم إذا علموه فيهم", "sigha": "حكاية خلاف", "nasib": "", "aqwal": [{"n": 1, "t": "فهو القدرة على الاحتراف والكسب", "ashab": "", "athar": []}, {"n": 2, "t": "الوفاء والصدق", "ashab": "", "athar": []}, {"n": 3, "t": "المال", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 4657, "mi": 1, "aya": 33, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 282", "qawl": "", "nass": "وأولى هذه الأقوال في معنى ذلك عندي قول من قال: معناه: فكاتبوهم إن علمتم فيهم قوة على الاحتراف والاكتساب، ووفاء بما أوجب على نفسه وألزمها، وصدق لهجة. وذلك أن هذه المعاني هي الأسباب التي بمولى العبد الحاجة إليها إذا كاتب عبده، مما يكون في العبد؛ فأما المال وإن كان من الخير فإنه لا يكون في العبد، وإنما يكون عنده أو له، لا فيه، والله إنما أوجب علينا مكاتبة العبد إذا علمنا فيه خيرا، لا إذا علمنا عنده أو له، فلذلك لم نقل: إن الخير في هذا الموضع معني به: المال", "qawaid": ["الدلالة العقلية", "اللغة"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["الدلالة العقلية", "اللغة"]}, "rulesD": {}}}, {"aya": 35, "title": "في تأويل ذلك ﴿الله نور السماوات والأرض مثل نوره كمشكاة فيها مصباح المصباح في زجاجة الزجاجة كأنها كوكب در﴾", "tabari": {"page": "17/295", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "بل معنى ذلك: الله مدبر السماوات والأرض", "taqdim": 0, "n_athar": 1, "qailun": [["ابن جريج", "تابع التابعين"]], "athar": [53476]}, {"n": 2, "t": "بل عنى بذلك النور الضياء. وقالوا: معنى ذلك: ضياء السماوات والأرض", "taqdim": 0, "n_athar": 1, "qailun": [["أبي بن كعب", "صحابي"]], "athar": [53402, 53415, 53416, 53433, 53435, 53454, 53477, 53497, 53510, 53553]}]}, "mawaqif": [{"taliq": 4662, "mi": 1, "aya": 35, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 297", "qawl": "الأول", "nass": "وإنما اخترنا القول الذي اخترناه في ذلك لأنه عقيب قوله: {ولقد أنزلنا إليكم آيات مبينات ومثلا من الذين خلوا من قبلكم وموعظة للمتقين} [النور: 34]، فكان ذلك بأن يكون خبرا عن موقع يقع تنزيله من خلقه، ومن مدح ما ابتدأ بذكر مدحه؛ أولى وأشبه، ما لم يأت ما يدل على انقضاء الخبر عنه من غيره. فإذا كان ذلك كذلك فتأويل الكلام: ولقد أنزلنا إليكم أيها الناس آيات مبينات الحق من الباطل، {ومثلا من الذين خلوا من قبلكم وموعظة للمتقين} فهديناكم بها، وبينا لكم معالم دينكم بها؛ لأني هادي أهل السماوات وأهل الأرض", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 4662, "mi": 1, "aya": 35, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "2/ 241", "qawl": "ابن مسعود", "nass": "وهذا الذي قاله ابن مسعود? أقرب إلى تفسير الآية من قول من فسرها بأنه هادي أهل السماوات والأرض. وأما من فسرها بأنه منور السماوات والأرض؛ فلا تنافي بينه وبين قول ابن مسعود، والحق أنه نور السماوات والأرض بهذه الاعتبارات كلها", "qawaid": [], "tabi": ""}, {"taliq": 4662, "mi": 1, "aya": 35, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 384 - 385", "qawl": "", "nass": "النور في كلام العرب: الأضواء المدركة بالبصر. ويستعمل مجازا فيما صح من المعاني ولاح، فيقال: كلام له نور … والله تعالى ليس كمثله شيء، فبين أنه ليس كالأضواء المدركة، ولم يبق للآية معنى إلا أنه أراد: الله ذو نور السماوات والأرض، أي: بقدرته أنارت أضواؤها، واستقامت أمورها، وقامت مصنوعاتها، فالكلام على التقريب للذهن، كما تقول: الملك نور الأمة، أي: به قوام أمورها وصلاح جملتها، والأمر في الملك مجاز، وهو في صفة الله تعالى حقيقة محضة؛ إذ هو الذي أبدع الموجودات، وخلق العقل نورا هاديا؛ لأن ظهور الوجود به حصل كما حصل بالضوء ظهور المبصرات، تبارك الله لا رب سواه. وقالت فرقة: التقدير: دين الله نور السماوات والأرض. قال ابن عباس: هادي أهل السماوات والأرض. والأول أعم للمعاني وأوضح مع التأمل", "qawaid": [], "tabi": ""}], "mushid": {"i": 17, "imgs": ["024_017_1.png"], "pages": [382], "n": 3, "rajih": [1], "daif": [], "match": false}, "mawsua": {"taliq": 4662, "masala": "تفسير قوله: {الله نور السموات والأرض}", "sigha": "حكاية خلاف", "nasib": "", "aqwal": [{"n": 1, "t": "هادي السماوات والأرض", "ashab": "", "athar": []}, {"n": 2, "t": "مدبر السماوات والأرض", "ashab": "", "athar": []}, {"n": 3, "t": "ضياء السماوات والأرض", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["السياق"]}, "rulesD": {}}}, {"aya": 35, "title": "في المعني بالهاء في قوله: ﴿مثل نوره﴾. علام عائدة، ومن ذكر ما هي", "tabari": {"page": "17/297", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "هي من ذكر المؤمن. وقالوا: معنى الكلام: مثل نور المؤمن الذي في قلبه من الإيمان والقرآن مثل مشكاة", "taqdim": 0, "n_athar": 4, "qailun": [["أبي بن كعب", "صحابي"], ["سعيد بن جبير", "تابعي"], ["الضحاك", "تابعي"]], "athar": [53402, 53409, 53415, 53416, 53423, 53430, 53433, 53435, 53442, 53443, 53444, 53445, 53454, 53465, 53466, 53477, 53497, 53501, 53510, 53514, 53525, 53529, 53547, 53553]}, {"n": 2, "t": "بل عنى بالنور محمد ﷺ. وقالوا: الهاء التي في قوله: ﴿مثل نوره﴾. عائدة على اسم الله", "taqdim": 0, "n_athar": 2, "qailun": [["شمر", ""], ["سعيد بن جبير", "تابعي"]], "athar": [53408, 53430, 53441, 53442, 53443, 53463, 53465, 53525, 53547]}, {"n": 3, "t": "بل عنى بذلك هدى الله وبيانه، وهو القرآن. قالوا: والهاء من ذكر الله. قالوا: ومعنى الكلام: الله هادى أهل السماوات والأرض بآياته المبينات، وهى النور الذي استنار به السماوات والأرض، مثل هداه وآياته التي هدى بها خلقه، ووعظهم بها في قلوب المؤمنين - كمشكاة", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["الحسن", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [53403, 53404, 53405, 53406, 53410, 53411, 53418, 53419, 53421, 53428, 53434, 53436, 53437, 53438, 53439, 53440, 53447, 53452, 53455, 53456, 53457, 53458, 53459, 53471, 53478, 53487, 53498, 53502, 53511, 53512, 53516, 53518, 53519, 53520, 53521, 53522, 53531, 53539, 53543, 53544, 53545, 53551, 53554, 53555]}, {"n": 4, "t": "بل معنى ذلك: مثل نور الله. وقالوا: يعنى بالنور الطاعة", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [53403, 53404, 53405, 53406, 53419, 53421, 53428, 53434, 53436, 53437, 53438, 53439, 53440, 53455, 53456, 53457, 53458, 53459, 53478, 53487, 53498, 53511, 53512, 53516, 53518, 53519, 53520, 53521, 53522, 53543, 53544, 53545, 53554, 53555]}]}, "mawaqif": [{"taliq": 4663, "mi": 1, "aya": 35, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 307", "qawl": "الثاني", "nass": "وأولى الأقوال في ذلك بالصواب قول من قال: ذلك مثل ضربه الله للقرآن في قلب أهل الإيمان به، فقال: مثل نور الله الذي أنار به لعباده سبيل الرشاد، الذي أنزله إليهم، فآمنوا به، وصدقوا بما فيه في قلوب المؤمنين، مثل مشكاة، وهي عمود القنديل الذي فيه الفتيلة، وذلك هو نظير الكوة التي تكون في الحيطان التي لا منفذ لها. وإنما جعل ذلك العمود مشكاة لأنه غير نافذ، وهو أجوف، مفتوح الأعلى، فهو كالكوة التي في الحائط التي لا تنفذ. ثم قال: {فيها مصباح} وهو السراج، وجعل السراج، وهو المصباح مثلا لما في قلب المؤمن من القرآن والآيات المبينات. ثم قال: {المصباح في زجاجة}، يعني: أن السراج الذي في المشكاة في القنديل، وهو الزجاجة، وذلك مثل للقرآن، يقول: القرآن الذي في قلب المؤمن الذي أنار الله قلبه في صدره. ثم مثل الصدر -في خلوصه من الكفر بالله، والشك فيه، واستنارته بنور القرآن، واستضاءته بآيات ربه المبينات، ومواعظه فيها- بالكوكب الدري، فقال: {الزجاجة} وذلك صدر المؤمن الذي فيه قلبه {كأنها كوكب دري}", "qawaid": [], "tabi": ""}, {"taliq": 4663, "mi": 1, "aya": 35, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "6/ 386 - 387", "qawl": "", "nass": "وهذه أقوال فيها عود الضمير على من لم يجر له ذكر، وفيها تقطع المعنى المراد بالآية", "qawaid": [], "tabi": ""}], "mushid": {"i": 18, "imgs": ["024_018_1.png"], "pages": [382], "n": 4, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 4663, "masala": "عود الضمير من قوله: {مثل نوره}", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "أنه عائد على المؤمن، والمعنى: مثل نور المؤمن", "ashab": "", "athar": []}, {"n": 2, "t": "أنه عائد على القرآن، والمعنى: مثل نور القرآن", "ashab": "", "athar": []}, {"n": 3, "t": "أنه عائد على النبي، والمعنى: مثل نور محمد صلى الله عليه وسلم", "ashab": "", "athar": []}, {"n": 4, "t": "أنه عائد على اسم الله تعالى، والمعنى: مثل نور الله", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"]]}, "t": {"3": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 35, "title": "في معنى \"المشكاة\" و \"المصباح\"، وما المراد بذلك، وبالزجاجة", "tabari": {"page": "17/301", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب قول من قال: ذلك مثل ضربه الله للقرآن في قلب أهل الإيمان به، فقال: مثل نور الله الذي أثار به لعباده سبيل الرشاد، الذي أنزله إليهم فآمنوا به وصدقوا بما فيه، في قلوب المؤمنين - مثل مشكاة؛ وهى عمود القنديل الذي فيه الفتيلة، وذلك هو نظير الكوة التي تكون في الحيطان التي لا منفذ لها، وإنما جعل ذلك العمود مشكاة؛ لأنه غير نافذ وهو أجوف مفتوح الأعلى، فهو كالكوة التي في الحائط التي لا تنفذ، ثم قال: ﴿فيها مصباح﴾. وهو السراج، وجعل السراج، وهو المصباح، مثلا لما في قلب المؤمن من القرآن والآيات المبينات. ثم قال: ﴿المصباح في زجاجة﴾. يعنى أن السراج الذي في المشكاة في القنديل، وهو الزجاجة، وذلك مثل للقرآن. يقول: القرآن الذي في قلب المؤمن الذي أنار الله به قلبه في صدره. ثم مثل الصدر في خلوصه من الكفر بالله والشك فيه، واستنارته بنور القرآن، واستضاءته بآيات ربه المبينات، ومواعظه فيها - بالكوكب الدري، فقال: الزجاجة. وذلك صدر المؤمن الذي فيه قلبه ﴿كأنها كوكب دري﴾.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "المشكاة كل كوة لا منفذ لها. وقالوا: هذا مثل ضربه الله لقلب محمد ﷺ", "taqdim": 0, "n_athar": 3, "qailun": [["شمر", ""], ["ابن عباس", "صحابي"]], "athar": [53403, 53404, 53405, 53406, 53408, 53419, 53421, 53428, 53434, 53436, 53437, 53438, 53439, 53440, 53441, 53455, 53456, 53457, 53458, 53459, 53463, 53478, 53487, 53498, 53511, 53512, 53516, 53518, 53519, 53520, 53521, 53522, 53543, 53544, 53545, 53554, 53555]}, {"n": 2, "t": "عنى بالمشكاة صدر المؤمن، وبالمصباح القرآن والإيمان، وبالزجاجة قلبه", "taqdim": 0, "n_athar": 4, "qailun": [["أبي بن كعب", "صحابي"], ["ابن عباس", "صحابي"]], "athar": [53402, 53403, 53404, 53405, 53406, 53415, 53416, 53419, 53421, 53428, 53433, 53434, 53435, 53436, 53437, 53438, 53439, 53440, 53454, 53455, 53456, 53457, 53458, 53459, 53477, 53478, 53487, 53497, 53498, 53510, 53511, 53512, 53516, 53518, 53519, 53520, 53521, 53522, 53543, 53544, 53545, 53553, 53554, 53555]}, {"n": 3, "t": "هو مثل للمؤمن، غير أن المصباح وما فيه مثل لفؤاده، والمشكاة مثل لجوفه", "taqdim": 0, "n_athar": 1, "qailun": [["ابن جريج", "تابع التابعين"]], "athar": [53476]}, {"n": 4, "t": "بل ذلك مثل للقرآن في قلب المؤمن", "taqdim": 0, "n_athar": 4, "qailun": [["الحسن", "تابعي"], ["ابن زيد", "تابع التابعين"], ["سعيد بن عياض", ""], ["عطية", "تابعي"]], "athar": [53410, 53411, 53418, 53447, 53452, 53471, 53502, 53531, 53532, 53539, 53551]}, {"n": 5, "t": "المشكاة القنديل", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"]], "athar": [53420, 53467, 53468, 53469, 53481, 53488, 53491, 53517, 53528, 53558]}, {"n": 6, "t": "المشكاة الحديد الذي يعلق به القنديل", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [53420, 53467, 53468, 53469, 53481, 53488, 53491, 53517, 53528, 53558]}]}, "mawaqif": [{"taliq": 4664, "mi": 1, "aya": 35, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 307", "qawl": "الثاني", "nass": "", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 4664, "mi": 1, "aya": 35, "alam": "ابن كثير", "fil": "وكذا", "kind": "موافقة", "ref": "6/ 58 بتصرف", "qawl": "", "nass": "", "qawaid": ["السياق"], "tabi": "ابن جرير"}, {"taliq": 4664, "mi": 1, "aya": 35, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "قوله: {كمشكاة} قال ابن عباس، ومجاهد، ومحمد بن كعب، وغير واحد: هو موضع الفتيلة من القنديل. هذا هو المشهور، وهو الأولى؛ ولهذا قال بعده: {فيها مصباح}", "qawaid": [], "tabi": ""}, {"taliq": 4664, "mi": 1, "aya": 35, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "6/ 387 بتصرف", "qawl": "الأول", "nass": "والمشكاة: الكوة في الحائط غير النافذة. قاله ابن جبير، وسعيد بن عياض، وجمهور المفسرين، وهي أجمع للضوء، والمصباح فيها أكثر إنارة من غيرها، فهذا أصح الأقوال", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "mushid": {"i": 19, "imgs": ["024_019_1.png", "024_019_2.png"], "pages": [382, 383], "n": 6, "rajih": [4], "daif": [], "match": true}, "mawsua": {"taliq": 4664, "masala": "تفسير قوله: {كمشكاة}", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "كوة لا منفذ لها", "ashab": "", "athar": []}, {"n": 2, "t": "موضع الفتيلة من القنديل", "ashab": "", "athar": []}, {"n": 3, "t": "الحديد الذي به القنديل", "ashab": "", "athar": []}, {"n": 4, "t": "صدر المؤمن", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"], ["ابن كثير", "r"]], "1": [["ابن عطية", "r"]]}, "t": {"1": [["ابن عطية", "r"]], "4": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق"], "ابن كثير": ["السياق"], "ابن عطية": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 35, "title": "في قراءة قوله: ﴿يوقد من شجرة مباركة﴾", "tabari": {"page": "17/309", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "بل معنى ذلك: ليست شرقية ولا غربية", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"], ["ابن زيد", "تابع التابعين"]], "athar": [53403, 53404, 53405, 53406, 53411, 53419, 53421, 53428, 53434, 53436, 53437, 53438, 53439, 53440, 53452, 53455, 53456, 53457, 53458, 53459, 53478, 53487, 53498, 53511, 53512, 53516, 53518, 53519, 53520, 53521, 53522, 53539, 53543, 53544, 53545, 53551, 53554, 53555]}, {"n": 2, "t": "ليست هذه الشجرة من شجر الدنيا", "taqdim": 0, "n_athar": 3, "qailun": [["الحسن", "تابعي"]], "athar": [53410, 53418, 53447, 53471, 53502, 53531]}]}, "mawaqif": [{"taliq": 4665, "mi": 0, "aya": 35, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "17/ 310", "qawl": "", "nass": "وكأن الذين ضموا داله وتركوا الهمزة وجهوا معناه إلى ما قاله أهل التفسير الذي ذكرنا عنهم، من أن الزجاجة في صفائها وحسنها كالدر، وأنها منسوبة إليه لذلك من نعتها وصفتها. ووجه الذين قرؤوا ذلك بكسر داله وهمزه إلى أنه (فعيل) من درأ الكوكب، أي: دفع ورجم به الشيطان، من قوله: {ويدرأ عنها العذاب} [النور: 8]، أي: يدفع، والعرب تسمي الكواكب العظام التي لا تعرف أسماءها: الدراري، بغير همز … وأما الذين قرؤوه بضم داله وهمزه فإن كانوا أرادوا به دروء، مثل: سبوح، وقدوس، من درأت، ثم استثقلوا كثرة الضمات فيه، فصرفوا بعضها إلى الكسرة، فقالوا: دريء، كما قيل: {وقد بلغت من الكبر عتيا} [مريم: 8]، وهو فعول، من عتوت عتوا، ثم حولت بعض ضماتها إلى الكسر، فقيل: عتيا؛ فهو مذهب، وإلا فلا أعرف لصحة قراءتهم ذلك كذلك وجها، وذلك أنه لا يعرف في كلام العرب: فعيل", "qawaid": ["أقوال السلف"], "tabi": ""}, {"taliq": 4665, "mi": 0, "aya": 35, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "6/ 387", "qawl": "", "nass": "ولهذه القراءة وجهان: إما أن ينسب الكوكب إلى الدر لبياضه وصفائه، وإما أن يكون أصله: دريء -مهموز- من الدرء، وهو الدفع، وخففت الهمزة", "qawaid": [], "tabi": ""}, {"taliq": 4666, "mi": 0, "aya": 35, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "17/ 310", "qawl": "", "nass": "وهذه القراءات متقاربات المعاني، وإن اختلفت الألفاظ بها؛ وذلك أن الزجاجة إذا وصفت بالتوقد أو بأنها توقد، فمعلوم معنى ذلك، فإن المراد به: توقد فيها المصباح، أو يوقد فيها المصباح، ولكن وجهوا الخبر إلى أن وصفها بذلك أقرب في الكلام منها، وفهم السامعين معناه، والمراد منه. فإذا كان ذلك كذلك فبأي القراءات قرأ القارئ فمصيب", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 4669, "mi": 0, "aya": 35, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 313", "qawl": "الثاني", "nass": "وأولى هذه الأقوال بتأويل ذلك قول من قال: إنها شرقية غربية. وقال: ومعنى الكلام: ليست شرقية تطلع عليها الشمس بالعشي، دون الغداة، ولكن الشمس تشرق عليها وتغرب، فهي شرقية غربية. وإنما قلنا ذلك أولى بمعنى الكلام لأن الله إنما وصف الزيت الذي يوقد على هذا المصباح بالصفاء والجودة، فإذا كان شجره شرقيا غربيا كان زيته لا شك أجود وأصفى وأضوأ", "qawaid": ["الدلالة العقلية", "السياق"], "tabi": ""}, {"taliq": 4669, "mi": 0, "aya": 35, "alam": "ابن كثير", "fil": "وبنحوه", "kind": "موافقة", "ref": "6/ 60", "qawl": "", "nass": "وأولى هذه الأقوال القول الأول، وهو أنها في مستوى من الأرض، في مكان فسيح بارز ظاهر ضاح للشمس، تفرعه من أول النهار إلى آخره، ليكون ذلك أصفى لزينتها وألطف؛ ولهذا قال: {يكاد زيتها يضيء ولو لم تمسسه نار}. قال عبد الرحمن بن زيد بن أسلم: يعني: لضوء إشراق الزيت", "qawaid": ["السياق"], "tabi": "ابن جرير"}], "mushid": {"i": 20, "imgs": ["024_020_1.png"], "pages": [383], "n": 3, "rajih": [1], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["الدلالة العقلية", "السياق"], "ابن كثير": ["السياق"]}, "rulesD": {}}}, {"aya": 36, "title": "في تأويل قوله: ﴿أذن الله أن ترفع﴾", "tabari": {"page": "17/318", "sarih": 1, "tarjih": "وأولى القولين في ذلك عندى بالصواب القول الذي قاله مجاهد، وهو أن معناه: أذن الله أن ترفع بناء. كما قال جل ثناؤه: ﴿وإذ يرفع إبراهيم القواعد من البيت﴾ [البقرة: ١٢٧]. وذلك أن ذلك هو الأغلب من معنى الرفع في البيوت والأبنية.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "معناه: أذن الله أن تبنى", "taqdim": 0, "n_athar": 2, "qailun": [["مجاهد", "تابعي"]], "athar": [53577, 53578, 53588]}, {"n": 2, "t": "معناه: أذن الله أن تعظم", "taqdim": 0, "n_athar": 1, "qailun": [["الحسن", "تابعي"]], "athar": [53581, 53582, 53590, 53614]}]}, "mawaqif": [{"taliq": 4673, "mi": 1, "aya": 36, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 318", "qawl": "الأول", "nass": "وأولى القولين في ذلك عندي بالصواب القول الذي قاله مجاهد، وهو أن معناه: أذن الله أن ترفع بناء، كما قال -جل ثناؤه-: {وإذ يرفع إبراهيم القواعد من البيت} [البقرة: 127]، وذلك أن ذلك هو الأغلب من معنى الرفع في البيوت والأبنية", "qawaid": ["القرآن والنظائر", "اللغة"], "tabi": ""}, {"taliq": 4673, "mi": 1, "aya": 36, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "6/ 390 - 391", "qawl": "الأول", "nass": "و {ترفع} قيل: معناه: تبنى وتعلى. قاله مجاهد وغيره، فذلك كنحو قوله تعالى: {وإذ يرفع إبراهيم القواعد} [البقرة: 127]، وقال رسول الله صلى الله عليه وسلم: «من بنى مسجدا من ماله بنى الله له بيتا في الجنة", "qawaid": [], "tabi": ""}], "mushid": {"i": 22, "imgs": ["024_022_1.png"], "pages": [383], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 4673, "masala": "تفسير قوله: {أذن الله أن ترفع}", "sigha": "حكاية خلاف", "nasib": "", "aqwal": [{"n": 1, "t": "أذن الله أن تبنى", "ashab": "", "athar": []}, {"n": 2, "t": "أذن الله أن تعظم", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن عطية", "w"]]}, "t": {"1": [["ابن جرير", "r"], ["ابن عطية", "w"]]}, "gen": [], "rules": {"ابن جرير": ["القرآن والنظائر", "اللغة"]}, "rulesD": {}}}, {"aya": 36, "title": "متعلق قوله: {في بيوت}]", "mawsua": {"taliq": 4670, "masala": "متعلق قوله: {في بيوت}]", "sigha": "حكاية خلاف", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "هي متعلقة ب {مصباح}. قال أبو حاتم:", "ashab": "", "athar": []}, {"n": 2, "t": "متعلقة ب {يسبح} المتأخر. فعلى هذا التأويل يوقف على {عليم} [38]، قال الرماني: هي متعلقة ب {يوقد} [35]", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 4670, "mi": 0, "aya": 36, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 390", "qawl": "", "nass": "واختلف في الفاء من قوله: {في} [كذا؛ يعني: اختلف في متعلق قوله: {في بيوت}]؛ فقيل: هي متعلقة ب {مصباح}. قال أبو حاتم: وقيل: متعلقة ب {يسبح} المتأخر. فعلى هذا التأويل يوقف على {عليم} [38]، قال الرماني: هي متعلقة ب {يوقد} [35]", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 36, "title": "تفسير قوله: {بيوت}", "mawsua": {"taliq": 4672, "masala": "تفسير قوله: {بيوت}", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "أنها المساجد", "ashab": "", "athar": []}, {"n": 2, "t": "أنها كل البيوت", "ashab": "", "athar": []}, {"n": 3, "t": "أنها بيوت النبي صلى الله عليه وسلم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 4672, "mi": 1, "aya": 36, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 318", "qawl": "الأول", "nass": "إنما اخترنا القول الذي اخترناه في ذلك لدلالة قوله: {يسبح له فيها بالغدو والآصال رجال لا تلهيهم تجارة ولا بيع عن ذكر الله} على أنها بيوت بنيت للصلاة؛ فلذلك قلنا: هي المساجد", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 4672, "mi": 1, "aya": 36, "alam": "ابن عطية", "fil": "وبنحوه", "kind": "موافقة", "ref": "6/ 390", "qawl": "", "nass": "وقوله تعالى: {يسبح له فيها بالغدو والآصال رجال} يقوي أنها المساجد", "qawaid": [], "tabi": "ابن جرير"}], "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن عطية", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["السياق"]}, "rulesD": {}}}, {"aya": 36, "title": "معنى قوله: {ويذكر فيها اسمه}", "mawsua": {"taliq": 4674, "masala": "معنى قوله: {ويذكر فيها اسمه}", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "يتلى فيها كتابه", "ashab": "", "athar": []}, {"n": 2, "t": "أن يذكر فيها اسم الله ويوحد", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 4674, "mi": 1, "aya": 36, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 319", "qawl": "الثاني", "nass": "وهذا القول قريب المعنى مما قلناه في ذلك؛ لأن تلاوة كتاب الله من معاني ذكر الله", "qawaid": [], "tabi": ""}], "tags": {"m": {"2": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 37, "title": "تأويل: ﴿رجال لا تلهيهم تجارة ولا بيع عن ذكر الله﴾", "tabari": {"page": "17/322", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿رجال لا تلهيهم تجارة ولا بيع عن ذكر الله﴾. يقول تعالى ذكره: لا يشغل هؤلاء الرجال الذين يصلون في هذه المساجد التي أذن الله أن ترفع، عن ذكر الله فيها وإقام الصلاة - تجارة ولا بيع.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "معنى ذلك: لا تلهيهم تجارة ولا بيع عن صلاتهم المفروضة عليهم", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [53625, 53626, 53634, 53635, 53657]}]}, "mawaqif": [], "mushid": {"i": 23, "imgs": ["024_023_1.png"], "pages": [383], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 37, "title": "قوله: {تتقلب فيه القلوب والأبصار}", "mawsua": {"taliq": 4679, "masala": "قوله: {تتقلب فيه القلوب والأبصار}", "sigha": "ذكر قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "يرى الناس الحقائق عيانا، فتتقلب قلوب الشاكين ومعتقدي الضلال عن معتقداتها إلى اعتقاد الحق على وجهه، وكذلك الأبصار", "ashab": "", "athar": []}, {"n": 2, "t": "هو تقلب على جمر جهنم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 4679, "mi": 1, "aya": 37, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 392 بتصرف", "qawl": "", "nass": "واختلف الناس في تقلب القلوب والأبصار، كيف هو؟ فقالت فرقة: يرى الناس الحقائق عيانا، فتتقلب قلوب الشاكين ومعتقدي الضلال عن معتقداتها إلى اعتقاد الحق على وجهه، وكذلك الأبصار. وقالت فرقة: هو تقلب على جمر جهنم", "qawaid": ["اللغة"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 40, "title": "قوله: {إذا أخرج يده لم يكد يراها}", "mawsua": {"taliq": 4681, "masala": "قوله: {إذا أخرج يده لم يكد يراها}", "sigha": "ذكر قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن هذا الرجل المقدر في هذه الأحوال لم ير يده البتة. كما أفاده قول مقاتل", "ashab": "", "athar": []}, {"n": 2, "t": "أن هذا الرجل رأى يده بعد جهد وشدة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 4681, "mi": 1, "aya": 40, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 395 - 396", "qawl": "مقاتل", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 4681, "mi": 1, "aya": 40, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "", "qawl": "الثاني", "nass": "(كاد) إذا صحبها حرف النفي وجب الفعل الذي بعدها، وإذا لم يصحبها انتفى الفعل", "qawaid": [], "tabi": ""}, {"taliq": 4681, "mi": 1, "aya": 40, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "17/ 332", "qawl": "", "nass": "أظهر معاني الكلمة من جهة ما تستعمل العرب أكاد في كلامها", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 55, "title": "تأويل: ﴿وعد الله الذين آمنوا منكم وعملوا الصالحات ليستخلفنهم في الأرض كما استخلف الذين من قبلهم ول﴾", "tabari": {"page": "17/346", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: ﴿وعد الله الذين آمنوا﴾ بالله ورسوله ﴿منكم﴾ أيها الناس، ﴿وعملوا الصالحات﴾. يقول: وأطاعوا الله ورسوله فيما أمراه ونهياه - ﴿ليستخلفنهم في الأرض﴾. يقول: ليورثنهم الله أرض المشركين من العرب والعجم، فيجعلهم ملوكها وساستها، ﴿كما استخلف الذين من قبلهم﴾. يقول: كما فعل من قبلهم ذلك ببنى إسرائيل، إذ أهلك الجبابرة بالشام، وجعلهم ملوكها وسكانها، ﴿وليمكنن لهم دينهم الذي ارتضى لهم﴾. يقول: وليوطئ", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿وعد الله الذين آمنوا﴾. ثم تلقى ذلك بجواب اليمين بقوله: ﴿ليستخلفنهم﴾؛ لأن الوعد قول يصلح فيه \"أن\" وجواب اليمين، كقوله: وعدتك أن أكرمك، ووعدتك لأكرمنك", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 4692, "mi": 0, "aya": 55, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 349", "qawl": "الأول", "nass": "أن الله وعد الإنعام على هذه الأمة بما أخبر في هذه الآية أنه منعم به عليهم، ثم قال عقيب ذلك: فمن كفر هذه النعمة بعد ذلك فأولئك هم الفاسقون", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 4692, "mi": 0, "aya": 55, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "6/ 406", "qawl": "الأول", "nass": "ويكون الفسق على هذا غير المخرج عن الملة", "qawaid": [], "tabi": ""}], "mushid": {"i": 24, "imgs": ["024_024_1.png"], "pages": [384], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق"]}, "rulesD": {}}}, {"aya": 58, "title": "في المعني بقوله: ﴿ليستأذنكم الذين ملكت أيمانكم﴾", "tabari": {"page": "17/351", "sarih": 1, "tarjih": "وأولى القولين في ذلك عندى بالصواب قول من قال: عنى به الذكور والإناث؛ لأن الله عم بقوله: ﴿الذين ملكت أيمانكم﴾ جميع أملاك أيماننا، ولم يخصص منهم ذكرا ولا أنثى، فذلك على جميع من عمه ظاهر التنزيل.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "عنى بذلك الرجال دون النساء، ونهوا عن أن يدخلوا عليهم في هذه الأوقات الثلاثة، هؤلاء الذين سموا في هذه الآية، إلا بإذن", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عمر", "صحابي"]], "athar": [53904, 53905, 53968]}, {"n": 2, "t": "بل عنى به الرجال والنساء", "taqdim": 0, "n_athar": 1, "qailun": [["أبي عبد الرحمن", "تابعي"]], "athar": [53906, 53907]}]}, "mawaqif": [{"taliq": 4693, "mi": 0, "aya": 58, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 352", "qawl": "الثاني", "nass": "لأن الله عم بقوله: {الذين ملكت أيمانكم} جميع أملاك أيماننا، ولم يخصص منهم ذكرا ولا أنثى، فذلك على جميع من عمه ظاهر التنزيل", "qawaid": ["العموم"], "tabi": ""}], "mushid": {"i": 25, "imgs": ["024_025_1.png"], "pages": [384], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["العموم"]}, "rulesD": {}}}, {"aya": 61, "title": "في تأويل هذه الآية وفي المعنى الذي أنزلت فيه", "tabari": {"page": "17/365", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "أنزلت هذه الآية ترخيصا للمسلمين في الأكل مع العميان والعرجان والمرضى وأهل الزمانة من طعامهم، من أجل أنهم كانوا قد امتنعوا من أن يأكلوا معهم من طعامهم؛ خشية أن يكونوا قد أتوا بأكلهم معهم من طعامهم ما نهاهم الله عنه بقوله: ﴿ياأيها الذين آمنوا لا تأكلوا أموالكم بينكم بالباطل إلا أن تكون تجارة عن تراض منكم﴾ [النساء: ٢٩]", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"]], "athar": [54066, 54067, 54100, 54118, 54119, 54121, 54133, 54134, 54135, 54136, 54137, 54138]}, {"n": 2, "t": "بل نزلت هذه الآية ترخيصا لأهل الزمانة، في الأكل من بيوت من سمى الله في هذه الآية؛ لأن قوما كانوا من أصحاب رسول الله ﷺ، إذا لم يكن عندهم في بيوتهم ما يطعمونهم، ذهبوا بهم إلى بيوت آبائهم وأمهاتهم، أو بعض من سمى الله في هذه الآية، فكان أهل الزمانة يتحوبون من أن يطعموا ذلك الطعام؛ لأنه أطعمهم غير مالكه", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"]], "athar": [54072, 54102, 54148, 54149, 54150, 54185]}, {"n": 3, "t": "بل نزلت ترخيصا لأهل الزمانة الذين وصفهم الله في هذه الآية، أن يأكلوا من بيوت من خلفهم في بيوته من الغزاة", "taqdim": 0, "n_athar": 1, "qailun": [["معمر", "تابع التابعين"]], "athar": [54153]}, {"n": 4, "t": "بل عنى بقوله: ﴿ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج﴾. في التخلف عن الجهاد في سبيل الله. قالوا: وقوله: ﴿ولا على أنفسكم أن تأكلوا من بيوتكم﴾. كلام منقطع عما قبله", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [54084, 54098, 54132, 54169]}, {"n": 5, "t": "بل نزلت هذه الآية ترخيصا للمسلمين الذين كانوا يتقون مؤاكلة أهل الزمانة في مؤاكلتهم إذا شاءوا ذلك", "taqdim": 0, "n_athar": 1, "qailun": [["مقسم", ""]], "athar": [54071]}]}, "mawaqif": [{"taliq": 4697, "mi": 1, "aya": 61, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "17/ 367", "qawl": "الأول", "nass": "فمعنى الكلام على تأويل هؤلاء: ليس عليكم أيها الناس في الأعمى حرج أن تأكلوا منه ومعه، ولا في الأعرج حرج، ولا في المريض حرج، ولا في أنفسكم، أن تأكلوا من بيوتكم. فوجهوا معنى {على} في هذا الموضع إلى معنى: في", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 4697, "mi": 1, "aya": 61, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "6/ 409", "qawl": "", "nass": "أن الحرج مرفوع عنهم في كل ما يضطرهم إليه العذر، وتقتضي نيتهم الإتيان فيه بالأكمل، ويقتضي العذر أن يقع منهم الأنقص، فالحرج مرفوع عنهم في هذا", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 4697, "mi": 1, "aya": 61, "alam": "ابن جرير", "fil": "انتقد", "kind": "نقد", "ref": "17/ 373", "qawl": "الثاني", "nass": "معنى لقول من قال: إنما أنزلت هذه الآية من أجل كراهة المستتبع أكل طعام غير المستتبع؛ لأن ذلك لو كان كما قال من قال ذلك لقيل: ليس عليكم حرج أن تأكلوا من طعام غير من أضافكم، أو من طعام آباء من دعاكم، ولم يقل: {أن تأكلوا من بيوتكم أو بيوت آبائكم}", "qawaid": ["ظاهر الآية ولفظها", "الدلالة العقلية", "اللغة"], "tabi": ""}], "mushid": {"i": 26, "imgs": ["024_026_1.png", "024_026_2.png"], "pages": [384, 385], "n": 5, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 4697, "masala": "المراد بقوله تعالى: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج} الآية، وفي المعنى الذي نزلت فيه", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنزلت هذه الآية مرخصة لمن خشي من المسلمين الأكل مع العميان والعرجان والمرضى وأهل الزمانة من طعامهم، مخافة الوقوع فيما نهاهم الله عنه بقوله: {يا أيها الذين آمنوا لا تأكلوا أموالكم بينكم بالباطل} [النساء: 29]", "ashab": "", "athar": []}, {"n": 2, "t": "نزلت هذه الآية ترخيصا لأهل الزمانة في الأكل من بيوت من سمى الله في هذه الآية؛ لأن قوما كانوا من أصحاب رسول الله صلى الله عليه وسلم إذا لم يكن عندهم في بيوتهم ما يطعمونهم ذهبوا بهم إلى بيوت آبائهم وأمهاتهم، أو بعض من سمى الله في هذه الآية، فكان أهل الزمانة يتحوبون [يتحرجون ويتخوفون من الإثم] من أن يطعموا ذلك الطعام؛ لأنه أطعمهم غير مالكه", "ashab": "", "athar": []}, {"n": 3, "t": "نزلت ترخيصا لأهل الزمانة -الذين وصفهم الله في هذه الآية- أن يأكلوا من بيوت من خلفهم في بيوته من الغزاة", "ashab": "", "athar": []}, {"n": 4, "t": "أنها نزلت في إسقاط الجهاد عن أهل الزمانة المذكورين في الآية", "ashab": "", "athar": []}, {"n": 5, "t": "نزلت ترخيصا للمسلمين الذين كانوا يتقون مؤاكلة أهل الزمانة في مؤاكلتهم إذا شاءوا ذلك", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "w"]], "2": [["ابن جرير", "d"]]}, "t": {"1": [["ابن جرير", "w"]], "2": [["ابن جرير", "d"]]}, "gen": [["ابن عطية", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن عطية": ["ظاهر الآية ولفظها"]}, "rulesD": {"ابن جرير": ["ظاهر الآية ولفظها", "الدلالة العقلية", "اللغة"]}}}, {"aya": 61, "title": "في معنى قوله: ﴿أو ما ملكتم مفاتحه﴾", "tabari": {"page": "17/370", "sarih": 1, "tarjih": "وأشبه الأقوال التي ذكرنا في تأويل قوله: ﴿ليس على الأعمى حرج﴾ إلى قوله: ﴿أو صديقكم﴾ القول الذي ذكرنا عن الزهري، عن عبيد الله بن عبد الله، وذلك أن أظهر معاني قوله: ﴿ليس على الأعمى حرج ولا على الأعرج حرج﴾: أنه لا حرج على هؤلاء الذين سموا في هذه الآية أن يأكلوا من بيوت من ذكره الله فيها، على ما أباح لهم من الأكل منها. فإذ كان ذلك أظهر معانيه، فتوجيه معناه إلى الأغلب الأعرف من معانيه أولى من توجيهه إلى الأنكر منها. فإذ كان ذلك كذلك، كان ما خالف من التأويل قول من قال: معناه: ليس في الأعمى والأعرج حرج - أولى بالصواب.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "عنى بذلك وكيل الرجل وقيمه، أنه لا بأس عليه أن يأكل من ثمر ضيعته ونحو ذلك", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [54066, 54067, 54100, 54118, 54119, 54121, 54133, 54134, 54135, 54136, 54137, 54138]}, {"n": 2, "t": "بل عنى بذلك منزل الرجل نفسه، أنه لا بأس عليه أن يأكل منه", "taqdim": 0, "n_athar": 3, "qailun": [["قتادة", "تابعي"], ["مجاهد", "تابعي"]], "athar": [54072, 54076, 54102, 54106, 54115, 54127, 54148, 54149, 54150, 54158, 54163, 54185]}]}, "mawaqif": [], "mushid": {"i": 27, "imgs": ["024_027_1.png"], "pages": [385], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 61, "title": "في تأويله", "tabari": {"page": "17/375", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله وضع الحرج عن المسلمين، أن يأكلوا جميعا معا إذا شاءوا، أو أشتاتا متفرقين إذا أرادوا، وجائز أن يكون ذلك نزل بسبب من كان يتحوب من الأغنياء الأكل مع الفقير، وجائز أن يكون نزل بسبب القوم الذين ذكر أنهم كانوا لا يطعمون وحدانا، وبسبب غير ذلك، ولا خبر بشيء من ذلك يقطع العذر، ولا دلالة في ظاهر التنزيل على حقيقة شيء منه. والصواب التسليم لما دل عليه ظاهر التنزيل، والتوقف فيما لم يكن على صحته دليل.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "كان الغني من الناس يتحوب أن يأكل مع الفقير، فرخص لهم في الأكل معهم", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [54066, 54067, 54100, 54118, 54119, 54121, 54133, 54134, 54135, 54136, 54137, 54138]}, {"n": 2, "t": "بل عنى بذلك حي من أحياء العرب، كانوا لا يأكل أحدهم وحده، [ولا يأكل إلا مع غيره، فأذن الله لهم أن يأكل من شاء منهم وحده] ، ومن شاء منهم مع غيره", "taqdim": 0, "n_athar": 6, "qailun": [["ابن عباس", "صحابي"], ["ابن جريج", "تابع التابعين"], ["ابن زيد", "تابع التابعين"], ["قتادة", "تابعي"], ["أبي صالح وعكرمة", "تابعي"]], "athar": [54066, 54067, 54076, 54084, 54098, 54100, 54106, 54115, 54118, 54119, 54121, 54127, 54131, 54132, 54133, 54134, 54135, 54136, 54137, 54138, 54140, 54141, 54158, 54159, 54160, 54162, 54163, 54169]}]}, "mawaqif": [{"taliq": 4699, "mi": 1, "aya": 61, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 377", "qawl": "العموم", "nass": "إن الله وضع الحرج عن المسلمين أن يأكلوا جميعا معا إذا شاءوا، أو أشتاتا متفرقين إذا أرادوا، وجائز أن يكون ذلك نزل بسبب من كان يتحوب من الأغنياء الأكل مع الفقير، وجائز أن يكون نزل بسبب القوم الذين ذكر أنهم كانوا لا يطعمون وحدانا، وبسبب غير ذلك؛ ولا خبر بشيء من ذلك يقطع العذر، ولا دلالة في ظاهر التنزيل على حقيقة شيء منه. والصواب التسليم لما دل عليه ظاهر التنزيل، والتوقف فيما لم يكن على صحته دليل", "qawaid": [], "tabi": ""}], "mushid": {"i": 28, "imgs": ["024_028_1.png", "024_028_2.png"], "pages": [385, 386], "n": 3, "rajih": [], "daif": [], "match": false}, "mawsua": {"taliq": 4699, "masala": "المعني بقوله تعالى: {ليس عليكم جناح أن تأكلوا جميعا أو أشتاتا}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "كان الغني من الناس يجد في نفسه أن يأكل مع الفقير، فرخص لهم في الأكل معهم", "ashab": "", "athar": []}, {"n": 2, "t": "عني بذلك: حي من أحياء العرب، كانوا لا يأكل أحدهم وحده، ولا يأكل إلا مع غيره، فأذن الله لهم أن يأكل من شاء منهم وحده أو مع غيره", "ashab": "", "athar": []}, {"n": 3, "t": "عني بذلك قوم كانوا لا يأكلون إذا نزل بهم ضيف إلا مع ضيفهم، فرخص لهم في أن يأكلوا كيف شاءوا", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح العموم"]], "rules": {}, "rulesD": {}}}, {"aya": 61, "title": "في ذلك ﴿فإذا دخلتم بيوتا فسلموا على أنفسكم تحية من عند الله﴾", "tabari": {"page": "17/378", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب قول من قال: معناه: فإذا دخلتم بيوتا من بيوت المسلمين فليسلم بعضكم على بعض.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه: فإذا دخلتم أيها الناس بيوت أنفسكم، فسلموا على أهليكم وعيالكم", "taqdim": 0, "n_athar": 5, "qailun": [["الزهري وقتادة", "تابعي"], ["ابن جريج", "تابع التابعين"], ["جابر بن عبد الله", "صحابي"], ["لى ابن جريج", ""]], "athar": [54131, 54140, 54141, 54144, 54159, 54160, 54162, 54178]}, {"n": 2, "t": "بل معناه: فإذا دخلتم المساجد فسلموا على أهلها", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [54066, 54067, 54100, 54118, 54119, 54121, 54133, 54134, 54135, 54136, 54137, 54138]}, {"n": 3, "t": "بل معنى ذلك: إذا دخلتم بيوتا من بيوت المسلمين فيها ناس منكم، فليسلم بعضكم على بعض", "taqdim": 0, "n_athar": 2, "qailun": [["الحسن", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [54075, 54084, 54098, 54105, 54113, 54132, 54152, 54169]}, {"n": 4, "t": "معناه: فإذا دخلتم بيوتا ليس فيها أحد، فسلموا على أنفسكم", "taqdim": 0, "n_athar": 5, "qailun": [["أبي مالك", "تابعي"], ["ماهان", ""], ["منصور", ""], ["نافع", "تابعي"], ["إبراهيم", "تابعي"]], "athar": [54146, 54147, 54166, 54186]}]}, "mawaqif": [{"taliq": 4700, "mi": 1, "aya": 61, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "6/ 412", "qawl": "الثاني", "nass": "والمعنى: سلموا على من فيها من صنفكم، فهذا كما قال: {لقد جاءكم رسول من أنفسكم} [التوبة: 128]، فإن لم يكن في المساجد أحد فالسلام أن يقول المرء: السلام على رسول الله. وقيل: يقول: السلام عليكم. يريد الملائكة", "qawaid": [], "tabi": ""}, {"taliq": 4700, "mi": 1, "aya": 61, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 383", "qawl": "العموم", "nass": "وأولى الأقوال في ذلك بالصواب قول من قال: معناه: فإذا دخلتم بيوتا من بيوت المسلمين فليسلم بعضكم على بعض. وإنما قلنا: ذلك أولى بالصواب؛ لأن الله -جل ثناؤه- قال: {فإذا دخلتم بيوتا}، ولم يخصص من ذلك بيتا دون بيت، وقال: {فسلموا على أنفسكم} يعني: بعضكم على بعض. فكان معلوما إذ لم يخص ذلك على بعض البيوت دون بعض أنه معني به جميعها؛ مساجدها وغير مساجدها", "qawaid": ["العموم"], "tabi": ""}], "mushid": {"i": 29, "imgs": ["024_029_1.png"], "pages": [386], "n": 4, "rajih": [3], "daif": [], "match": true}, "mawsua": {"taliq": 4700, "masala": "معنى قوله تعالى: {فإذا دخلتم بيوتا فسلموا على أنفسكم تحية من عند الله}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "معناه: فإذا دخلتم أيها الناس بيوت أنفسكم فسلموا على أهليكم وعيالكم", "ashab": "", "athar": []}, {"n": 2, "t": "فإذا دخلتم المساجد فسلموا على أهلها", "ashab": "", "athar": []}, {"n": 3, "t": "إذا دخلتم بيوتا من بيوت المسلمين فيها ناس منكم فليسلم بعضكم على بعض", "ashab": "", "athar": []}, {"n": 4, "t": "فإذا دخلتم بيوتا ليس فيها أحد فسلموا على أنفسكم", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن عطية", "w"]], "3": [["ابن جرير", "r"]]}, "t": {"2": [["ابن عطية", "w"]], "3": [["ابن جرير", "r"]]}, "gen": [["ابن جرير", "رجّح العموم"]], "rules": {"ابن جرير": ["العموم"]}, "rulesD": {}}}, {"aya": 63, "title": "في معنى ذلك ﴿لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضا قد يعلم الله الذين يتسللون منكم لواذا فليحذر ﴾", "tabari": {"page": "17/388", "sarih": 1, "tarjih": "وأولى التأويلين في ذلك بالصواب عندى التأويل الذي قاله ابن عباس؛ وذلك أن الذي قبل قوله: ﴿لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضا﴾ - نهي من الله المؤمنين أن يأتوا من الانصراف عنه، في الأمر الذي يجمع جميعهم، ما يكرهه، والذي بعده وعيد للمنصرفين [عنه بغير إذنه] ، فالذي بينهما بأن يكون تحذيرا لهم سخطه، أن يضطره إلى الدعاء عليهم، أشبه من أن يكون أمرا لهم بما لم يجر له ذكر؛ من تعظيمه وتوقيره بالقول والدعاء.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "نهى الله بهذه الآية المؤمنين أن يتعرضوا لدعاء الرسول عليهم، وقال لهم : اتقوا دعاءه [عليكم، بأن تفعلوا ما يسخطه، فيدعو لذلك عليكم فتهلكوا، فلا تجعلوا دعاءه كدعاء غيره من الناس؛ فإن دعاءه] موجبة", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [54231, 54232, 54233, 54234, 54251, 54267]}, {"n": 2, "t": "بل ذلك نهى من الله أن يدعوا رسول الله ﷺ بغلظ وجفاء، وأمرهم أن يدعوه بلين وتواضع", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [54239, 54244, 54252, 54256, 54268, 54283]}]}, "mawaqif": [{"taliq": 4701, "mi": 0, "aya": 63, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 389", "qawl": "الثاني", "nass": "أن الذي قبل قوله: {لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضا} نهي من الله المؤمنين أن يأتوا من الانصراف عنه في الأمر الذي يجمع جميعهم ما يكرهه، والذي بعده وعيد للمنصرفين عنه بغير إذنه، فالذي بينهما بأن يكون تحذيرا لهم سخطه أن يضطره إلى الدعاء عليهم أشبه من أن يكون أمرا لهم بما لم يجر له ذكر من تعظيمه وتوقيره بالقول والدعاء", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 4701, "mi": 0, "aya": 63, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "6/ 414", "qawl": "الأول", "nass": "", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 4701, "mi": 0, "aya": 63, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "10/ 280", "qawl": "الأول", "nass": "", "qawaid": ["السياق"], "tabi": "ابن عطية"}, {"taliq": 4701, "mi": 0, "aya": 63, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "والأول أصح", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}, {"taliq": 4701, "mi": 0, "aya": 63, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "وهو الظاهر من السياق", "qawaid": [], "tabi": ""}, {"taliq": 4701, "mi": 0, "aya": 63, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "", "qawl": "الثاني", "nass": "ولفظ الآية يدفع هذا المعنى", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}], "mushid": {"i": 30, "imgs": ["024_030_1.png"], "pages": [386], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [["ابن عطية", "رجّح ولم يتعيّن القول آليًّا"], ["ابن كثير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["السياق"], "ابن عطية": ["السياق", "لم يذكر مستندًا"], "ابن كثير": ["السياق"]}, "rulesD": {"ابن عطية": ["ظاهر الآية ولفظها"]}}}], "extra": [{"i": 10, "aya": 27, "imgs": ["024_010_1.png"], "pages": [380], "ihala": 0}, {"i": 15, "aya": 33, "imgs": ["024_015_1.png"], "pages": [381], "ihala": 0}, {"i": 21, "aya": 35, "imgs": ["024_021_1.png"], "pages": [383], "ihala": 0}], "others": {"0": [{"id": 4588, "kinds": "غيره", "text": "نصَّ ابنُ عطية (6/ 329)، وابنُ كثير (10/ 159) على مَدَنِيَّة السورة، فقال ابنُ عطية: «هذه السورةُ كلُّها مدنية». وبنحوه قال ابنُ كثير.", "mawaqif": [{"taliq": 4588, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "هذه السورة كلها مدنية", "qawaid": [], "tabi": ""}, {"taliq": 4588, "mi": 0, "aya": 0, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}]}], "1": [{"id": 4589, "kinds": "خلاف،بيان،نقل", "text": "اختلف القرّاء في قراءة قوله تعالى: {وفَرَضْناها}؛ فقرأها بعضهم بتشديد الراء، على معنى: وفصَّلناها ونزَّلنا فيها فرائضَ مختلفةً. وذكر ابنُ جرير (17/ 137) أنّ لهذه القراءة معنًى آخر تحتمله، وهو: «وفَرَّضْناها عليكم، وعلى مَن بعدَكم مِن الناس إلى قيام الساعة». وقرأها بعضهم بتخفيف الراء، على معنى: أوجَبْنا ما فيها من الأحكام عليكم، وألزمناكموه، وبيَّنا ذلك لكم.\nوبيَّنَ ابنُ جرير (17/ 138) أنّ كلتا القراءتين صواب؛ لشهرتهما، وقراءة القراء بهما، فقال: «الصواب مِن القول في ذلك أنهما قراءتان مشهورتان، قد قرأ بكل واحدة منهما علماءٌ مِن القرأة، فبأيتهما قرأ القارئ فمصيب، وذلك أن الله قد فصّلها، وأنزل فيها ضُروبًا من الأحكام، وأمر فيها ونهى، وفرض على عباده فيها فرائض، ففيها المعنيان كلاهما: التفريض، والفرض، فلذلك قلنا: بأية القراءتين قرأ القارئ فمصيب الصواب».", "mawaqif": [{"taliq": 4589, "mi": 0, "aya": 1, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "17/ 137", "qawl": "", "nass": "وفرضناها عليكم، وعلى من بعدكم من الناس إلى قيام الساعة", "qawaid": [], "tabi": ""}, {"taliq": 4589, "mi": 0, "aya": 1, "alam": "ابن جرير", "fil": "بين", "kind": "بيان", "ref": "17/ 138", "qawl": "", "nass": "الصواب من القول في ذلك أنهما قراءتان مشهورتان، قد قرأ بكل واحدة منهما علماء من القرأة، فبأيتهما قرأ القارئ فمصيب، وذلك أن الله قد فصلها، وأنزل فيها ضروبا من الأحكام، وأمر فيها ونهى، وفرض على عباده فيها فرائض، ففيها المعنيان كلاهما: التفريض، والفرض، فلذلك قلنا: بأية القراءتين قرأ القارئ فمصيب الصواب", "qawaid": [], "tabi": ""}]}, {"id": 4590, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (6/ 330) أنّ الزهراوي قال بأن معنى الآيات البينات: ليس فيها مشكل، تأويلها موافق لظاهرها. وانتقده بقوله: «وهذا تَحَكُّم».", "mawaqif": [{"taliq": 4590, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 330", "qawl": "", "nass": "وهذا تحكم", "qawaid": [], "tabi": ""}]}], "2": [{"id": 4591, "kinds": "نقل", "text": "قال ابنُ عطية (6/ 333): «الجلد يكون والمجلود قاعدٌ عند مالك، ولا يُجْزِئ عنده إلا في الظهر. وأصحاب الرأي والشافعيّ يرون أن يُجلَد الرجلُ وهو واقف، وهو قول علي بن أبي طالب، ويُفَرَّق الضرب على كلّ الأعضاء، وأشار ابن عمر بالضرب إلى رِجْلَي أمةٍ جلدها في الزنا، والإجماع في تسليم الوجه والعورة والمَقاتِل. ويترجَّح قول مالك? بقول النبي صلى الله عليه وسلم: «البينة، أو حدٌّ في ظهرك». وقول عمر: أو لأوجعَنَّ مَتْنَكِ. ويُعرّى الرجل عند مالك، والنخعي، وأبي عبيدة بن الجراح، وابن مسعود، وعمر بن عبد العزيز، والحسن، والشعبي. وغيرُهم يرون أن يُضْرَب على قميص، وهو قول عثمان، وابن مسعود أيضًا، وأما المرأة فتستر قولًا واحدًا».", "mawaqif": [{"taliq": 4591, "mi": 0, "aya": 2, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 333", "qawl": "", "nass": "الجلد يكون والمجلود قاعد عند مالك، ولا يجزئ عنده إلا في الظهر. وأصحاب الرأي والشافعي يرون أن يجلد الرجل وهو واقف، وهو قول علي بن أبي طالب، ويفرق الضرب على كل الأعضاء، وأشار ابن عمر بالضرب إلى رجلي أمة جلدها في الزنا، والإجماع في تسليم الوجه والعورة والمقاتل. ويترجح قول مالك? بقول النبي صلى الله عليه وسلم: «البينة، أو حد في ظهرك", "qawaid": [], "tabi": ""}]}], "3": [{"id": 4595, "kinds": "غيره", "text": "قال ابنُ عطية (6/ 336): «في الآية -على هذا التأويل- معنى التفجّع عليهم، وفي ذلك توبيخ، كأنه يقول: أيُّ مُصاب؟! الزاني لا يريد أن يتزوج إلا زانية أو مشركة، أي: تنزِع نفوسُهم إلى هذه الخسائس؛ لقِلَّة انضباطهم».", "mawaqif": [{"taliq": 4595, "mi": 0, "aya": 3, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 336", "qawl": "", "nass": "في الآية -على هذا التأويل- معنى التفجع عليهم، وفي ذلك توبيخ، كأنه يقول: أي مصاب؟! الزاني لا يريد أن يتزوج إلا زانية أو مشركة، أي: تنزع نفوسهم إلى هذه الخسائس؛ لقلة انضباطهم", "qawaid": [], "tabi": ""}]}, {"id": 4596, "kinds": "نقد", "text": "انتَقَدَ ابنُ عطية (6/ 338) قولَ الحسن هذا مستندًا لظاهر الآية، فقال: «قولٌ فيه نظر، وإدخال المشرك في الآية يَرُدُّه، وألفاظ الآية تأباه، وإن قدرت المشركة بمعنى: الكتابية؛ فلا حيلة في لفظ المشرك».", "mawaqif": [{"taliq": 4596, "mi": 0, "aya": 3, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "6/ 338", "qawl": "الحسن هذا", "nass": "قول فيه نظر، وإدخال المشرك في الآية يرده، وألفاظ الآية تأباه، وإن قدرت المشركة بمعنى: الكتابية؛ فلا حيلة في لفظ المشرك", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}]}], "4": [{"id": 4599, "kinds": "بيان،نقل", "text": "ذكر ابنُ عطية (6/ 339) أن الله تعالى ذكر في الآية قذْف النساء مِن حيث هو أهم، ورميهن بالفاحشة أبشع وأنكى للنفوس، وبَيَّن أنّ قذف الرجال بإجماع الأمة داخلٌ في حكم الآية بالمعنى، كنصه تعالى على لحم الخنزير ودخول شحمه وغضاريفه ونحو ذلك بالمعنى وبالإجماع، ثم قال: «وحكى الزهراويُّ أن المعنى: الأنفس المحصنات؛ فهي تَعُمُّ بلفظها الرجال والنساء، ويدل على ذلك قوله تعالى: {والمحصنات من النساء} [النساء: 24]».", "mawaqif": [{"taliq": 4599, "mi": 0, "aya": 4, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 339", "qawl": "", "nass": "وحكى الزهراوي أن المعنى: الأنفس المحصنات؛ فهي تعم بلفظها الرجال والنساء، ويدل على ذلك قوله تعالى: {والمحصنات من النساء} [النساء: 24]", "qawaid": [], "tabi": ""}]}], "6": [{"id": 4602, "kinds": "غيره", "text": "قال ابنُ عطية (6/ 344): «المشهور أن نازلة هلال قبلُ، وأنها سبب الآية. وقيل: نازلة عويمر قبلُ، وهو الذي وسَّط إلى رسول الله صلى الله عليه وسلم عاصم بن عدي».", "mawaqif": [{"taliq": 4602, "mi": 0, "aya": 6, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 344", "qawl": "", "nass": "المشهور أن نازلة هلال قبل، وأنها سبب الآية. وقيل: نازلة عويمر قبل، وهو الذي وسط إلى رسول الله صلى الله عليه وسلم عاصم بن عدي", "qawaid": [], "tabi": ""}]}], "11": [{"id": 4604, "kinds": "غيره", "text": "قال ابنُ عطية (6/ 351): «فكأنها عدَّت ما يختصّ بها».", "mawaqif": [{"taliq": 4604, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 351", "qawl": "", "nass": "فكأنها عدت ما يختص بها", "qawaid": [], "tabi": ""}]}, {"id": 4605, "kinds": "بيان،نقل", "text": "قال ابنُ عطية (6/ 355): «إنّ حسان ومِسطحًا وحَمنة حُدُّوا، ذكر ذلك ابن إسحاق، وذكره الترمذي. وفي تفسير ابن عباس رضي الله عنهما أنّ ابن أُبَيٍّ حُدَّ، وهذا عندي لا يصحّ عن ابن عباس رضي الله عنهما؛ لأنه لم يُحْفَظ عن عبد الله الرَّمْي». وقال أيضًا (6/ 357): «لم يُرْوَ في شهير الدواوين أنّ عبد الله بن أُبَيٍّ حُدَّ، ويشبه أنّ ذلك لم يكن؛ لأنه لم تقم عليه بالمقالة بيّنة لنفاقه وتستره، وإنما كان يخوض فيه مع مَن يذيعه ولا يسأل عن شهادته، كما قال عروة في البخاري: أخبرت أنه كان يُقِرّه ويَسْتَوشِيه … ولكن النبي صلى الله عليه وسلم استعذر منه على المنبر، ووَقَذَه بالقول، ووقع في أمره بين الأوس والخزرج ما هو مطوّل في مسلم في جملة حديث الإفك».", "mawaqif": [{"taliq": 4605, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 355", "qawl": "", "nass": "إن حسان ومسطحا وحمنة حدوا، ذكر ذلك ابن إسحاق، وذكره الترمذي. وفي تفسير ابن عباس رضي الله عنهما أن ابن أبي حد، وهذا عندي لا يصح عن ابن عباس رضي الله عنهما؛ لأنه لم يحفظ عن عبد الله الرمي", "qawaid": [], "tabi": ""}]}, {"id": 4606, "kinds": "غيره", "text": "قال ابنُ عطية (6/ 351): «هذه الآية وما بعدها إلى ست عشرة آية أنزلت في عائشة أم المؤمنين رضي الله عنها، وما اتَّصل بذلك من أمر الإفك».\nوبنحوه قال ابنُ كثير (10/ 179).", "mawaqif": [{"taliq": 4606, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 351", "qawl": "", "nass": "هذه الآية وما بعدها إلى ست عشرة آية أنزلت في عائشة أم المؤمنين رضي الله عنها، وما اتصل بذلك من أمر الإفك", "qawaid": [], "tabi": ""}, {"taliq": 4606, "mi": 0, "aya": 11, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "10/ 179", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}]}, {"id": 4607, "kinds": "غيره", "text": "قال ابنُ عطية (6/ 353) مبينًا أوجه الخير في ذلك: «يريد: أنه تبرئة في الدنيا، وترفيع من الله تعالى في أن نزل وحيه بالبراءة من ذلك، وأجر جزيل في الآخرة، وموعظة للمؤمنين في غابر الزمن، ونقمة من المفترين في الدنيا والآخرة، ففي ذلك شفاء وخير، وهذه خمسة وجوه».", "mawaqif": [{"taliq": 4607, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 353", "qawl": "", "nass": "يريد: أنه تبرئة في الدنيا، وترفيع من الله تعالى في أن نزل وحيه بالبراءة من ذلك، وأجر جزيل في الآخرة، وموعظة للمؤمنين في غابر الزمن، ونقمة من المفترين في الدنيا والآخرة، ففي ذلك شفاء وخير، وهذه خمسة وجوه", "qawaid": [], "tabi": ""}]}, {"id": 4608, "kinds": "غيره", "text": "قال ابن عطية (6/ 355): \"أما ضربه بالسيف فإنّ صفوان بن المعطل لما بلغه قول حسان في الإفك جاء فضربه بالسيف ضربة على رأسه، وقال:\nتَلَقَّ ذُباب السيف عني فإنني * غلام إذا هُوجِيتُ لست بشاعر\nفأخذ جماعةٌ صفوانَ ولبَّبوه، وجاءوا به رسولَ الله صلى الله عليه وسلم، فأهدر رسولُ الله صلى الله عليه وسلم جرح حسان، واستوهبه إيّاه، وهذا يقتضي أن حسان ممن تولى الكبر\".", "mawaqif": [{"taliq": 4608, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 355", "qawl": "حسان في", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 4609, "kinds": "نقل", "text": "ذكر ابنُ عطية (6/ 355) أنّ المشار إليه بـ «الذي» -على هذا القول- غيرُ مُعَيَّن.", "mawaqif": [{"taliq": 4609, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 355", "qawl": "", "nass": "الذي", "qawaid": [], "tabi": ""}]}], "12": [{"id": 4611, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (6/ 356) أنّ الخطاب بهاتين الآيتين لجميع المؤمنين حاشا مَن تولى الكبر، ثم قال: «ويحتمل دخولهم في الخطاب، وفي هذا عتاب للمؤمنين؛ أي: كان الإنكار واجبًا عليهم، والمعنى: أنه كان ينبغي أن يقيس فضلاء المؤمنين والمؤمنات الأمر على أنفسهم، وإذا كان ذلك يبعد فيهم فكانوا يقضون بأنّه من صفوان وعائشة أبعد لفضلهما». وذكر أنّه رُوِي هذا النظر السديد عن أبي أيوب الانصاري وامرأته، وساق هذا الأثر، ثم علَّق بقوله: «فذلك الفعل ونحوه هو الذي عاتب الله المؤمنين عليه؛ إذ لم يفعله جميعُهم».", "mawaqif": [{"taliq": 4611, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 356", "qawl": "", "nass": "ويحتمل دخولهم في الخطاب، وفي هذا عتاب للمؤمنين؛ أي: كان الإنكار واجبا عليهم، والمعنى: أنه كان ينبغي أن يقيس فضلاء المؤمنين والمؤمنات الأمر على أنفسهم، وإذا كان ذلك يبعد فيهم فكانوا يقضون بأنه من صفوان وعائشة أبعد لفضلهما", "qawaid": [], "tabi": ""}]}], "15": [{"id": 4612, "kinds": "توجيه", "text": "وجَّهَ ابنُ جرير (17/ 216) هذه القراءة بقوله: «كأنّ عائشة وجَّهت معنى ذلك بقراءتها (تَلِقُونَهُ) -بكسر اللام وتخفيف القاف- إلى: إذ تستمرّون في كذبكم عليها، وإفككم بألسنتكم. كما يُقال: ولَقَ فلان في السير فهو يَلِق: إذا استمرّ فيه».", "mawaqif": [{"taliq": 4612, "mi": 0, "aya": 15, "alam": "ابن جرير", "fil": "وجه", "kind": "توجيه", "ref": "17/ 216", "qawl": "", "nass": "كأن عائشة وجهت معنى ذلك بقراءتها (تلقونه) -بكسر اللام وتخفيف القاف- إلى: إذ تستمرون في كذبكم عليها، وإفككم بألسنتكم. كما يقال: ولق فلان في السير فهو يلق: إذا استمر فيه", "qawaid": [], "tabi": ""}]}, {"id": 4613, "kinds": "ترجيح", "text": "رجَّحَ ابنُ جرير (17/ 217) قراءة الجمهور، فقال: «والقراءة التي لا أستجيز غيرَها: {إذْ تَلَقَّوْنَهُ} على ما ذكرتُ مِن قراءة قرَأَةِ الأمصار؛ لإجماع الحجّة مِن القرأة عليها».", "mawaqif": [{"taliq": 4613, "mi": 0, "aya": 15, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "17/ 217", "qawl": "", "nass": "والقراءة التي لا أستجيز غيرها: {إذ تلقونه} على ما ذكرت من قراءة قرأة الأمصار؛ لإجماع الحجة من القرأة عليها", "qawaid": [], "tabi": ""}]}], "19": [{"id": 4614, "kinds": "ترجيح،توجيه،تعليق،نقل", "text": "علَّق ابنُ عطية (6/ 360) على هذا القول بقوله: «فحبُّهم شياع الفاحشة في المؤمنين مُتَمَكِّن على وجهه لعداوتهم في أهل الإيمان، وعذابهم الأليم في الدنيا الحدود، وفي الآخرة النار». ثم أورد قولًا لفرقة بأن الآية عامة في كل قاذف منافقًا كان أو مؤمنًا. ورجَّحه بقوله: «وقولها الأظهر». ولم يذكر مستندًا. ثم قال: «فالقاذف المؤمن من لا يتصف بحب شياع الفاحشة في المؤمنين جُملَة، لكنه يُحِبُّها لمقذوفه، وكذلك آخر لمقذوفه، وآخر حتى تشيع الفاحشة مِن مجموع فِعْلهم، فهم لها مُحِبُّون بهذا الوجه مِن حيث أحبَّ كلُّ واحد جزءًا مِن شياعها».", "mawaqif": [{"taliq": 4614, "mi": 0, "aya": 19, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "6/ 360", "qawl": "بقوله", "nass": "فحبهم شياع الفاحشة في المؤمنين متمكن على وجهه لعداوتهم في أهل الإيمان، وعذابهم الأليم في الدنيا الحدود، وفي الآخرة النار", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}, {"id": 4615, "kinds": "بيان", "text": "قال ابنُ عطية (6/ 360 - 361): «العذاب الأليم في الدنيا الحدود، وفي الآخرة يحتمل وجهين: أحدهما: أن يكون القاذف مُتَوَعَّدًا مِن بين العصاة بعذاب الآخرة، لا يزيله الحدُّ، حسب مقتضى حديث عبادة بن الصامت، ويكون أمره كأمر المحاربين إذا صُلِبوا لهم خزي في الدنيا ولهم في الآخرة عذاب. والوجه الثاني: أن يحكم بأن الحدَّ مُسْقِط عذاب الآخرة حسب حديث عبادة بن الصامت، وأن قوله: {والآخرة} لا يريد به عموم القذفة، بل يريد: إما المنافقين، وإما من لم يحد، وقال الطبري: معناه: إن مات مُصِرًّا غير تائب».", "mawaqif": [{"taliq": 4615, "mi": 0, "aya": 19, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 360 - 361", "qawl": "", "nass": "العذاب الأليم في الدنيا الحدود، وفي الآخرة يحتمل وجهين: أحدهما: أن يكون القاذف متوعدا من بين العصاة بعذاب الآخرة، لا يزيله الحد، حسب مقتضى حديث عبادة بن الصامت، ويكون أمره كأمر المحاربين إذا صلبوا لهم خزي في الدنيا ولهم في الآخرة عذاب. والوجه الثاني: أن يحكم بأن الحد مسقط عذاب الآخرة حسب حديث عبادة بن الصامت، وأن قوله: {والآخرة} لا يريد به عموم القذفة، بل يريد: إما المنافقين، وإما من لم يحد، وقال الطبري: معناه: إن مات مصرا غير تائب", "qawaid": [], "tabi": ""}]}], "22": [{"id": 4616, "kinds": "خلاف،ترجيح،بيان", "text": "اختُلِف هل كان نزول الآية لِما دار بين مِسْطح وأبي بكر، أم لأنّ جماعة من المؤمنين قطعوا منافعهم عن كُلِّ مَن قال في الإفك.\nورجَّح ابنُ عطية (6/ 362) القول الأول دون الثاني الذي قاله الضحاك وابن عباس، فقال: «والأول أصح». ولم يذكر مستندًا. ثم قال: «غير أنّ الآية تتناول الأُمَّة إلى يوم القيامة بألّا يغتاظ ذو فضل وسَعَة فيحلف أن لا ينفع مَن هذه صفتُه غابِرَ الدَّهْرِ».", "mawaqif": [{"taliq": 4616, "mi": 0, "aya": 22, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "6/ 362", "qawl": "الأول", "nass": "والأول أصح", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}, {"id": 4617, "kinds": "نقل", "text": "ذكر ابنُ عطية (6/ 362 - 363) هذا القول، ثم قال: «وقالت فرقة: معناه: يُقَصِّر، مِن قولك: ألوتُ في كذا. إذا قصرتَ فيه، ومنه قوله تعالى: {لا يَأْلُونَكُمْ خَبالًا} [التوبة: 47]».", "mawaqif": [{"taliq": 4617, "mi": 0, "aya": 22, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 362 - 363", "qawl": "", "nass": "وقالت فرقة: معناه: يقصر، من قولك: ألوت في كذا. إذا قصرت فيه، ومنه قوله تعالى: {لا يألونكم خبالا} [التوبة: 47]", "qawaid": [], "tabi": ""}]}], "23": [{"id": 4618, "kinds": "نقد،نقل", "text": "أورد ابنُ جرير (17/ 226 - 227) هذا الأثر مع القائلين بأنّ الآية حكمها مختص بعائشة، وهو ما انتقده ابنُ كثير (10/ 199)، فقال: «هكذا أورده ابن جرير، وليس فيه أنّ الحكم خاصٌّ بها، وإنّما فيه أنها سبب النزول دون غيرها، وإن كان الحكم يَعُمُّها كغيرها».", "mawaqif": [{"taliq": 4618, "mi": 0, "aya": 23, "alam": "ابن جرير", "fil": "أورد", "kind": "نقل", "ref": "17/ 226 - 227", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 4618, "mi": 0, "aya": 23, "alam": "ابن كثير", "fil": "انتقده", "kind": "نقد", "ref": "10/ 199", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 4618, "mi": 0, "aya": 23, "alam": "ابن جرير", "fil": "أورده", "kind": "نقل", "ref": "", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن كثير"}]}, {"id": 4619, "kinds": "توجيه", "text": "وجَّه ابنُ تيمية (4/ 503) هذا القول بقوله: «وقوله: إنها نزلت زمن العهد. يعني -والله أعلم-: أنه عنى بها مثل أولئك المشركين المعاهدين، وإلا فهذه الآية نزلت في ليالي الإفك، وكان الإفك في غزوة بني المصطلق قبل الخندق، والهدنة كانت بعد ذلك بسنتين».", "mawaqif": [{"taliq": 4619, "mi": 0, "aya": 23, "alam": "ابن تيمية", "fil": "وجه", "kind": "توجيه", "ref": "4/ 503", "qawl": "بقوله", "nass": "وقوله: إنها نزلت زمن العهد. يعني -والله أعلم-: أنه عنى بها مثل أولئك المشركين المعاهدين، وإلا فهذه الآية نزلت في ليالي الإفك، وكان الإفك في غزوة بني المصطلق قبل الخندق، والهدنة كانت بعد ذلك بسنتين", "qawaid": [], "tabi": ""}]}], "24": [{"id": 4621, "kinds": "تعليق،نقل", "text": "علَّق ابنُ كثير (10/ 201) على هذا الحديث بقوله: «قد رواه مسلم والنسائي جميعًا، عن أبي بكر بن أبي النضر، عن أبيه، عن عُبَيد الله الأشجعي، عن سفيان الثوري به، ثم قال النسائي: لا أعلم أحدًا روى هذا الحديث عن سفيان الثوري غير الأشجعي، وهو حديث غريب، والله أعلم. هكذا قال».", "mawaqif": [{"taliq": 4621, "mi": 0, "aya": 24, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "10/ 201", "qawl": "", "nass": "قد رواه مسلم والنسائي جميعا، عن أبي بكر بن أبي النضر، عن أبيه، عن عبيد الله الأشجعي، عن سفيان الثوري به، ثم قال النسائي: لا أعلم أحدا روى هذا الحديث عن سفيان الثوري غير الأشجعي، وهو حديث غريب، والله أعلم. هكذا قال", "qawaid": [], "tabi": ""}]}], "25": [{"id": 4623, "kinds": "نقل", "text": "ذكر ابنُ عطية (6/ 366) أنّ قوله: {يَعْلَمُونَ أنَّ اللَّهَ هُوَ الحَقُّ المُبِينُ} يُقَوِّي قولَ مَن ذهب إلى أنّ الآية في المنافقين؛ عبد الله بن أُبَيٍّ وغيره، وذلك أنّ كل مؤمن ففي الدنيا يعلم أنّ الله هو الحق المبين، وإلا فليس بمؤمن.", "mawaqif": [{"taliq": 4623, "mi": 0, "aya": 25, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 366", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "26": [{"id": 4625, "kinds": "نقد،توجيه،نقل", "text": "ذكر ابنُ جرير (17/ 238) أنّه قيل: عُنِي بقوله: {أولئك مبرءون مما يقولون}: عائشة، وصفوان بن المعطل الذي رُمِيَت به. ووجَّهه بقوله: «فعلى هذا القول قيل: {أولئك} جمع، والمراد: ذانك، كما قيل: {فإن كان له إخوة} [النساء: 11]، والمراد: أخوان».\nونسب ابنُ عطية (6/ 367) القول كاملًا للنقاش، وانتقده بقوله: «وفي هذا التمثيل بآية الإخوة نظر».", "mawaqif": [{"taliq": 4625, "mi": 0, "aya": 26, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "17/ 238", "qawl": "", "nass": "فعلى هذا القول قيل: {أولئك} جمع، والمراد: ذانك، كما قيل: {فإن كان له إخوة} [النساء: 11]، والمراد: أخوان", "qawaid": [], "tabi": ""}, {"taliq": 4625, "mi": 0, "aya": 26, "alam": "ابن عطية", "fil": "نسب", "kind": "نقل", "ref": "6/ 367", "qawl": "كاملا للنقاش", "nass": "وفي هذا التمثيل بآية الإخوة نظر", "qawaid": [], "tabi": ""}]}, {"id": 4626, "kinds": "نقل", "text": "ساق ابنُ كثير (10/ 203) هذا الأثر، ثم قال: «ويُشْبِه هذا ما رواه الإمامُ أحمد في المسند مرفوعًا: «مَثَل الذي يسمع الحكمة ثم لا يُحَدِّث إلا بشرِّ ما سَمِع؛ كمثل رجل جاء إلى صاحب غنم، فقال: أجْزِرني شاةً. فقال: اذهب، فَخُذ بأذُن أيها شئتَ. فذهب فأخذ بأذن كَلْب الغنم»».", "mawaqif": [{"taliq": 4626, "mi": 0, "aya": 26, "alam": "ابن كثير", "fil": "ساق", "kind": "نقل", "ref": "10/ 203", "qawl": "", "nass": "ويشبه هذا ما رواه الإمام أحمد في المسند مرفوعا: «مثل الذي يسمع الحكمة ثم لا يحدث إلا بشر ما سمع؛ كمثل رجل جاء إلى صاحب غنم، فقال: أجزرني شاة. فقال: اذهب، فخذ بأذن أيها شئت. فذهب فأخذ بأذن كلب الغنم»", "qawaid": [], "tabi": ""}]}], "27": [{"id": 4627, "kinds": "نقد،بيان،تعليق،نقل", "text": "انتقد ابنُ عطية (5/ 67 ط: دار الكتب العلمية) هذه القراءة مستندًا للإجماع، ورسم المصحف، فقال: «مصاحف الإسلام كلها قد ثبت فيها: {تَسْتَأْنِسُوا}، وصحَّ الإجماع فيها مِن لدُن مدة عثمان رضي الله عنهما، فهي التي لا يجوز خلافها، والقراءة (تَسْتَأْذِنُوا) ضعيفة، وإطلاق الخطأ والوهم على الكتّاب في لفظ أجمع الصحابة عليه لا يصح عن ابن عباس، والأشبه أن يقرأ: (تَسْتَأْذِنُوا) على التفسير، وظاهر ما حكى الطبري أنها قراءة، ولكن قد رُوِي عن ابن عباس أنه قال: {تَسْتَأْنِسُوا} معناه: تستأذنوا. ومِمّا ينفي هذا القولَ عن ابن عباس أن {تَسْتَأْنِسُوا} متمكنة في المعنى، بينة الوجه في كلام العرب، وقد قال عمر للنبي صلى الله عليه وسلم: أستأنس، يا رسول الله. وعمر واقف على باب الغرفة … الحديث المشهور؛ وذلك يقتضي أنّه طلب الأُنسَ به صلى الله عليه وسلم، فكيف يُخَطِّئ ابنُ عباس رضي الله عنهما أصحابَ الرسول في مثل هذا».\nوعلَّق ابنُ كثير (10/ 207) على قول ابن عباس بقوله: «وهذا غريب جدًّا عن ابن عباس».", "mawaqif": [{"taliq": 4627, "mi": 0, "aya": 27, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "5/ 67 ط: دار الكتب العلمية", "qawl": "", "nass": "مصاحف الإسلام كلها قد ثبت فيها: {تستأنسوا}، وصح الإجماع فيها من لدن مدة عثمان رضي الله عنهما، فهي التي لا يجوز خلافها، والقراءة (تستأذنوا) ضعيفة، وإطلاق الخطأ والوهم على الكتاب في لفظ أجمع الصحابة عليه لا يصح عن ابن عباس، والأشبه أن يقرأ: (تستأذنوا) على التفسير، وظاهر ما حكى الطبري أنها قراءة، ولكن قد روي عن ابن عباس أنه قال: {تستأنسوا} معناه: تستأذنوا. ومما ينفي هذا القول عن ابن عباس أن {تستأنسوا} متمكنة في المعنى، بينة الوجه في كلام العرب، وقد قال عمر للنبي صلى الله عليه وسلم: أستأنس، يا رسول الله. وعمر واقف على باب الغرفة … الحديث المشهور؛ وذلك يقتضي أنه طلب الأنس به صلى الله عليه وسلم، فكيف يخطئ ابن عباس رضي الله عنهما أصحاب الرسول في مثل هذا", "qawaid": ["الإجماع", "القراءة ورسم المصحف"], "tabi": ""}, {"taliq": 4627, "mi": 0, "aya": 27, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "10/ 207", "qawl": "ابن عباس", "nass": "وهذا غريب جدا عن ابن عباس", "qawaid": [], "tabi": ""}]}, {"id": 4628, "kinds": "بيان،نقل", "text": "ساق ابنُ عطية (6/ 367) هذا القول، ثم بيَّن أنّ الآية عامة تشمل كل أحد.", "mawaqif": [{"taliq": 4628, "mi": 0, "aya": 27, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "6/ 367", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 4629, "kinds": "تعليق،نقل", "text": "ساق ابنُ كثير (10/ 211) قول مقاتل، ثم علَّق عليه بقوله: «وهذا الذي قاله مقاتل حسن؛ ولهذا قال: {ذلكم خير لكم} يعني: الاستئذان خير لكم، بمعنى: هو خير للطرفين؛ للمستأذن ولأهل البيت، {لعلكم تذكرون}».", "mawaqif": [{"taliq": 4629, "mi": 0, "aya": 27, "alam": "ابن كثير", "fil": "ساق", "kind": "نقل", "ref": "10/ 211", "qawl": "مقاتل", "nass": "وهذا الذي قاله مقاتل حسن؛ ولهذا قال: {ذلكم خير لكم} يعني: الاستئذان خير لكم، بمعنى: هو خير للطرفين؛ للمستأذن ولأهل البيت، {لعلكم تذكرون}", "qawaid": [], "tabi": ""}]}, {"id": 4631, "kinds": "تعليق", "text": "علَّق ابنُ كثير (10/ 210) على هذا الأثر بقوله: «إسناده صحيح».", "mawaqif": [{"taliq": 4631, "mi": 0, "aya": 27, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "10/ 210", "qawl": "", "nass": "إسناده صحيح", "qawaid": [], "tabi": ""}]}, {"id": 4632, "kinds": "تعليق،نقل", "text": "ساق ابنُ عطية (6/ 370) هذا الأثر، وعلَّق عليه بقوله: «فكأنّه توقف لما قالت: بسلام. لاحتمال اللفظ أن تريد: ادخل بسلامِك، لا بشخصك. ثم لكل قوم في الاستئذان عرفهم في العبارة».", "mawaqif": [{"taliq": 4632, "mi": 0, "aya": 27, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "6/ 370", "qawl": "", "nass": "فكأنه توقف لما قالت: بسلام. لاحتمال اللفظ أن تريد: ادخل بسلامك، لا بشخصك. ثم لكل قوم في الاستئذان عرفهم في العبارة", "qawaid": [], "tabi": ""}]}, {"id": 4633, "kinds": "تعليق،نقل", "text": "ساق ابنُ كثير (10/ 210) هذا القول، وعلَّق عليه بقوله: «وهذا محمول على عدم الوجوب، وإلا فالأولى أن يُعلِمها بدخوله، ولا يُفاجئها به؛ لاحتمال أن تكون على هيئة لا تحب أن يراها عليها».", "mawaqif": [{"taliq": 4633, "mi": 0, "aya": 27, "alam": "ابن كثير", "fil": "ساق", "kind": "نقل", "ref": "10/ 210", "qawl": "", "nass": "وهذا محمول على عدم الوجوب، وإلا فالأولى أن يعلمها بدخوله، ولا يفاجئها به؛ لاحتمال أن تكون على هيئة لا تحب أن يراها عليها", "qawaid": [], "tabi": ""}]}, {"id": 4634, "kinds": "تعليق", "text": "علَّق ابنُ كثير (10/ 206) على هذا الحديث بقوله: «قد رواه أبو داود الطيالسي، عن سفيان الثوري، عن الأعمش، عن طلحة بن مصرف، عن رجل، عن سعد، عن النبي صلى الله عليه وسلم. رواه أبو داود من حديثه».", "mawaqif": [{"taliq": 4634, "mi": 0, "aya": 27, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "10/ 206", "qawl": "", "nass": "قد رواه أبو داود الطيالسي، عن سفيان الثوري، عن الأعمش، عن طلحة بن مصرف، عن رجل، عن سعد، عن النبي صلى الله عليه وسلم. رواه أبو داود من حديثه", "qawaid": [], "tabi": ""}]}], "29": [{"id": 4636, "kinds": "ترجيح،نقد،توجيه،نقل", "text": "انتقد ابنُ جرير (17/ 253 - 254) القول بالنسخ الذي قاله ابن عباس، وعكرمة مستندًا إلى عدم التعارض؛ لأن الآية الأولى في البيوت المسكونة، والآية الثانية في البيوت التي لا أرباب لها، وإنما يستثنى الشيءُ من الشيء إذا كان من جنسه أو نوعه في الفعل أو النفس، فأما إذا لم يكن كذلك فلا معنى لاستثنائه منه.\nوبنحوه ابنُ عطية (6/ 370)، ووجَّه ابنُ عطية هذا القول بقوله: «وكأن من ذهب إلى الاستثناء رأى الأولى عامة».\nوذكر ابنُ كثير (10/ 212) أنّ هذه الآية أخص من التي قبلها، ورجَّح القول بأنها مستثناة من التي قبلها، فقال: «والأول أظهر». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 4636, "mi": 0, "aya": 29, "alam": "ابن جرير", "fil": "انتقد", "kind": "نقد", "ref": "17/ 253 - 254", "qawl": "بالنسخ الذي", "nass": "", "qawaid": ["غير ذلك"], "tabi": ""}, {"taliq": 4636, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "وبنحوه", "kind": "موافقة", "ref": "6/ 370", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 4636, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "", "qawl": "بقوله", "nass": "وكأن من ذهب إلى الاستثناء رأى الأولى عامة", "qawaid": [], "tabi": ""}, {"taliq": 4636, "mi": 0, "aya": 29, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "10/ 212", "qawl": "بأنها مستثناة", "nass": "والأول أظهر", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}, {"id": 4637, "kinds": "نقد،توجيه", "text": "وجَّه ابنُ عطية (6/ 373) هذا القول الذي قاله ابن الحنفية، فقال: «وهذا على القول بأنها غير متملَّكة، وأنّ الناس شركاء فيها، وأن مكة أخذت عنوة». وانتقده مستندًا لمخالفته السنة، فقال: «وهذا هو في هذه المسألة القول الضعيف، يردّه قوله صلى الله عليه وسلم: «وهل ترك لنا عقيل منزلًا». وقوله: «مَن دخل دار أبي سفيان، ومن دخل داره». وغير ذلك من وجوه النظر».", "mawaqif": [{"taliq": 4637, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "6/ 373", "qawl": "", "nass": "وهذا على القول بأنها غير متملكة، وأن الناس شركاء فيها، وأن مكة أخذت عنوة", "qawaid": ["السنة"], "tabi": ""}]}, {"id": 4638, "kinds": "نقد", "text": "انتقد ابنُ جرير (17/ 252) هذا القول الذي قاله ابن زيد، والنخعي مستندًا لدلالة العقل، فقال: «وأما بيوت التجار فإنه ليس لأحد دخولها إلا بإذن أربابها وسكانها. فإن ظنَّ ظانٌّ أن التاجر إذا فتح دكانه، وقعد للناس، فقد أذن لمن أراد الدخول عليه في دخوله، فإن الأمر في ذلك بخلاف ما ظن؛ وذلك أنه ليس لأحد دخول ملك غيره بغير ضرورة ألجأته إليه، أو بغير سبب أباح له دخوله إلا بإذن ربه، لا سيما إذا كان فيه متاع، فإن كان التاجر قد عُرِف منه أنّ فتحه حانوته إذْنٌ منه لمن أراد دخوله في الدخول، فذلك بعدُ راجع إلى ما قلنا مِن أنه لم يدخله من دخله إلا بإذنه».\nوانتقده كذلك ابنُ عطية (6/ 372) مستندًا للإجماع، فقال: «هذا قولٌ غلِط قائلُه، وذلك أنّ بيوت القيسارية محظورةٌ بأموال الناس، غيرُ مباحة لكل مَن أراد دخولها بإجماع، ولا يدخلها إلا مَن أُذن له بها، بل أربابها مُوَكَّلون بدفع الناس عنها».", "mawaqif": [{"taliq": 4638, "mi": 0, "aya": 29, "alam": "ابن جرير", "fil": "انتقد", "kind": "نقد", "ref": "17/ 252", "qawl": "", "nass": "وأما بيوت التجار فإنه ليس لأحد دخولها إلا بإذن أربابها وسكانها. فإن ظن ظان أن التاجر إذا فتح دكانه، وقعد للناس، فقد أذن لمن أراد الدخول عليه في دخوله، فإن الأمر في ذلك بخلاف ما ظن؛ وذلك أنه ليس لأحد دخول ملك غيره بغير ضرورة ألجأته إليه، أو بغير سبب أباح له دخوله إلا بإذن ربه، لا سيما إذا كان فيه متاع، فإن كان التاجر قد عرف منه أن فتحه حانوته إذن منه لمن أراد دخوله في الدخول، فذلك بعد راجع إلى ما قلنا من أنه لم يدخله من دخله إلا بإذنه", "qawaid": ["الدلالة العقلية", "الإجماع"], "tabi": ""}]}], "30": [{"id": 4640, "kinds": "ترجيح،نقد،توجيه،نقل", "text": "ذكر ابنُ عطية (6/ 373) أنّ حفظ الفروج يحتمل أن يريد به: في الزنا، ويحتمل أن يريد: بستر العورة، ثم رجَّح العموم فقال: «والأظهر أن الجميع مراد، واللفظ عام». وساق (6/ 374) قول أبي العالية، وانتقده مستندًا لدلالة العموم، فقال: «ولا وجه لهذا التخصيص عندي».", "mawaqif": [{"taliq": 4640, "mi": 0, "aya": 30, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 373", "qawl": "العموم", "nass": "والأظهر أن الجميع مراد، واللفظ عام", "qawaid": ["العموم"], "tabi": ""}]}, {"id": 4641, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (6/ 373) أن قوله: {قُلْ لِلْمُؤْمِنِينَ} بمنزلة قوله: انْهَهم، فقول: {يَغُضُّوا} جواب الأمر، وذكر أن المازني قال بأن المعنى: قل لهم: غضوا يَغُضُّوا. وانتقد ذلك مستندًا إلى دلالة العقل، فقال: «ويلحق هذين من الاعتراض أن الجواب خبرٌ من الله، وقد يوجد مَن لا يغض، وينفصل بأنّ المراد: يكونون في حكم مَن يغض».", "mawaqif": [{"taliq": 4641, "mi": 0, "aya": 30, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 373", "qawl": "", "nass": "ويلحق هذين من الاعتراض أن الجواب خبر من الله، وقد يوجد من لا يغض، وينفصل بأن المراد: يكونون في حكم من يغض", "qawaid": ["الدلالة العقلية"], "tabi": ""}]}, {"id": 4642, "kinds": "تعليق", "text": "علَّق ابنُ كثير (10/ 212 - 213) على هذا الحديث بقوله: «وكذا رواه الإمام أحمد، عن هشيم، عن يونس بن عبيد، به. ورواه أبو داود والترمذي والنسائي، من حديثه أيضًا. وقال الترمذي: حسن صحيح. وفي رواية لبعضهم: فقال: «أطرِق بصرك». يعني: انظر إلى الأرض. والصرف أعم؛ فإنه قد يكون إلى الأرض، وإلى جهة أخرى».", "mawaqif": [{"taliq": 4642, "mi": 0, "aya": 30, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "10/ 212 - 213", "qawl": "", "nass": "وكذا رواه الإمام أحمد، عن هشيم، عن يونس بن عبيد، به. ورواه أبو داود والترمذي والنسائي، من حديثه أيضا. وقال الترمذي: حسن صحيح. وفي رواية لبعضهم: فقال: «أطرق بصرك", "qawaid": [], "tabi": ""}]}], "31": [{"id": 4643, "kinds": "نقل", "text": "ذكر ابنُ عطية (6/ 374) أن حفظ الفروج يعم الفواحش، وستر العورة، وما دون ذلك مِمّا فيه حِفْظ.", "mawaqif": [{"taliq": 4643, "mi": 0, "aya": 31, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 374", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 4644, "kinds": "تعليق،نقل", "text": "ساق ابنُ كثير (10/ 217) قول ابن مسعود، ثم علَّق بقوله: «يعني: على ما كان يَتَعاناه نساء العرب، مِن المُقَنَّعة التي تُجَلِّل ثيابها، وما يبدو مِن أسافل الثياب فلا حرج عليها فيه؛ لأنّ هذا لا يمكن إخفاؤه. ونظيره في زي النساء ما يظهر من إزارها، وما لا يمكن إخفاؤه».", "mawaqif": [{"taliq": 4644, "mi": 0, "aya": 31, "alam": "ابن كثير", "fil": "ساق", "kind": "نقل", "ref": "10/ 217", "qawl": "ابن مسعود", "nass": "يعني: على ما كان يتعاناه نساء العرب، من المقنعة التي تجلل ثيابها، وما يبدو من أسافل الثياب فلا حرج عليها فيه؛ لأن هذا لا يمكن إخفاؤه. ونظيره في زي النساء ما يظهر من إزارها، وما لا يمكن إخفاؤه", "qawaid": [], "tabi": ""}]}, {"id": 4645, "kinds": "تعليق،نقل", "text": "علَّق ابنُ كثير (10/ 217 - 218 بتصرف) على هذا القول الذي قاله ابن عباس، وابن عمر، وعطاء، وعكرمة، وسعيد بن جبير، وأبو الشعثاء، والضحاك، وإبراهيم النخعي، ومَن معهم، فقال: «وهذا يحتمل أن يكون تفسيرًا للزينة التي نُهِينَ عن إبدائها، ويحتمل أنّ ابن عباس ومن تابعه أرادوا تفسير ما ظهر منها بالوجه والكفين، وهذا هو المشهور عند الجمهور، ويستأنس له بالحديث الذي رواه أبو داود في سننه». وساق حديث عائشة: أنّ أسماء بنت أبي بكر دخلت على النبي صلى الله عليه وسلم … الحديث، وسيأتي في الآثار المتعلقة بالآية.", "mawaqif": [{"taliq": 4645, "mi": 0, "aya": 31, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "10/ 217 - 218 بتصرف", "qawl": "", "nass": "وهذا يحتمل أن يكون تفسيرا للزينة التي نهين عن إبدائها، ويحتمل أن ابن عباس ومن تابعه أرادوا تفسير ما ظهر منها بالوجه والكفين، وهذا هو المشهور عند الجمهور، ويستأنس له بالحديث الذي رواه أبو داود في سننه", "qawaid": [], "tabi": ""}]}, {"id": 4647, "kinds": "تعليق،نقل", "text": "ذكر ابنُ كثير (10/ 212) أن قوله: {أو نسائهن} يعني: أنه يجوز للمرأة المسلمة أن تظهر زينتها للنساء المسلمات دون نساء أهل الذمة، وعلَّق على قول عطاء بقوله: «فهذا -إن صحَّ- محمول على حال الضرورة، أو أنّ ذلك من باب الامتهان، ثم إنه ليس فيه كشف عورة ولا بُدَّ».", "mawaqif": [{"taliq": 4647, "mi": 0, "aya": 31, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "10/ 212", "qawl": "عطاء بقوله", "nass": "فهذا -إن صح- محمول على حال الضرورة، أو أن ذلك من باب الامتهان، ثم إنه ليس فيه كشف عورة ولا بد", "qawaid": [], "tabi": ""}]}, {"id": 4648, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (6/ 377) هذه القراءة، ثم علَّق بقوله: «فيدخل فيه عبدُ الغير».", "mawaqif": [{"taliq": 4648, "mi": 0, "aya": 31, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 377", "qawl": "", "nass": "فيدخل فيه عبد الغير", "qawaid": [], "tabi": ""}]}, {"id": 4649, "kinds": "نقل", "text": "عقَّب ابنُ كثير (6/ 48) (ت. سلامة) على هذا الحديث بقوله: «وقد ذكر الحافظ ابن عساكر في تاريخه في ترجمة حديج الخصي -مولى معاوية- أنّ عبد الله بن مسعدة الفزاري كان أسود شديد الأدمة، وأنه قد كان النبي صلى الله عليه وسلم وهبه لابنته فاطمة، فربَّته، ثم أعتقته».", "mawaqif": []}, {"id": 4650, "kinds": "نقل", "text": "نسب ابن عطية (6/ 376) قولًا لابن عباس يخالف هذا القول، فقال: «وقال ابن عباس وجماعة: لا يدخل العبد على سيدته فيرى شعرها ونحو ذلك، إلا أن يكون وغدًا» يعني: صبيًّا، أو ضعيف العقل. ينظر: لسان العرب (وغد).", "mawaqif": [{"taliq": 4650, "mi": 0, "aya": 31, "alam": "ابن عطية", "fil": "نسب", "kind": "نقل", "ref": "6/ 376", "qawl": "", "nass": "وقال ابن عباس وجماعة: لا يدخل العبد على سيدته فيرى شعرها ونحو ذلك، إلا أن يكون وغدا", "qawaid": [], "tabi": ""}]}], "32": [{"id": 4651, "kinds": "بيان،تعليق،نقل", "text": "ذكر ابنُ عطية (6/ 380) هذه القراءة، وبيَّن أن الجمهور على {عبادكم}، وأنّ معنى القراءتين واحد، ثم علَّق بقوله: «إلا أنّ قرينة الترفيع بالنكاح يؤيد قراءة الجمهور».", "mawaqif": [{"taliq": 4651, "mi": 0, "aya": 32, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 380", "qawl": "", "nass": "إلا أن قرينة الترفيع بالنكاح يؤيد قراءة الجمهور", "qawaid": [], "tabi": ""}]}, {"id": 4652, "kinds": "نقل", "text": "ذكر ابنُ عطية (6/ 380) أنّ عموم اللفظة في الآية هو الدافع لهذا القول بالنسخ.", "mawaqif": [{"taliq": 4652, "mi": 0, "aya": 32, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 380", "qawl": "بالنسخ", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 4653, "kinds": "نقد،بيان،نقل", "text": "ذكر ابنُ عطية (6/ 380) أنّ النقّاش قال بأن هذه الآية حُجَّة على مَن قال: إنّ القاضي يُفَرِّق بين الزوجين إذا كان الزوج فقيرًا لا يقدر على النفقة؛ لأن الله تعالى قال: {يغنهم الله} ولم يقل: يفرق بينهما «. وانتقده مستندًا إلى الدلالة العقلية، فقال:» وهذا انتزاع ضعيف، وليست هذه الآية حكمًا فيمَن عجز عن النفقة، وإنما هي وعد بالإغناء، كما وعد به مع التفرق في قوله: {وإنْ يَتَفَرَّقا يُغْنِ اللَّهُ كُلًّا مِن سَعَتِهِ} [النساء: 130]، ونفحات رحمة الله مأمولة في كل حال، موعود بها\".", "mawaqif": [{"taliq": 4653, "mi": 0, "aya": 32, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 380", "qawl": "", "nass": ". وانتقده مستندا إلى الدلالة العقلية، فقال:", "qawaid": [], "tabi": ""}]}], "33": [{"id": 4654, "kinds": "نقد،توجيه،بيان،نقل", "text": "ذكر ابنُ عطية (6/ 381) أنّ الله أمر في هذه الآية كلَّ مَن يتعذر عليه النكاح ولا يجده بأي وجه تعذُّر أن يستعف، وبين أنه لما كان أغلب الموانع على النكاح عدَم المال وعَدَ بالإغناء من فضله، ثم قال: «فعلى هذا التأويل يعمَّ الأمر بالاستعفاف كل مَن تعذر عليه النكاح بأي وجه تعذر». ثم ذكر أن جماعة من المفسرين قالت بأنّ النكاح في هذه الآية اسم ما يُمْهر وينفق في الزواج؛ كاللحاف واللباس لما يلتحف به ويلبس، ووجَّهه بقوله: «وحملهم على هذا قوله: {حتى يغنيهم الله من فضله}، فظنُّوا أنّ المأمور بالاستعفاف إنما هو من عُدِم المال الذي يتزوج به». وانتقده مستندًا لدلالة العموم، فقال: «وفي هذا القول تخصيص المأمورين بالاستعفاف، وذلك ضعيف».", "mawaqif": [{"taliq": 4654, "mi": 0, "aya": 33, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 381", "qawl": "", "nass": "فعلى هذا التأويل يعم الأمر بالاستعفاف كل من تعذر عليه النكاح بأي وجه تعذر", "qawaid": ["العموم"], "tabi": ""}]}, {"id": 4656, "kinds": "تعليق", "text": "علَّق ابنُ عطية (6/ 372) على قول عبيدة بقوله: «وهذا في زمنه القول الذي قبله». يعني: القول بأن الخير هو الوفاء والصدق.", "mawaqif": [{"taliq": 4656, "mi": 0, "aya": 33, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "6/ 372", "qawl": "عبيدة بقوله", "nass": "وهذا في زمنه القول الذي قبله", "qawaid": [], "tabi": ""}]}, {"id": 4658, "kinds": "تعليق", "text": "علَّق ابنُ عطية (6/ 382) على هذا القول بقوله: «وعِلَّة ذلك: أنّه إذا وُضِع من أول نجم ربما عجز العبد؛ فرجع هو وماله إلى السيد؛ فعادت إليه وضِيعَتُه، وهي شبه الصدقة».", "mawaqif": [{"taliq": 4658, "mi": 0, "aya": 33, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "6/ 382", "qawl": "بقوله", "nass": "وعلة ذلك: أنه إذا وضع من أول نجم ربما عجز العبد؛ فرجع هو وماله إلى السيد؛ فعادت إليه وضيعته، وهي شبه الصدقة", "qawaid": [], "tabi": ""}]}, {"id": 4660, "kinds": "غيره", "text": "قال ابنُ عطية (6/ 383): «قوله: {إنْ أرَدْنَ تَحَصُّنًا} راجع إلى الفتيات، وذلك أنّ الفتاة إذا أرادت التحصن فحينئذ يتصور، ويمكن أن يكون السيد مكرِهًا، ويمكن أن يُنهى عن الإكراه، وإذا كانت الفتاة لا تريد التحصن فلا يتصور أن يُقال للسيد: لا تكرهها؛ لأنّ الإكراه لا يتصور فيها وهي مريدة للزنا، فهذا أمر في سادة وفتيات حالهم هذه، وذهب هذا النظر عن كثير من المفسرين، فقال بعضهم: قوله: {إنْ أرَدْنَ} راجع إلى {الأَيامى} في قوله سبحانه: {وأَنْكِحُوا الأَيامى مِنكُمْ}، وقال بعضهم: هذا الشرط في قوله: {إنْ أرَدْنَ} ملغًى، ونحو هذا مما ضُعِّف».", "mawaqif": [{"taliq": 4660, "mi": 0, "aya": 33, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 383", "qawl": "", "nass": "قوله: {إن أردن تحصنا} راجع إلى الفتيات، وذلك أن الفتاة إذا أرادت التحصن فحينئذ يتصور، ويمكن أن يكون السيد مكرها، ويمكن أن ينهى عن الإكراه، وإذا كانت الفتاة لا تريد التحصن فلا يتصور أن يقال للسيد: لا تكرهها؛ لأن الإكراه لا يتصور فيها وهي مريدة للزنا، فهذا أمر في سادة وفتيات حالهم هذه، وذهب هذا النظر عن كثير من المفسرين، فقال بعضهم: قوله: {إن أردن} راجع إلى {الأيامى} في قوله سبحانه: {وأنكحوا الأيامى منكم}، وقال بعضهم: هذا الشرط في قوله: {إن أردن} ملغى، ونحو هذا مما ضعف", "qawaid": [], "tabi": ""}]}], "35": [{"id": 4661, "kinds": "تعليق", "text": "علّق ابنُ القيم (2/ 240) على ما جاء في هذا القول، فقال: «وقد فُسِّر: {الله نور السماوات والأرض} بكونه: منور السماوات والأرض، وهادي أهل السماوات والأرض، فبنوره اهتدى أهل السماوات والأرض، وهذا إنما هو فعله، وإلا فالنور الذي هو مِن أوصافه قائمٌ به، ومنه اشتق له اسم: النور، الذي هو أحد الأسماء الحسنى».", "mawaqif": [{"taliq": 4661, "mi": 0, "aya": 35, "alam": "ابن القيم", "fil": "علق", "kind": "تعليق", "ref": "2/ 240", "qawl": "", "nass": "وقد فسر: {الله نور السماوات والأرض} بكونه: منور السماوات والأرض، وهادي أهل السماوات والأرض، فبنوره اهتدى أهل السماوات والأرض، وهذا إنما هو فعله، وإلا فالنور الذي هو من أوصافه قائم به، ومنه اشتق له اسم: النور، الذي هو أحد الأسماء الحسنى", "qawaid": [], "tabi": ""}]}, {"id": 4667, "kinds": "ترجيح", "text": "قال ابنُ عطية (6/ 387): «وقوله: {كَأَنَّها كَوْكَبٌ دُرِّيٌّ} أي: في الإنارة والضوء، وذلك يحتمل معنين: إما أن يريد أنها بالمصباح كذلك، وإما أن يريد أنها في نفسها لصفائها وجودة جوهرها كذلك». ثم رجّح مستندًا إلى الدلالة العقلية الاحتمال الثاني بقوله: «وهذا التأويل أبلغُ في التعاون على النور».", "mawaqif": [{"taliq": 4667, "mi": 0, "aya": 35, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 387", "qawl": "", "nass": "وقوله: {كأنها كوكب دري} أي: في الإنارة والضوء، وذلك يحتمل معنين: إما أن يريد أنها بالمصباح كذلك، وإما أن يريد أنها في نفسها لصفائها وجودة جوهرها كذلك", "qawaid": ["الدلالة العقلية"], "tabi": ""}]}, {"id": 4668, "kinds": "غيره", "text": "قال ابنُ عطية (6/ 388): «والزيتون مِن أعظم الثمار نماء واطراد أفنان وغضارة، ولا سيما بالشام، والرمان كذلك، والعيان يقضي بذلك».", "mawaqif": [{"taliq": 4668, "mi": 0, "aya": 35, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "6/ 388", "qawl": "", "nass": "والزيتون من أعظم الثمار نماء واطراد أفنان وغضارة، ولا سيما بالشام، والرمان كذلك، والعيان يقضي بذلك", "qawaid": [], "tabi": ""}]}], "36": [{"id": 4671, "kinds": "تعليق", "text": "علّق ابنُ عطية (6/ 390) على ما جاء في هذا القول، فقال: «وقال الحسن بن أبي الحسن: أراد: بيت المقدس، وسماه بيوتًا مِن حيث فيه مواضع يتحيز بعضها عن بعض، ويؤثر أنّ عادة بني إسرائيل في وقِيد بيتِ المقدس كانت غايةً في التهمم به، وكان الزيت منتخبًا مختومًا على ظروفه، قد صنع صنعة وقُدِّس حتى لا يجزى الوقيد بغيره، فكان لهذا ونحوه أضوأ بيوت الأرض».", "mawaqif": [{"taliq": 4671, "mi": 0, "aya": 36, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "6/ 390", "qawl": "", "nass": "وقال الحسن بن أبي الحسن: أراد: بيت المقدس، وسماه بيوتا من حيث فيه مواضع يتحيز بعضها عن بعض، ويؤثر أن عادة بني إسرائيل في وقيد بيت المقدس كانت غاية في التهمم به، وكان الزيت منتخبا مختوما على ظروفه، قد صنع صنعة وقدس حتى لا يجزى الوقيد بغيره، فكان لهذا ونحوه أضوأ بيوت الأرض", "qawaid": [], "tabi": ""}]}, {"id": 4675, "kinds": "ترجيح،توجيه،تعليق،نقل", "text": "علّق ابنُ جرير (17/ 319) على القراءتين، فقال: «قوله: {يسبح له} فقرأ ذلك عامة قراء الأمصار: {يسبح له} بضم الياء، وكسر الباء، بمعنى: يصلي له فيها رجال، وبجعل {يسبح} [الإسراء: 44] فعلًا للرجال وخبرًا عنهم، وترفع به الرجال. سوى عاصم، وابن عامر، فإنهما قرآ ذلك: «يُسَبَّحُ لَهُ» بضم الياء، وفتح الباء، على ما لم يسم فاعله، ثم يرفعان الرجال بخبر ثان مضمر، كأنهما أرادا: يسبح اللهَ في البيوت التي أذن الله أن ترفع، فسبح له رجال؛ فرفعا الرجال بفعل مضمر». ثم رجح مستندًا إلى ظاهر الآية قراءة كسر الياء، فقال: «والقراءة التي هي أولاهما بالصواب: قراءة مَن كسر الباء، وجعله خبرًا للرجال، وفعلًا لهم. وإنما كان الاختيار رفع الرجال بمضمر مِن الفعل لو كان الخبر عن البيوت لا يتم إلا بقوله: {يسبح له فيها}، فأمّا والخبر عنها دون ذلك تامٌّ فلا وجه لتوجيه قوله: {يسبح له} إلى غيره، أي: غير الخبر عن الرجال».\nوعلّق ابنُ كثير (6/ 67) على قراءة الفتح في الباء: \"ومَن قرأ مِن القرأة «يُسَبَّحُ لَهُ فِيها بِالغُدُوِّ والآصالِ» -بفتح الباء من «يُسَبَّحُ» على أنه مبني لما لم يسم فاعله- وقف على قوله: {والآصال} وقفًا تامًّا، وابتدأ بقوله: {رجال لا تلهيهم تجارة ولا بيع عن ذكر الله}، وكأنه مفسر للفاعل المحذوف، كما قال الشاعر:\nليبك يزيد ضارعٌ لخصومة … ومُخْتَبطٌ مما تُطيح الطّوائحُ\nكأنه قال: مَن يبكيه؟ قال: هذا يبكيه. وكأنه قيل: مَن يسبح له فيها؟ قال: {رجال} «. ثم علّق على القراءة الأخرى، فقال:» وأما على قراءة من قرأ: {يسبح} -بكسر الباء- فجعله فعلًا، وفاعله: {رجال}، فلا يحسن الوقف إلا على الفاعل؛ لأنه تمام الكلام\".", "mawaqif": [{"taliq": 4675, "mi": 0, "aya": 36, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "17/ 319", "qawl": "", "nass": "قوله: {يسبح له} فقرأ ذلك عامة قراء الأمصار: {يسبح له} بضم الياء، وكسر الباء، بمعنى: يصلي له فيها رجال، وبجعل {يسبح} [الإسراء: 44] فعلا للرجال وخبرا عنهم، وترفع به الرجال. سوى عاصم، وابن عامر، فإنهما قرآ ذلك: «يسبح له", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 4675, "mi": 0, "aya": 36, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "6/ 67", "qawl": "", "nass": "يسبح له فيها بالغدو والآصال", "qawaid": [], "tabi": ""}]}], "37": [{"id": 4676, "kinds": "نقل", "text": "ذكر ابنُ كثير (6/ 68) بعض الأحاديث الدالة على أفضلية صلاة المرأة في بيتها، ثم قال معلّقًا: «هذا ويجوز لها شهود جماعة الرجال، بشرط أن لا تؤذي أحدًا مِن الرجال بظهور زينة، ولا ريحٍ طيب، كما ثبت في الصحيحين عن عبد الله بن عمر أنه قال: قال رسول الله صلى الله عليه وسلم: «لا تمنعوا إماء الله مساجد الله»».", "mawaqif": [{"taliq": 4676, "mi": 0, "aya": 37, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "6/ 68", "qawl": "", "nass": "هذا ويجوز لها شهود جماعة الرجال، بشرط أن لا تؤذي أحدا من الرجال بظهور زينة، ولا ريح طيب، كما ثبت في الصحيحين عن عبد الله بن عمر أنه قال: قال رسول الله صلى الله عليه وسلم: «لا تمنعوا إماء الله مساجد الله»", "qawaid": [], "tabi": ""}]}, {"id": 4677, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (17/ 323) غير القول الذي أسنده عوف.", "mawaqif": []}, {"id": 4678, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (17/ 324) غير قول ابن عباس.", "mawaqif": []}], "40": [{"id": 4680, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (6/ 395) نحو قول ابن عباس، فقال: «وذهب بعض الناس إلى أنّ في هذا المثال أجزاء تُقابل أجزاء من المُمَثَّل فقال: الظلمات: الأعمال الفاسدة والمعتقدات الباطلة. والبحر اللجي: صدر الكافر وقلبه. واللجي معناه: ذو اللجة، وهي معظم الماء وغمره، واجتماع مائه أشد لظلمته. والموج هو: الضلال والجهالة التي غمرت قلبه والفِكَر المعوجة. والسحاب هو: شهوته في الكفر، وإعراضه عن الإيمان، وما رِين به على قلبه». ثم علّق بقوله: «وهذا التأويل سائغ، وألّا يُقدَّر هذا التقابلُ سائغٌ».", "mawaqif": [{"taliq": 4680, "mi": 0, "aya": 40, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 395", "qawl": "ابن عباس", "nass": "وذهب بعض الناس إلى أن في هذا المثال أجزاء تقابل أجزاء من الممثل فقال: الظلمات: الأعمال الفاسدة والمعتقدات الباطلة. والبحر اللجي: صدر الكافر وقلبه. واللجي معناه: ذو اللجة، وهي معظم الماء وغمره، واجتماع مائه أشد لظلمته. والموج هو: الضلال والجهالة التي غمرت قلبه والفكر المعوجة. والسحاب هو: شهوته في الكفر، وإعراضه عن الإيمان، وما رين به على قلبه", "qawaid": [], "tabi": ""}]}, {"id": 4682, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (17/ 330 - 331) في تفسير عموم الآية غير قول أُبَيٍّ، وقول ابن عباس من طريق العوفي، وقول قتادة من طريق معمر، وقول ابن زيد.", "mawaqif": []}, {"id": 4683, "kinds": "ترجيح،نقل", "text": "أفادت الآثارُ أن معنى قوله: {ومن لم يجعل الله له نورا فما له من نور}: مَن لم يهده الله لم يهتد. وقد ذكر ابنُ عطية (6/ 396) إضافةً إلى هذا القول قولًا آخر هو: «مَن لم ي? وينوّر حاله بالعفو والرحمة فلا رحمة له». ثم رجّح مستندًا إلى ظاهر اللفظ ودلالة العقل القولَ الأول، فقال: «والأول أبين وأليق بلفظ الآية، وأيضًا فذلك متلازم؛ نور الآخرة إنما هو لمن نوّر قلبه في الدنيا وهُدِي، وقد قررت الشريعة أنّ من مرَّ لآخرته على كفره فهو غير مرحوم ولا مغفور له».", "mawaqif": [{"taliq": 4683, "mi": 0, "aya": 40, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 396", "qawl": "قولا آخر", "nass": "من لم ي? وينور حاله بالعفو والرحمة فلا رحمة له", "qawaid": ["ظاهر الآية ولفظها", "الدلالة العقلية"], "tabi": ""}]}], "41": [{"id": 4684, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (17/ 333) غير قول مجاهد.", "mawaqif": []}, {"id": 4685, "kinds": "نقل", "text": "ذكر ابنُ عطية (6/ 397) في قوله: {كل قد علم صلاته وتسبيحه} عدة أقوال، فقال: «وقوله: {كل قد علم صلاته وتسبيحه} قال الحسن: المعنى: كل قد علم صلاة نفسه وتسبيح نفسه فهو يثابر عليهما ويؤديهما. وقال مجاهد: الصلاة للبشر، والتسبيح لما عداهم. وقالت فرقة: المعنى: كل قد علم صلاة الله وتسبيح الله اللذيْن أمر بهما وهَدى إليهما. فهذه إضافة خلق إلى خالق. وقال الزجاج وغيره: المعنى: كل قد علم الله صلاته وتسبيحه. فالضميران للكل».", "mawaqif": [{"taliq": 4685, "mi": 0, "aya": 41, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 397", "qawl": "", "nass": "وقوله: {كل قد علم صلاته وتسبيحه} قال الحسن: المعنى: كل قد علم صلاة نفسه وتسبيح نفسه فهو يثابر عليهما ويؤديهما. وقال مجاهد: الصلاة للبشر، والتسبيح لما عداهم. وقالت فرقة: المعنى: كل قد علم صلاة الله وتسبيح الله اللذين أمر بهما وهدى إليهما. فهذه إضافة خلق إلى خالق. وقال الزجاج وغيره: المعنى: كل قد علم الله صلاته وتسبيحه. فالضميران للكل", "qawaid": [], "tabi": ""}]}], "43": [{"id": 4686, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (17/ 337) غير قول ابن زيد.", "mawaqif": []}, {"id": 4687, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ جرير (17/ 337) هذه القراءة، ثم رجّح مستندًا إلى إجماع الحجة من القرّاء قراءةَ {خلاله}: «وأما قراء الأمصار فإنهم على القراءة الأخرى: {من خلاله}، وهي التي نختار؛ لإجماع الحجة من القراء عليها».", "mawaqif": [{"taliq": 4687, "mi": 0, "aya": 43, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "17/ 337", "qawl": "", "nass": "وأما قراء الأمصار فإنهم على القراءة الأخرى: {من خلاله}، وهي التي نختار؛ لإجماع الحجة من القراء عليها", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}]}, {"id": 4688, "kinds": "غيره", "text": "قال ابنُ كثير (6/ 72): «وقوله: {وينزل من السماء من جبال فيها من برد} قال بعض النحاة: {من} الأولى لابتداء الغاية، والثانية للتبعيض، والثالثة لبيان الجنس. وهذا إنّما يجيء على قول مَن ذهب مِن المفسرين إلى أن قوله: {من جبال فيها من برد} معناه: أنّ في السماء جبال برد ينزل الله منها البرد. وأمّا من جعل الجبال ههنا عبارة عن السحاب، فإن {من} الثانية عند هذا لابتداء الغاية أيضًا، لكنها بدل من الأولى».", "mawaqif": [{"taliq": 4688, "mi": 0, "aya": 43, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "6/ 72", "qawl": "", "nass": "وقوله: {وينزل من السماء من جبال فيها من برد} قال بعض النحاة: {من} الأولى لابتداء الغاية، والثانية للتبعيض، والثالثة لبيان الجنس. وهذا إنما يجيء على قول من ذهب من المفسرين إلى أن قوله: {من جبال فيها من برد} معناه: أن في السماء جبال برد ينزل الله منها البرد. وأما من جعل الجبال ههنا عبارة عن السحاب، فإن {من} الثانية عند هذا لابتداء الغاية أيضا، لكنها بدل من الأولى", "qawaid": [], "tabi": ""}]}], "45": [{"id": 4689, "kinds": "تعليق،نقل", "text": "ذكر ابنُ جرير (17/ 339) هذه القراءة، وقراءة من قرأ ذلك {خلق}، ثم علّق قائلًا: «وهما قراءتان مشهورتان متقاربتا المعنى، وذلك أنّ الإضافة في قراءة من قرأ ذلك «خالِقُ» تدل على أنّ معنى ذلك المضي، فبأيتهما قرأ القارئ فمصيب».", "mawaqif": [{"taliq": 4689, "mi": 0, "aya": 45, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "17/ 339", "qawl": "", "nass": "وهما قراءتان مشهورتان متقاربتا المعنى، وذلك أن الإضافة في قراءة من قرأ ذلك «خالق", "qawaid": [], "tabi": ""}]}], "53": [{"id": 4690, "kinds": "توجيه،نقل", "text": "لم يذكر ابنُ جرير (17/ 344) في معنى: {قُلْ لا تُقْسِمُوا طاعَةٌ مَعْرُوفَةٌ} سوى قول مجاهد.\nوذكر ابنُ عطية (6/ 403 - 404) في معنى الآية عدة احتمالات: «أحدها: النهي عن القسم الكاذب، إذ عرف أنّ طاعتهم دَغْلَةٌ رديَّة». ووجَّهه بقوله: «فكأنّه يقول: لا تُغالِطوا؛ فقد عُرِف ما أنتم عليه». «والثاني: أن يكون المعنى: لا تتكلفوا القسم، طاعة عرف متوسطة على قدر الاستطاعة أمْثل وأَجْدى عليكم». ووجَّهه بقوله: «وفي هذا الوجْه إبقاءٌ عليهم». «والثالث: أن يكون المعنى: لا تقنعوا بالقسم، طاعة تُعْرَف منكم وتظهر عليكم هو المطلوب منكم». «والرابع: أن يكون المعنى: لا تقنعوا لأنفسكم بإرضائنا بالقسم، طاعة الله معروفة، وشرعه وجهاد عدُوِّه مهيع لائح».", "mawaqif": [{"taliq": 4690, "mi": 0, "aya": 53, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 403 - 404", "qawl": "", "nass": "أحدها: النهي عن القسم الكاذب، إذ عرف أن طاعتهم دغلة ردية", "qawaid": [], "tabi": ""}]}], "55": [{"id": 4691, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ عطية (6/ 405) عن الضحاك -نقلًا من كتاب النقّاش- أنّه قال: «هذه الآية تتضمن خلافةَ أبي بكر، وعمر، وعثمان، وعلي رضي الله عنهم؛ لأنهم أهلُ الإيمان وعمل الصالحات، وقد قال رسول الله صلى الله عليه وسلم: «الخلافة بعدي ثلاثون سنة»». ثم رجَّح قائلًا: «والصحيح في الآية أنها في استخلاف الجمهور». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 4691, "mi": 0, "aya": 55, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 405", "qawl": "", "nass": "هذه الآية تتضمن خلافة أبي بكر، وعمر، وعثمان، وعلي رضي الله عنهم؛ لأنهم أهل الإيمان وعمل الصالحات، وقد قال رسول الله صلى الله عليه وسلم: «الخلافة بعدي ثلاثون سنة»", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}], "58": [{"id": 4694, "kinds": "تعليق", "text": "علَّق ابنُ عطية (6/ 407) على قول ابن عباس بقوله: «وهذه العبارة بـ» ترك الناس «إغلاظٌ وزجرٌ، إذ لم تُلْتَزَم حقَّ الالتزام، وإلا فما قال الله تعالى هو المعتَقد في ذلك عند العلماء، المكتوب في تواليفهم، أعني: أنّ الكرم التقوى، وأما أمْر الاستئذان فإنّ تغيير المباني والحُجُب أغنتْ عن كثيرٍ من الاستئذان، وصيَّرته على حدٍّ آخر، وأين أبواب المنازل اليوم من مواضع النوم؟».", "mawaqif": [{"taliq": 4694, "mi": 0, "aya": 58, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "6/ 407", "qawl": "ابن عباس", "nass": "وهذه العبارة ب", "qawaid": [], "tabi": ""}]}, {"id": 4695, "kinds": "تعليق،نقل", "text": "علَّق ابنُ عطية (6/ 407) على قول ابن عباس بقوله: «فهي الآن واجبةٌ في كثير مِن مساكن المسلمين في البوادي والصحاري ونحوها».\nوذكر ابنُ كثير (10/ 271) هذا الأثر من رواية ابن أبي حاتم بسنده عن الربيع بن سليمان، عن ابن وهب، عن سليمان بن بلال، عن عمرو بن أبي عمرو، عن عكرمة، عن ابن عباس موقوفًا، ثم علَّق عليه بقوله: «وهذا إسناد صحيح إلى ابن عباس».", "mawaqif": [{"taliq": 4695, "mi": 0, "aya": 58, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "6/ 407", "qawl": "ابن عباس", "nass": "فهي الآن واجبة في كثير من مساكن المسلمين في البوادي والصحاري ونحوها", "qawaid": [], "tabi": ""}, {"taliq": 4695, "mi": 0, "aya": 58, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "10/ 271", "qawl": "", "nass": "وهذا إسناد صحيح إلى ابن عباس", "qawaid": [], "tabi": ""}]}], "60": [{"id": 4696, "kinds": "نقل", "text": "نقل ابنُ عطية (6/ 408 بتصرف) قولًا ولم ينسبه: «أن المرأة قد تقعد عن الولد وفيها مُستَمتَع، فلمّا كان الغالب من النساء أن ذوات هذا السن لا مذهب للرجل فيهن أُبيح لهنَّ ما لم يُبَح لغيرهن، وأُزيل عنهن كلفة التحفظ المتعب؛ إذ علة التحفظ مرتفعة فيهن».", "mawaqif": [{"taliq": 4696, "mi": 0, "aya": 60, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "6/ 408 بتصرف", "qawl": "", "nass": "أن المرأة قد تقعد عن الولد وفيها مستمتع، فلما كان الغالب من النساء أن ذوات هذا السن لا مذهب للرجل فيهن أبيح لهن ما لم يبح لغيرهن، وأزيل عنهن كلفة التحفظ المتعب؛ إذ علة التحفظ مرتفعة فيهن", "qawaid": [], "tabi": ""}]}], "61": [{"id": 4698, "kinds": "خلاف،نقد،بيان،نقل", "text": "ذكر ابنُ عطية (6/ 412) قولًا عن بعض الناس: بأنّ هذه الآية منسوخة بآية الاستئذان الذي أُمِر به الناس، وهي قوله تعالى: {لا تَدْخُلُوا بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتّى تَسْتَأْنِسُوا وتُسَلِّمُوا عَلى أهْلِها} [النور: 27]، فقالوا: إذا كان الإذن محجورًا فالطعام أحرى. وذكر أيضًا عن فرقة نسخًا بيْن هذه الآية وبيْن قوله تعالى: {ولا تَأْكُلُوا أمْوالَكُمْ بَيْنَكُمْ بِالباطِلِ} [البقرة: 188]. ثم انتقد (6/ 413) كلا القولين بأن «النسخ لا يتصور في شيءٍ من هذه الآيات، بل هي كلها محكمة». وبيَّن ذلك بقوله: «أما قوله تعالى: {ولا تَأْكُلُوا أمْوالَكُمْ بَيْنَكُمْ بِالباطِلِ} ففي التعدِّي والخدع والغرر واللهو والقمار ونحوه، وأما هذه الآية ففي إباحة طعام هذه الأصناف التي يَسُرُّها استباحة طعامها على هذه الصفة، وأما آية الإذن فعِلَّة إيجاب الاستئذان خوف الكشف، فإذا استأذن الرجل خوف الكشفة، ودخل المنزل بالوجْه المباح صحَّ له بعد ذلك أكل الطعام بهذه الإباحة، وليس يكون في الآيات نسخٌ، فتأمله».", "mawaqif": [{"taliq": 4698, "mi": 0, "aya": 61, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "6/ 412", "qawl": "", "nass": "النسخ لا يتصور في شيء من هذه الآيات، بل هي كلها محكمة", "qawaid": [], "tabi": ""}]}], "64": [{"id": 4702, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (17/ 392) في معنى: {قَدْ يَعْلَمُ ما أنْتُمْ عَلَيْهِ} سوى قول ابن زيد.", "mawaqif": []}]}, "athar": {"53249": {"num": 53249, "aya": 33, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق يونس-: دينًا، وأمانة."}, "53250": {"num": 53250, "aya": 33, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق قتادة - قال: إن علمتم عندهم مالًا."}, "53251": {"num": 53251, "aya": 33, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق يونس- في قوله تعالى: {فكاتبوهم إن علمتم فيهم خيرا}، قال: الخير: القرآن، والإسلام. ="}, "53254": {"num": 53254, "aya": 33, "qail": "الحسن", "tabaqa": "تابعي", "bab": "", "text": "وقال الحسن: {إن علمتم فيهم خيرًا} صدقًا وأمانة، مَن أعطاه كان مأجورًا، ومن سُئِل فردَّ خيرًا كان مأجورًا."}, "53256": {"num": 53256, "aya": 33, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "", "text": "عن عطاء [بن أبي رباح]-من طريق عبد الملك بن أبي سليمان-: أداء، ومالًا."}, "53257": {"num": 53257, "aya": 33, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "", "text": "عن عطاء [بن أبي رباح]-من طريق عبد الملك- {إن علمتم فيهم خيرًا}، قال: خيرًا: أداء، وأمانة."}, "53259": {"num": 53259, "aya": 33, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن ابن جريج، قال: قلت لعطاء بن أبي رباح: ما قوله: {فكاتبوهم إن علمتم فيهم خيرا}، ما الخير؟ المال، أم الصلاح، أم كل ذلك؟ قال: ما نراه إلا المال، كقوله: {كتب عليكم إذا حضر أحدكم الموت إن ترك خيرا} [البقرة: 180]، الخير: المال."}, "53261": {"num": 53261, "aya": 33, "qail": "عمرو بن دينار", "tabaqa": "تابعي", "bab": "", "text": "عن عمرو بن دينار -من طريق ابن جريج-: أحسبه كل ذلك: المال، والصلاح."}, "53269": {"num": 53269, "aya": 33, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {إن علمتم فيهم خيرا}، قال: إن علمت فيه خيرًا لنفسك، يُؤَدِّي إليك، ويصدقك ما حدثك، فكاتِبه."}, "53272": {"num": 53272, "aya": 33, "qail": "نافع", "tabaqa": "تابعي", "bab": "", "text": "عن نافع، قال: كان عبد الله بن عمر يكره أن يُكاتِب عبده إذا لم يكن له حرفة، ويقول: تطعمني مِن أوساخ الناس!."}, "53275": {"num": 53275, "aya": 33, "qail": "علي بن أبي طالب", "tabaqa": "صحابي", "bab": "", "text": "عن علي بن أبي طالب -من طريق عبد الله بن حبيب- عن النبي صلى الله عليه وسلم، في قوله: {وآتوهم من مال الله الذي آتاكم}، قال: «يترك للمكاتب الرُّبُع»."}, "53280": {"num": 53280, "aya": 33, "qail": "علي بن أبي طالب", "tabaqa": "صحابي", "bab": "", "text": "وعلي بن أبي طالب ="}, "53282": {"num": 53282, "aya": 33, "qail": "علي بن أبي طالب", "tabaqa": "صحابي", "bab": "", "text": "عن علي بن أبي طالب -من طريق أبي عبد الرحمن السلمي- في قوله: {وآتوهم من مال الله الذي آتاكم}، قال: يترك للمكاتب الربع."}, "53283": {"num": 53283, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- قال في قوله: {وآتوهم من مال الله}: أمر الله المؤمنين أن يُعينوا في الرقاب. ="}, "53284": {"num": 53284, "aya": 33, "qail": "علي بن أبي طالب", "tabaqa": "صحابي", "bab": "", "text": "وقال علي بن أبي طالب: أمر الله السيدَ أن يدع للمكاتب الربعَ مِن ثمنه، وهذا تعليمٌ من الله ليس بفريضة، ولكن فيه أجر."}, "53286": {"num": 53286, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {وآتوهم من مال الله الذي آتاكم}، يعني: ضعوا عنهم مِن مكاتبتهم."}, "53287": {"num": 53287, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس: يَحُطُّ عنه الثُّلُثَ."}, "53288": {"num": 53288, "aya": 33, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير، قال: كان ابنُ عمر إذا كان له مُكاتِب لم يضع عنه شيئًا مِن أول نجومه؛ مخافة أن يعجز فيرجع إليه صدقته، ولكنه إذا كان في آخر مكاتبته وضع عنه ما أحبَّ."}, "53289": {"num": 53289, "aya": 33, "qail": "نافع", "tabaqa": "تابعي", "bab": "", "text": "عن نافع، قال: كاتب عبد الله بن عمر غلامًا له يُقال له: شرفًا، على خمسة وثلاثين ألف درهم، فوضع مِن آخر كتابته خمسة آلاف. ولم يذكر نافع أنّه أعطاه شيئًا غير الذي وضع له."}, "53290": {"num": 53290, "aya": 33, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عمر -من طريق نافع-: أنّ مُكاتَبًا له جاءه، فقال: إنِّي قد عجزت. فقال له ابن عمر: لا تفعل؛ فإنِّي رادُّك في الرِّقِّ. فقال: إني قد عجزت. فردَّه في الرِّقِّ، ثم أعتقه بعد ذلك."}, "53293": {"num": 53293, "aya": 33, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم [النخعي]-من طريق مغيرة- في قوله: {وآتوهم من مال الله الذي آتاكم}، قال: أمر مولاه والناسَ جميعًا أن يعينوه."}, "53294": {"num": 53294, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- قال: يترك للمكاتب طائفة من كتابته."}, "53295": {"num": 53295, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- {وآتوهم من مال الله الذي آتاكم}، قال: آتِهِم مما في يديك."}, "53296": {"num": 53296, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق القاسم بن أبي بزة- ="}, "53297": {"num": 53297, "aya": 33, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "", "text": "وعطاء بن أبي رباح -من طريق حجاج بن أرطاة- في قوله: {وآتوهم من مال الله الذي آتاكم}، قال: يحط عنه الربع."}, "53298": {"num": 53298, "aya": 33, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق يونس- {وآتوهم من مال الله}، قال: حثَّ الناسَ عليه؛ مولًى، وغيره."}, "53299": {"num": 53299, "aya": 33, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري، في قوله: {وآتوهم من مال الله}: أي: سهمهم الذي جعله الله لهم مِن الصدقات المفروضات."}, "53301": {"num": 53301, "aya": 33, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "", "text": "عن عطاء [بن أبي رباح]-من طريق عبد الملك بن أبي سليمان- في قوله: {وآتوهم من مال الله الذي آتاكم}، قال: مِمّا أخرج اللهُ لك مِن مكاتبته."}, "53305": {"num": 53305, "aya": 33, "qail": "عطاء", "tabaqa": "تابعي", "bab": "", "text": "وعن عطاء، مثل ذلك."}, "53315": {"num": 53315, "aya": 33, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق أصبغ- في قول الله: {وآتوهم من مال الله الذي آتاكم}، قال: الفيء، والصدقات. وقرأ قول الله: {إنما الصدقات للفقراء والمساكين} حتى بلغ {وفي الرقاب}. فأمرهم الله أن يوفوهم منه، وليس ذلك مِن الكتابة. ="}, "53321": {"num": 53321, "aya": 33, "qail": "ابن عمر", "tabaqa": "صحابي", "bab": "من أحكام الآية", "text": "وابن عمر ="}, "53326": {"num": 53326, "aya": 33, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "من أحكام الآية", "text": "عن عبد الله بن عمر ="}, "53333": {"num": 53333, "aya": 33, "qail": "علي بن أبي طالب", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن علي بن أبي طالب، في قوله: {ولا تكرهوا فتياتكم على البغاء}، قال: كان أهل الجاهلية يبغين إماءَهم، فنُهوا عن ذلك في الإسلام."}, "53334": {"num": 53334, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- قال: كانوا في الجاهلية يُكرِهون إماءَهم على الزِّنا، يأخذون أجورهنَّ؛ فنزلت الآية."}, "53335": {"num": 53335, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة-: أنّ جارية لعبد الله بن أُبَيٍّ كانت تزني في الجاهلية، فولدت له [أولادًا] مِن الزِّنا، فلمّا حرم الله الزِّنا قال لها: ما لك لا تزنين؟ قالت: لا، واللهِ، لا أزني أبدًا. فضربها؛ فأنزل الله: {ولا تكرهوا فتياتكم على البغاء}."}, "53336": {"num": 53336, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر -من طريق منصور- قال: كانوا يأمرون ولائدهم أن يباغوا، فكُنَّ يفعلْنَ ذلك، ويُصِبْنَ، فيأتين بكسبهِنَّ. قال: وكان لعبد الله بن أُبَيٍّ جاريةٌ، فكانت تباغي، وكرِهت ذلك، وحلفت ألّا تفعله، فأكرهها؛ فأنزل الله الآية."}, "53337": {"num": 53337, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {ولا تكرهوا فتياتكم} قال: إمائكم {على البغاء} على الزنا. قال: عبد الله بن أُبَيِّ بن سلول أمر أمَةً له بالزنا، فجاءته ببُرْد، فأعطته، فقال: ارجعي فازني على آخر. فقالت: واللهِ، ما أنا براجعة، والله غفورٌ رحيمٌ للمُكرَهات على الزنا. ففي هذا أنزلت هذه الآية."}, "53349": {"num": 53349, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- {ولا تكرهوا فتياتكم على البغاء}، قال: لا تكرهوا إماءكم على الزِّنا."}, "53350": {"num": 53350, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {ولا تكرهوا فتياتكم} قال: إماءكم {على البغاء} على الزِّنا."}, "53358": {"num": 53358, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- قوله: {ولا تكرهوا فتياتكم على البغاء} إلى آخر الآية، قال: كانوا في الجاهلية يكرهون إماءَهم على الزِّنا، يأخذون أجورهنَّ، فقال الله: لا تُكْرِهُوهُنَّ على الزنا مِن أجل المنالة في الدنيا."}, "53359": {"num": 53359, "aya": 33, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء- {لتبتغوا عرض الحياة الدنيا}: يعني: كسبهن، وأولادهن مِن الزِّنا."}, "53366": {"num": 53366, "aya": 33, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير، قال: في قراءة ابن مسعود: (فَإنَّ اللَّهَ مِن بَعْدِ إكْراهِهِنَّ لَهُنَّ غَفُورٌ رَّحِيمٌ)."}, "53368": {"num": 53368, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي-: (ومَن يُكْرِهْهُنَّ فَإنَّ اللهَ مِن بَعْدِ إكْراهِهِنَّ غَفُورٌ رَّحِيمٌ لَهُنَّ)، يعني: إذا أكُرِهْنَ."}, "53369": {"num": 53369, "aya": 33, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق جعفر- أنّه كان يقرأ: (فَإنَّ اللهَ مِن بَعْدِ إكْراهِهِنَّ لَهُنَّ غَفُورٌ رَّحِيمٌ)."}, "53370": {"num": 53370, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- {ولا تكرهوا فتياتكم على البغاء}، قال: لا تُكْرِهوا إماءَكم على الزِّنا، فإن فعلتم فإنّ الله لهن غفور رحيم، وإثمهن على مَن يكرههن."}, "53371": {"num": 53371, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {ولا تكرهوا فتياتكم} قال: إماءَكم {على البغاء} على الزِّنا. قال: عبد الله بن أُبَيّ بن سلول أمر أمَةً له بالزِّنا، فجاءته ببُرْد، فأعطته، فقال: ارجعي، فازني على آخَر. فقالت: واللهِ، ما أنا براجعة، والله غفور رحيم للمكرَهات على الزنا. ففي هذا أنزلت هذه الآية."}, "53373": {"num": 53373, "aya": 33, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق عوف- في هذه الآية: {فإن الله من بعد إكراههن غفور رحيم}، قال: لَهُنَّ، واللهِ، لَهُنَّ، واللهِ."}, "53376": {"num": 53376, "aya": 33, "qail": "عطاء الخراساني", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن عطاء الخراساني -من طريق ابنه عثمان بن عطاء- يعني: قوله: {فإن الله من بعد إكراههن غفور رحيم}، وعد الله المكرَهات المغفرة إن تُبْنَ وأصلحْنَ."}, "53380": {"num": 53380, "aya": 33, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ومن يكرههن فإن الله من بعد إكراههن غفور رحيم}، قال: غفور رحيم لَهُنَّ حين أُكرهن وقُسِرْن على ذلك."}, "53402": {"num": 53402, "aya": 35, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "تفسير الآية مجموعة", "text": "عن أُبَيّ بن كعب -من طريق أبي العالية- {الله نور السموات والأرض مثل نوره} قال: هو المؤمن الذي جعل الإيمان والقرآن في صدره، فضَرَب الله مثلَه، فقال: {الله نور السموات والأرض} فبدأ بنور نفسه، ثم ذكر نور المؤمن، فقال: مثل نور مَن آمن به. فكان أُبَيّ بن كعب يقرؤها: (مَثَلُ نُورِ مَن آمَنَ بِهِ)؛ فهو المؤمن، جعل الإيمانَ والقرآنَ في صدره، {كمشكاة} قال: فصدر المؤمن المشكاة، {فيها مصباح} والمصباح النور، وهو القرآن والإيمان الذي جعل في صدره، {في زجاجة} والزجاجة قلبه، {كأنها كوكب دري} فقلبه مِمّا استنار فيه القرآنُ والإيمان كأنه كوكب دري، يقول: كوكب مُضِيء، «تُوقَدُ مِن شَجَرَةٍ مُبارَكَةٍ» والشجرة المباركة أصلُ المبارك؛ الإخلاص لله وحده، وعبادته لا شريك له، {زيتونة لا شرقية ولا غربية} قال: فمَثَلُه كمَثَلِ شجرةٍ التفَّ بها الشجر، فهي خضراء ناعمة لا تُصيبها الشمسُ على أيِّ حالة كانت، لا إذا طلعت، ولا إذا غربت، فكذلك هذا المؤمن قد أُجِير مِن أن يُضِلَّه شيء مِن الفتن، وقد ابتلي بها، فثبته الله فيها، فهو بين أربع خِلال: إن قال صَدَق، وإن حكم عدل، وإن أُعطِي شَكَر، وإن ابتُلِي صبر، فهو في سائر الناس كالرجل الحيِّ يمشي بين قبور الأموات، {نور على نور} فهو يتقلب في خمسة من النور: فكلامه نور، ومدخله نور، ومخرجه نور، ومصيره إلى نور يوم القيامة؛ إلى الجنة …."}, "53403": {"num": 53403, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية مجموعة", "text": "عن عبد الله بن عباس، في قوله: {نور السموات والأرض}: {مثل نوره} الذي أعطاه المؤمن {كمشكاة} مثل الكوَّة، {فيها مصباح المصباح في زجاجة الزجاجة كأنها كوكب دري يوقد من شجرة مباركة زيتونة لا شرقية ولا غربية} زيتونة في سفح جبَل لا تُصِيبها الشمسُ إذا طلعت، ولا إذا غربت، {يكاد زيتها يضيء ولو لم تمسسه نار نور على نور} فذلك مَثَل قلبِ المؤمن، نورٌ على نور."}, "53404": {"num": 53404, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية مجموعة", "text": "عن عبد الله بن عباس -من طريق علي- {الله نور السموات والأرض} قال: هادي أهل السموات والأرض، {مثل نوره} مثل هُداه في قلب المؤمن، {كمشكاة} يقول: موضع الفتيلة. يقول: كما يكاد الزيت الصافي يُضِيء قبل أن تمسه النار، فإذا مسته النار ازداد ضوءًا على ضوئه؛ كذلك يكون قلب المؤمن، يعمل بالهُدى قبل أن يأتيه العلم، فإذا جاءه العِلْم ازداد هدًى على هُدًى، ونورًا على نور."}, "53405": {"num": 53405, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية مجموعة", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- قال: إنّ اليهود قالوا لمحمد: كيف يخلص نور الله مِن دون السماء؟ فضرب الله مَثَل ذلك لنوره، فقال: {الله نور السموات والأرض مثل نوره كمشكاة} والمشكاة كوة البيت، {فيها مصباح} وهو السِّراج يكون في الزجاجة، وهو مَثَل ضربه الله لطاعته، فسمى طاعته: نورًا، ثم سمّاها أنواعًا شتّى، {لا شرقية ولا غربية} قال: هي وسط الشجرة، لا تنالها الشمسُ إذا طلعت، ولا إذا غربت، وذلك أجود الزيت، {يكاد زيتها يضيء} يقول: بغير نار، {نور على نور} يعني بذلك: إيمان العبد وعمله، {يهدي الله لنوره من يشاء} هو مَثَل المؤمن."}, "53406": {"num": 53406, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية مجموعة", "text": "عن عبد الله بن عباس، {الله نور السموات والأرض} قال: الله هادي أهل السموات والأرض، {مثل نوره} يا محمد، في قلبك، كمثل هذا المصباح في هذه المشكاة، فكما هذا المصباح في هذه المشكاة كذلك فؤادُك في قلبك، وشبَّه قلبَ رسول الله صلى الله عليه وسلم بالكوكب الدري الذي لا يخبو، {يوقد من شجرة مباركة زيتونة} تأخذ دينَك عن إبراهيم عليه السلام، وهي الزيتونة، {لاشرقية ولا غربية} ليس بنصرانيٍّ فيُصَلِّي نحو المشرق، ولا يهودي فيصلي نحو المغرب، {يكاد زيتها يضيء} فيقول: يكاد محمد ينطق بالحكمة قبل أن يُوحى إليه بالنور الذي جعل اللهُ في قلبه."}, "53408": {"num": 53408, "aya": 35, "qail": "شمر بن عطية", "tabaqa": "", "bab": "تفسير الآية مجموعة", "text": "عن شِمْر بن عطية، قال: جاء ابنُ عباس إلى كعب الأحبار، فقال: حدِّثني عن قول الله: {الله نور السموات والأرض مثل نوره}. قال: مثلُ نورِ محمد صلى الله عليه وسلم {كمشكاة} قال: المشكاة: الكوة، ضربها مثلًا لفمه، {فيها مصباح} والمصباح قلبه، {في زجاجة} والزجاجة صدره، {كأنها كوكب دري} شبَّه صدرَ محمد صلى الله عليه وسلم بالكوكب الدري، ثم رجع إلى المصباح؛ إلى قلبه، فقال: «تَوَقَّدَ مِن شَجَرَةٍ مُباركةٍ زَيْتُونَة»، {يكاد زيتها يضيء} قال: يكاد محمد صلى الله عليه وسلم يَبِينُ للناسِ -ولو لم يتكلم- أنّه نبيٌّ، كما يكاد ذلك الزيت أن يضيء {ولو لم تمسسه نار}."}, "53409": {"num": 53409, "aya": 35, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية مجموعة", "text": "عن الضحاك بن مُزاحِم -من طريق مقاتل- قال: شبّه عبد المطّلب بالمشكاة، وعبد الله بالزجاجة، والنبي صلى الله عليه وسلم بالمصباح، كان في صُلبهما، فورِث النبوّة مِن إبراهيم عليه السلام، {يوقد من شجرة مباركة زيتونة لا شرقية ولا غربية} بل هي مكيّة؛ لأنّ مكة وسط الدنيا."}, "53410": {"num": 53410, "aya": 35, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية مجموعة", "text": "قال الحسن البصري ="}, "53411": {"num": 53411, "aya": 35, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية مجموعة", "text": "وعبد الرحمن بن زيد بن أسلم: هذا مَثَلٌ للقرآن في قلب المؤمن، فكما أنّ هذا المصباح يُسْتضاء به، وهو كما هو لا ينقص، فكذلك القرآن يُهْتَدى به، ويُؤخَذ ويُعمَل به، فالمصباح هو القرآن، والزجاجة قلبُ المؤمن، والمشكاة لسانُه وفمه، والشجرة المباركة شجرة الوحي."}, "53415": {"num": 53415, "aya": 35, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "", "text": "عن أُبَيّ بن كعب -من طريق أبي العالية- في قول الله: {الله نور السموات والأرض}، قال: فبدأ بنور نفسِه فذكره، ثم ذكر نور المؤمن."}, "53416": {"num": 53416, "aya": 35, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "", "text": "قال أُبَيّ بن كعب ="}, "53418": {"num": 53418, "aya": 35, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "والحسن البصري: مُزَيِّن السموات والأرض؛ زَيَّن السماء بالشمس والقمر والنجوم، وزيَّن الأرض بالأنبياء والعلماء والمؤمنين."}, "53419": {"num": 53419, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس ="}, "53420": {"num": 53420, "aya": 35, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "ومجاهد بن جبر -من طريق ابن جُرَيج- قالا في قوله: {الله نور السموات والأرض}: يدبر الأمر فيهما؛ نجومهما، وشمسهما، وقمرهما."}, "53421": {"num": 53421, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- {الله نور السموات والأرض}، قال: هادي أهل السموات والأرض."}, "53423": {"num": 53423, "aya": 35, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "قال الضَّحّاك بن مُزاحِم ="}, "53428": {"num": 53428, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس، قال: كان رسول الله صلى الله عليه وسلم إذا تَهَجَّد في الليل يدعو: «اللهم، لك الحمد، أنت ربُّ السموات والأرض ومن فيهن، ولك الحمد، أنت نور السموات والأرض ومَن فيهن، ولك الحمد، أنت قيام السموات والأرض ومَن فيهن، أنت الحق، وقولك الحق، ووعدك حقٌّ، ولقاؤك حق، والجنة حق، والنار حق، والساعة حق، اللهم، لك أسلمتُ، وبك آمنتُ، وعليك توكلتُ، وإليك أنبتُ، وبك خاصمتُ، وإليك حاكمتُ، فاغفر لي ما قدمتُ وما أخرتُ، وما أسررت وما أعلنتُ، أنت إلهي، لا إله إلا أنت»."}, "53430": {"num": 53430, "aya": 35, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن سعيد بن جبير، قال: كان ابنُ عباس يقول: اللهم، إنِّي أسألك بنور وجهك الذي أشْرَقَتْ له السموات والأرض أن تجعلني في حِرْزِك، وحِفْظك، وجوارك، وتحت كنفك."}, "53433": {"num": 53433, "aya": 35, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن أُبَيّ بن كعب -من طريق أبي العالية- … أنه كان يقرؤها: (مَثَلُ المُؤْمِنِ)."}, "53434": {"num": 53434, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن عبد الله بن عباس -من طريق عطاء- {مثل نوره}، قال: هي خطأ مِن الكاتب، هو أعظم مِن أن يكون نوره مثل نور المشكاة. قال: (مَثَلُ نُورِ المُؤْمِنِ كَمِشْكاةٍ)."}, "53435": {"num": 53435, "aya": 35, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن أُبَيّ بن كعب -من طريق أبي العالية- {الله نور السموات والأرض مثل نوره}، قال: هو المؤمن الذي جعل الإيمان والقرآن في صدره، فضرب الله مثله، فقال: {الله نور السموات والأرض}. فبدأ بنور نفسه، ثم ذكر نور المؤمن، فقال: مثل نور مَن آمن به."}, "53436": {"num": 53436, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {الله نور السموات والأرض}، يقول: مثل نور مَن آمن بالله كمشكاة."}, "53437": {"num": 53437, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- {الله نور السموات والأرض} قال: هادي أهل السموات والأرض، {مثل نوره} مَثَل هُداه في قلب المؤمن."}, "53438": {"num": 53438, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- قال: … هو مَثَل ضربه الله لطاعته، فسمى طاعته: نورًا."}, "53439": {"num": 53439, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس: أراد بالنور: القرآن."}, "53440": {"num": 53440, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، {الله نور السموات والأرض} قال: الله هادي أهل السموات والأرض، {مثل نوره} يا محمد، في قلبك، كمثل هذا المصباح في هذه المشكاة، فكما هذا المصباح في هذه المشكاة كذلك فؤادك في قلبك، وشَبَّه قلبَ رسول الله صلى الله عليه وسلم بالكوكب الدري الذي لا يخبو."}, "53441": {"num": 53441, "aya": 35, "qail": "شمر بن عطية", "tabaqa": "", "bab": "تفسير الآية", "text": "عن شِمْر بن عطية، قال: جاء ابن عباس إلى كعب الأحبار، فقال: حدِّثني عن قول الله: {الله نور السموات والأرض مثل نوره}. قال: مَثل نورِ محمد صلى الله عليه وسلم."}, "53442": {"num": 53442, "aya": 35, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن سعيد بن جبير -من طريق جعفر بن أبي المغيرة- {مثل نوره}، قال: محمد صلى الله عليه وسلم."}, "53443": {"num": 53443, "aya": 35, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن سعيد بن جبير -من طريق عطاء بن السائب- {مثل نوره}، قال: مَثَل نور المؤمن."}, "53444": {"num": 53444, "aya": 35, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضَّحّاك بن مُزاحِم -من طريق ثابت- في قوله: {مثل نوره}، قال: نور المؤمن."}, "53445": {"num": 53445, "aya": 35, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضَّحّاك بن مُزاحِم -من طريق مقاتل- في قوله: {مثل نوره}، قال: هو محمد صلى الله عليه وسلم."}, "53447": {"num": 53447, "aya": 35, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق أبي رجاء- في قول الله: {مثل نوره}، قال: مَثَل هذا القرآن في القلب كمشكاة."}, "53452": {"num": 53452, "aya": 35, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {مثل نوره}: نور القرآن الذي أنزل على رسوله صلى الله عليه وسلم وعباده، هذا مثل القرآن، {كمشكاة فيها مصباح}."}, "53454": {"num": 53454, "aya": 35, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "", "text": "عن أُبَيّ بن كعب -من طريق أبي العالية- {كمشكاة}، قال: فصدر المؤمن المشكاة."}, "53455": {"num": 53455, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، {كمشكاة}، قال: ككَوة."}, "53456": {"num": 53456, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {الله نور السموات والأرض}، يقول: مثل نور مَن آمن بالله كمشكاة. قال: وهي القُتْرةُ. يعني: الكَوَّةَ."}, "53457": {"num": 53457, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، قال: المشكاة بلسان الحبشة: الكَوة."}, "53458": {"num": 53458, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- {كمشكاة}، يقول: موضع الفتيلة."}, "53459": {"num": 53459, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سليمان بن قَتَّة- قال: المشكاة: الرزونة في البيت. قال يحيى بن سلّام: وهي بالفارسية."}, "53463": {"num": 53463, "aya": 35, "qail": "شمر بن عطية", "tabaqa": "", "bab": "", "text": "عن شِمْر بن عطية، قال: جاء ابنُ عباس إلى كعب الأحبار، فقال: حدِّثني عن قول الله: {الله نور السموات والأرض مثل نوره}. قال: مَثَل نور محمد صلى الله عليه وسلم {كمشكاة}. قال: المشكاة: الكوة، ضربها مثلًا لفَمِه."}, "53465": {"num": 53465, "aya": 35, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير، {كمشكاة}، قال: الكوة التي ليست بنافِذة."}, "53466": {"num": 53466, "aya": 35, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مُزاحِم، مثله."}, "53467": {"num": 53467, "aya": 35, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- قال: المشكاة: الكوة، بلغة الحبشة."}, "53468": {"num": 53468, "aya": 35, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق داود بن أبي هند- قال: المشكاة: الحدائِد التي يُعَلَّق بها القنديل."}, "53469": {"num": 53469, "aya": 35, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {كمشكاة}، قال: الصُّفْر الذي في جوف القنديل."}, "53471": {"num": 53471, "aya": 35, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق أبي رجاء- {كمشكاة}، قال: ككَوَّة."}, "53476": {"num": 53476, "aya": 35, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الملك ابن جُرَيْج: {كمشكاة} كوة غير نافذة."}, "53477": {"num": 53477, "aya": 35, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "", "text": "عن أُبَيّ بن كعب -من طريق أبي العالية- {فيها مصباح}: والمصباح: النور، وهو القرآن والإيمان الذي جُعِل في صدره."}, "53478": {"num": 53478, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- قال: {فيها مصباح}، وهو السِّراج يكون في الزجاجة، وهو مَثَل ضربه الله لطاعته، فسمى طاعته: نورًا، ثم سمّاها أنواعًا شتى."}, "53481": {"num": 53481, "aya": 35, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق داود بن أبي هند- {فيها مصباح}، قال: السِّراج."}, "53487": {"num": 53487, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس ="}, "53488": {"num": 53488, "aya": 35, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "ومجاهد بن جبر -من طريق ابن جُرَيج- قالا: المصباح وما فيه مَثَل فؤاد المؤمن وجوفه؛ المصباح مثل الفؤاد، والكوة مثل الجوف."}, "53491": {"num": 53491, "aya": 35, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق داود بن أبي هند- {في زجاجة}، قال: القِنديل."}, "53497": {"num": 53497, "aya": 35, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن أُبَيّ بن كعب -من طريق أبي العالية- {كأنها كوكب دري}: فقلبه مما استنار فيه القرآن والإيمان كأنه كوكب دري، يقول: كوكب مضيء، «يُوقَدَ مِن شَجَرَةٍ مُباركةٍ» والشجرة المباركة أصله، المباركة: الإخلاص لله وحده، وعبادته لا شريك له."}, "53498": {"num": 53498, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، {تَوَقَّدُ من شجرة مباركة زيتونة}: تأخذ دينك عن إبراهيم عليه السلام، وهي الزيتونة."}, "53501": {"num": 53501, "aya": 35, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضحاك بن مُزاحِم -من طريق جُوَيبِر- {كأنها كوكب دري}، قال: يعني: الزهرة، ضرب الله مثل المؤمن مثل ذلك النور، يقول: قلبه نور، وجوفه نور، ويمشي في نور."}, "53502": {"num": 53502, "aya": 35, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق عمرو بن عبيد- {كأنها كوكب دري} قال: أخذها من الدُر، «تُوقَدَ مِن شَجَرَةٍ» يعني: الزجاجة التي توقد."}, "53510": {"num": 53510, "aya": 35, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "", "text": "عن أُبَيّ بن كعب -من طريق أبي العالية- {زيتونة لا شرقية ولا غربية}، قال: فمثله كمثل شجرة التَفَّ بها الشجر، فهي خضراء ناعمة لا تُصيبها الشمسُ على أيِّ حالة كانت، لا إذا طلعت، ولا إذا غربت، فكذلك هذا المؤمن قد أُجِير مِن أن يضله شيءٌ مِن الفتن، وقد ابتلي بها، فثبَّته الله فيها، فهو بين أربع خِلال: إن قال صدق، وإن حكم عدل، وإن أعطي شكر، وإن ابتلي صبر، فهو في سائر الناس كالرجل الحي يمشي بين قبور الأموات."}, "53511": {"num": 53511, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {لا شرقية ولا غربية}، قال: ليست شرقيةً ليس فيها غرب، ولا غربيةً ليس فيها شرق، ولكنها شرقية غربية."}, "53512": {"num": 53512, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {لا شرقية ولا غربية} / قال: شجرة بالصحراء لا يُظِلُّها كهفٌ ولا جبل، ولا يُواريها شيء، وهو أجود لزيتها."}, "53514": {"num": 53514, "aya": 35, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "وعن الضحاك بن مزاحم ="}, "53516": {"num": 53516, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس ="}, "53517": {"num": 53517, "aya": 35, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "ومجاهد بن جبر -من طريق ابن جريج- في قوله: {لا شرقية ولا غربية}، قالا: هي التي بشِقِّ الجبل، التي يصيبها شروقُ الشمس وغروبُها، إذا طلعت أصابتها، وإذا غربت أصابتها."}, "53518": {"num": 53518, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضحاك- «تُوقَدَ مِن شَجَرَةٍ مُباركةٍ» قال: رجل صالح، {لا شرقية ولا غربية} قال: لا يهودي ولا نصراني."}, "53519": {"num": 53519, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس: {يوقد من شجرة مباركة زيتونة} تأخذ دينك عن إبراهيم عليه السلام، وهي الزيتونة، {لاشرقية ولا غربية} ليس بنصراني فيصلي نحو المشرق، ولا يهودي فيصلي نحو المغرب."}, "53520": {"num": 53520, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- {لا شرقية ولا غربية}، قال: هي وسط الشجرة، لا تنالها الشمس إذا طلعت، ولا إذا غربت، وذلك أجود الزيت."}, "53521": {"num": 53521, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {شجرة مباركة زيتونة لا شرقية ولا غربية}: زيتونة في سَفْح جبل، لا تصيبها الشمس إذا طلعت، ولا إذا غربت."}, "53522": {"num": 53522, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق قابوس، عن أبيه- {لا شرقية ولا غربية}، قال: هي شجرة وسط الشجر، ليست من الشرق، ولا من الغرب."}, "53525": {"num": 53525, "aya": 35, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق أبي بِشْر- في قوله: {لا شرقية ولا غربية}، قال: هي في وسط الشجر؛ لا تصيبها الشمس في شرق ولا غرب، وهي من أجود الشجر."}, "53528": {"num": 53528, "aya": 35, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق داود بن أبي هند- {لا شرقية ولا غربية}، قال: في الشمس مِن حين تطلع إلى أن تغرب ليس لها ظِلٌّ، وذلك أضْوَأُ لزيتها، وأحسن له، وأنور له."}, "53529": {"num": 53529, "aya": 35, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق مقاتل- قال: {يوقد من شجرة مباركة زيتونة لا شرقية ولا غربية}، بل هي مكيّة؛ لأنّ مكة وسط الدنيا."}, "53531": {"num": 53531, "aya": 35, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق عوف- قال: لو كانت هذه الشجرةُ في الأرض لكانت شرقيةً أو غربية، ولكنه مَثَل ضربه الله لنوره."}, "53532": {"num": 53532, "aya": 35, "qail": "عطية العوفي", "tabaqa": "تابعي", "bab": "", "text": "عن عطية [العوفي]-من طريق ابن إدريس- {لا شرقية ولا غربية}، قال: هي في موضع مِن الشجر يُرى ظِلُّ ثمرها في ورقها، وهذه مِن الشجر لا تطلع عليها الشمس ولا تغرب."}, "53539": {"num": 53539, "aya": 35, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {زيتونة لا شرقية ولا غربية}، قال: متيامنة الشام لا شرقي ولا غربي."}, "53543": {"num": 53543, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- {يكاد زيتها يضيء}، يقول: بغير نار."}, "53544": {"num": 53544, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس: {يكاد زيتها يضيء}، فيقول: يكاد محمد ينطِق بالحكمة قبل أن يُوحى إليه بالنور الذي جعل الله في قلبه."}, "53545": {"num": 53545, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي-: مَثَل هُداه في قلب المؤمن كما يكاد الزيت الصافي يُضيء قبل أن تمسه النار، فإذا مَسَّته النارُ ازداد ضوءًا على ضوء، كذلك يكون قلب المؤمن يعمل بالهدى قبل أن يأتيه العلم، فإذا جاءه العلمُ ازداد هدًى على هدًى، ونورًا على نور، كما قال إبراهيم -صلوات الله عليه- قبل أن تجيئه المعرفة، {قال هذا ربي} [الأنعام: 76] حين رأى الكوكب من غير أن يخبره أحدٌ أن له رَبًّا، فلمّا أخبره اللهُ أنّه ربُّه ازداد هدًى على هدًى."}, "53547": {"num": 53547, "aya": 35, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق جعفر بن أبي المغيرة- {مثل نوره}، قال: محمد صلى الله عليه وسلم. {يكاد زيتها يضيء}، قال: يكاد مَن رأى [محمدًا]صلى الله عليه وسلم يعلم أنه رسول الله، وإن لم يتكلم."}, "53551": {"num": 53551, "aya": 35, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق أصبغ- قال: الضوء: إشراق الزيت."}, "53553": {"num": 53553, "aya": 35, "qail": "أبي بن كعب", "tabaqa": "صحابي", "bab": "", "text": "عن أبي بن كعب -من طريق أبي العالية- {نور على نور}: فهو يتقلب في خمسة من النور: فكلامه نور، ومدخله نور، ومخرجه نور، ومصيره إلى النور يوم القيامة؛ إلى الجنة."}, "53554": {"num": 53554, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي-: {نور على نور} يعني بذلك: إيمان العبد وعمله، {يهدي الله لنوره من يشاء} هو مَثَل المؤمن."}, "53555": {"num": 53555, "aya": 35, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس: {يهدي الله لنوره من يشاء} لدين الإسلام، وهو نور البصيرة."}, "53558": {"num": 53558, "aya": 35, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {نور على نور}، قال: النار على الزيت جوَّدتْه."}, "53577": {"num": 53577, "aya": 36, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {في بيوت أذن الله أن ترفع}، قال: في مساجد تُبْنى."}, "53578": {"num": 53578, "aya": 36, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- {في بيوت أذن الله أن ترفع}، قال: هي بيوت النبي صلى الله عليه وسلم."}, "53581": {"num": 53581, "aya": 36, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق مَعْمَر- في قوله: {في بيوت}: في المساجد."}, "53582": {"num": 53582, "aya": 36, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن [البصري]-من طريق سفيان بن الحسين-: هو بيت المقدس؛ لأنه يُسْرَج فيه كل ليلة عشرةُ آلاف قنديل."}, "53588": {"num": 53588, "aya": 36, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {أذن الله أن ترفع}، قال: تُبْنى."}, "53590": {"num": 53590, "aya": 36, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق مَعْمَر- في قوله: {أذن الله أن ترفع}، يقول: أن تُعَظَّم لذِكْرِه."}, "53614": {"num": 53614, "aya": 36, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق مَعْمَر- في قوله: {يسبح له فيها}: يُصلّى له فيها."}, "53625": {"num": 53625, "aya": 37, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة - في قوله: {رجال لا تلهيهم تجارة ولا بيع عن ذكر الله}، قال: أما -واللهِ- لقد كانوا تُجّارًا، فلم تكن تجارتُهم ولا بيعُهم يلهيهم عن ذكر الله."}, "53626": {"num": 53626, "aya": 37, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- في الآية، قال: ضرب الله هذا المثلَ -قوله: {مثل نوره كمشكاة} - لأولئك القوم الذين لا تلهيهم تجارة ولا بيع عن ذكر الله، وكانوا أتجر الناس وأبيعهم، ولكن لم تكن تلهيهم تجارتهم ولا بيعُهم عن ذكر الله."}, "53634": {"num": 53634, "aya": 37, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {رجال لا تلهيهم تجارة ولا بيع عن ذكر الله}، قال: كانوا رجالًا يبتغون مِن فضل الله؛ يشترون ويبيعون، فإذا سمعوا النداءَ بالصلاة ألقوا ما أيديهم، وقاموا إلى المسجد، فصلوا."}, "53635": {"num": 53635, "aya": 37, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- {رجال لا تلهيهم تجارة ولا بيع عن ذكر الله}، قال: عن شهود الصلاة المكتوبة."}, "53657": {"num": 53657, "aya": 37, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- قوله: {وأقيموا الصلاة وآتوا الزكاة} [البقرة: 43، 83، 110، النساء: 77، النور: 56، المزمل: 20]، {وكان يأمر أهله بالصلاة والزكاة} [مريم: 55]، وقوله: {وأوصاني بالصلاة والزكاة} [مريم: 31]، وقوله: {ولولا فضل الله عليكم ورحمته ما زكا منكم من أحد أبدا} [النور: 21]، وقوله: {وحنانا من لدنا وزكاة} [مريم: 13]، ونحو هذا في القرآن، قال: يعني بالزكاة: طاعة الله، والإخلاص."}, "53904": {"num": 53904, "aya": 58, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عمر -من طريق نافع- في قوله: {ليستأذنكم الذين ملكت أيمانكم}، قال: هو على الذكور دون الإناث."}, "53905": {"num": 53905, "aya": 58, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عمر، في قوله: {ثلاث عورات لكم ليس عليكم ولا عليهم جناح بعدهن طوافون عليكم}، قال: هو للإناث دون الذكور، أن يدخلوا بغير إذن."}, "53906": {"num": 53906, "aya": 58, "qail": "أبي عبد الرحمن السلمى", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن أبي عبد الرحمن السلمى -من طريق أبي حصين- في هذه الآية، قال: هي في النساء خاصة، الرجال يستأذنون على كلِّ حال بالليل والنهار."}, "53907": {"num": 53907, "aya": 58, "qail": "أبي عبد الرحمن السلمي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن أبي عبد الرحمن السلمي -من طريق أبي حصين- في قوله: {يا أيُّها الَّذِينَ آمَنُوا لِيَسْتَأْذِنْكُمُ الَّذِينَ مَلَكَتْ أيْمانُكُمْ}، قال: هي في الرجال والنساء؛ يستأذنون على كلِّ حال بالليل والنهار."}, "53968": {"num": 53968, "aya": 58, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عمر، قال: قال رسول الله صلى الله عليه وسلم: «لا تغلِبَنَّكم الأعرابُ على اسم صلاتكم العشاء، فإنّما هي في كتاب الله العشاء، وإنما يُعْتَم بِحِلاب الإبل»."}, "54066": {"num": 54066, "aya": 61, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق علي- قال: لَمّا نزلت: {يا أيها الذين آمنوا لا تأكلوا أموالكم بينكم بالباطل} [النساء: 29]؛ قال المسلمون: إنّ الله قد نهانا أن نأكل أموالنا بيننا بالباطل، والطعام هو أفضلُ الأموال؛ فلا يَحِلُّ لأحد مِنّا أن يأكل عندَ أحدٍ. فكَفَّ الناسُ عن ذلك؛ فأنزل الله: {ليس على الأعمى حرج} إلى قوله: {أو ما ملكتم مفاتحه}."}, "54067": {"num": 54067, "aya": 61, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس، قال: خرج الحارث غازِيًا مع رسول الله صلى الله عليه وسلم، وخلف على أهله خالد بن زيد، فتحرَّج أن يأكل مِن طعامه، وكان مجهودًا؛ فنزلت."}, "54071": {"num": 54071, "aya": 61, "qail": "مقسم بن بجرة", "tabaqa": "", "bab": "نزول الآية، وتفسيرها", "text": "عن مِقْسَم بن بُجْرَة -من طريق قيس بن مسلم- قال: كانوا يكرهون أن يأكلوا مع الأعمى والأعرج والمريض؛ لأنهم لا ينالون كما ينال الصحيح؛ فنزلت: {ليس على الأعمى حرج} الآية."}, "54072": {"num": 54072, "aya": 61, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- قال: كان الرجل يذهب بالأعمى أو الأعرج أو المريض إلى بيت أبيه، أو بيت أخيه، أو بيت أخته، أو بيت عمِّه، أو بيت عمَّته، أو بيت خاله، أو بيت خالته، فكان الزَّمْنى يتحرجون مِن ذلك، يقولون: إنّما [يذهبون] بنا إلى بيوت غيرهم. فنزلت هذه الآية رخصةً لهم."}, "54075": {"num": 54075, "aya": 61, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "قال الحسن البصري: نزلت هذه الآيةُ رخصةً لهؤلاء في التَّخَلُّف عن الجهاد. قال: تَمَّ الكلامُ عند قوله: {ولا على المريض حرج}."}, "54076": {"num": 54076, "aya": 61, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {ليس على الاعمى حرج ولا على الأعرج حرج ولا على المريض حرج}، قال: منعت البيوت زمانًا كان الرجل لا يُطعِم أحدًا، ولا يأكل في بيت غيره؛ تأثُّمًا مِن ذلك، فكان أول مَن رخص له في ذلك الأعمى، ثم رخص بعد ذلك للناس عامة. ="}, "54084": {"num": 54084, "aya": 61, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "نزول الآية، وتفسيرها", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج}، قال: هذا في الجهاد في سبيل الله."}, "54098": {"num": 54098, "aya": 61, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ولا على أنفسكم أن تأكلوا من بيوتكم} إلى قوله: {أو صديقكم}، قال: هذا شيء قد انقطع، إنما كان هذا في أوَّل، لم يكن لهم أبواب، وكانت الستور مُرخاة، فربما دخل الرجلُ البيتَ وليس فيه أحد، فربما وجد الطعام وهو جائع، فسوَّغه الله أن يأكله. قال: وقد ذهب ذلك اليومُ؛ البيوتُ اليومَ فيها أهلها، وإذا أخرجوا أغلقوها، فقد ذهب ذلك."}, "54100": {"num": 54100, "aya": 61, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {أو ما ملكتم مفاتحه}، قال: وهو الرجل يُوَكِّلَ الرجل بضَيْعته، فرخَّص الله له أن يأكل مِن ذلك الطعام والتمر، ويشرب اللبن."}, "54102": {"num": 54102, "aya": 61, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن مجاهد بن جبر -من طريق ابن جُرَيْج- قال: {أو ما ملكتم مفاتحه}، قال: خزائن لأنفسهم، ليست لغيرهم."}, "54105": {"num": 54105, "aya": 61, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "قال الحسن البصري: {أو ما ملكتم مفاتحه} خزانته مِمّا كنتم عليه أُمناء."}, "54106": {"num": 54106, "aya": 61, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- في قوله: {أو ما ملكتم مفاتحه}: مِمّا تختزن، يا ابن آدم."}, "54113": {"num": 54113, "aya": 61, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق عمرو- قال: يأكل الرجل مِن منزل صديقه حتى ينهاه، ثم قرأ: {أو صديقكم}."}, "54115": {"num": 54115, "aya": 61, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {أو صديقكم}، قال: إذا دخلت بيت صديقك مِن غير مؤامرته، ثم أكلت من طعامه بغير إذنه، لم يكن بذلك بأس."}, "54118": {"num": 54118, "aya": 61, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق علي- قال: كانوا يَأْنَفون ويَتَحَرَّجون أن يأكل الرجلُ الطعامَ وحده حتى يكون معه غيرُه؛ فرخص الله لهم، فقال: {ليس عليكم جناح أن تأكلوا جميعا أو أشتاتا}."}, "54119": {"num": 54119, "aya": 61, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق عطاء الخراساني- قوله: {أن تأكلوا جميعا أو أشتاتا}، قال: كان الغنيُّ يدخل على الفقير مِن ذَوي قرابته وصديقه، فيدعوه إلى طعامه ليأكل معه، فيقول: واللهِ، إنِّي لَأجنح أن آكل معك -والجُنْحُ: الحرج-؛ وأنا غنيٌّ وأنت فقير. فأُمِروا أن يأكلوا جميعًا أو أشتاتًا."}, "54121": {"num": 54121, "aya": 61, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق [علي بن أبي طلحة] الوالبي- ="}, "54127": {"num": 54127, "aya": 61, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: كان هذا الحيُّ مِن بني كنانة بن خزيمة، يرى أحدُهم أنّ عليه مخزاة أن يأكل وحده في الجاهلية، حتى إن كان الرجل يسوق الذود الحُفَّل وهو جائع حتى يجد مَن يُؤاكله ويُشاربه، وكان الرجل يتخذ الخيال إلى جنبه إذا لم يجد مَن يؤاكله ويشاربه؛ فأنزل الله: {ليس عليكم جناح أن تأكلوا جميعا أو أشتاتا}."}, "54131": {"num": 54131, "aya": 61, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الملك ابن جُرَيج -من طريق حجّاج- قال: كانت بنو كنانة يستحي الرجل منهم أن يأكل وحده، حتى نزلت هذه الآية."}, "54132": {"num": 54132, "aya": 61, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "نزول الآية، وتفسيرها", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ليس عليكم جناح أن تأكلوا جميعا أو أشتاتا}، قال: كان مِن العرب مَن لا يأكل أبدًا جميعًا، ومنهم مَن لا يأكل إلا جميعًا، فقال الله ذلك."}, "54133": {"num": 54133, "aya": 61, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {فاذا دخلتم بيوتا فسلموا على أنفسكم}، يقول: إذا دخلتم بيوتًا فسلِّموا على أهلها."}, "54134": {"num": 54134, "aya": 61, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عمرو بن دينار- في قوله: {فإذا دخلتم بيوتا فسلموا على أنفسكم}، قال: هو المسجد، إذا دخلته فقُل: السلام علينا، وعلى عباد الله الصالحين."}, "54135": {"num": 54135, "aya": 61, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: ما أخذتُ التَّشَهُّد إلا مِن كتاب الله، سمعت اللهَ يقول: {فاذا دخلتم بيوتا فسلموا على أنفسكم تحية من عند الله مباركة طيبة}، فالتشهد في الصلاة: التحيات المباركات الطيبات لله."}, "54136": {"num": 54136, "aya": 61, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس: إن لم يكن في البيت أحدٌ فليقل: السلام علينا، وعلى عباد الله الصالحين، السلام على أهل البيت، ورحمة الله."}, "54137": {"num": 54137, "aya": 61, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس: {مباركة طيبة} حسنة جميلة."}, "54138": {"num": 54138, "aya": 61, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {فاذا دخلتم بيوتا فسلموا على أنفسكم} يقول: إذا دخلتم بيوتًا فسلِّموا على أهلها {تحية من عند الله} وهو السلام؛ لأنّه اسم الله، وهو تحية أهل الجنة."}, "54140": {"num": 54140, "aya": 61, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن ابن جريج، قال: قلت لعطاء [بن أبي رباح]: إذا خرجتُ أواجبٌ السلامُ؟ هل أُسَلِّم عليهم؟ فإنما قال: {إذا دخلتم بيوتا فسلموا}. قال: ما أعلمه واجبًا، ولا آثر عن أحد وجوبه، ولكن أحب إلَيَّ، وما أدعه إلا ناسيًا. ="}, "54141": {"num": 54141, "aya": 61, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "قال ابن جريج: وقال عمرو بن دينار: لا. قال: قلت لعطاء لعطاء [بن أبي رباح]: فإن لم يكن في البيت أحد؟ قال: سلِّم، قل: السلام على النبي ورحمة الله وبركاته، السلام علينا وعلى عباد الله الصالحين، السلام على أهل البيت ورحمة الله. قلت له: قولك هذا إذا دخلت بيتًا ليس فيه أحد، عمَّن تأثره؟ قال: سمعته، ولم يؤثر لي عن أحد. ="}, "54144": {"num": 54144, "aya": 61, "qail": "جابر بن عبد الله", "tabaqa": "صحابي", "bab": "", "text": "عن جابر بن عبد الله -من طريق أبي الزبير- قال: إذا دخلتَ على أهلك فسلِّم عليهم {تحية من عند الله مباركة طيبة}، قال: ما رأيتُه إلا أوجبه."}, "54146": {"num": 54146, "aya": 61, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم [النخعي]-من طريق الأعمش- في قوله: {فإذا دخلتم بيوتا فسلموا على أنفسكم}، قال: إذا دخلتَ المسجدَ فقُل: السلام على رسول الله. وإذا دخلت بيتًا ليس فيه أحد فقُل: السلام علينا، وعلى عباد الله الصالحين. وإذا دخلت بيتك فقل: السلام عليكم."}, "54147": {"num": 54147, "aya": 61, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم [النخعي]-من طريق منصور- {فإذا دخلتم بيوتا فسلموا على أنفسكم}، قال: إذا دخلت بيتًا فيه يهود فقُل: السلام عليكم. وإن لم يكن فيه أحد فقُل: السلام علينا، وعلى عباد الله الصالحين."}, "54148": {"num": 54148, "aya": 61, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق عطاء- في قوله: {فسلموا على أنفسكم}، قال: بعضكم على بعض."}, "54149": {"num": 54149, "aya": 61, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق عبد الكريم أبي أُمَيَّة- قال: إذا دخلتَ بيتًا ليس فيه أحدٌ، فقُل: بسم الله، والحمد لله، السلام علينا، وعلى عباد الله الصالحين."}, "54150": {"num": 54150, "aya": 61, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ضِرار بن مُرَّة- في هذه الآية: {فاذا دخلتم بيوتًا فسلموا على أنفسكم}، قال: إذا دخلت بيتًا ليس فيه أحدٌ فقُل: السلام علينا، وعلى عباد الله الصالحين. وإذا دخلت المسجد فقُل: السلام على رسول الله. وإذا دخلت على أهلك فقُل: السلام عليكم."}, "54152": {"num": 54152, "aya": 61, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق معمر- في قوله: {فسلموا على أنفسكم}، قال: ليسلم بعضكم على بعض، كقوله: {ولا تقتلوا أنفسكم} [النساء: 29]."}, "54153": {"num": 54153, "aya": 61, "qail": "معمر", "tabaqa": "تابع التابعين", "bab": "", "text": "عن معمر ="}, "54158": {"num": 54158, "aya": 61, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "وقتادة بن دعامة -من طريق مَعْمَر- في قوله: {فسلموا على أنفسكم تحية من عند الله}، قالا: بيتك إذا دخلتَه فقُل: سلام عليكم."}, "54159": {"num": 54159, "aya": 61, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن ابن جُرَيْج -من طريق حجّاج- {فإذا دخلتم بيوتا فسلموا على أنفسكم}، قال: سلِّم على أهلك. ="}, "54160": {"num": 54160, "aya": 61, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "قال ابن جريج: وسُئِل عطاء بن أبي رباح: أحقٌّ على الرجل إذا دخل على أهله أن يُسَلِّم عليهم؟ قال: نعم. ="}, "54162": {"num": 54162, "aya": 61, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "قال ابن جريج: وأخبرني زياد، عن ابن طاووس أنّه كان يقول: إذا دخل أحدكم بيته فليسلم."}, "54163": {"num": 54163, "aya": 61, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- في قوله: {فإذا دخلتم بيوتا فسلموا على أنفسكم}، قال: إذا دخلت بيتك فسلِّم على أهلك، وإذا دخلت بيتًا لا أحد فيه فقُل: السلام علينا، وعلى عباد الله الصالحين. فإنه كان يؤمر بذلك، وحُدِّثْنا: أنّ الملائكة تَرُدُّ عليه."}, "54166": {"num": 54166, "aya": 61, "qail": "ماهان", "tabaqa": "", "bab": "", "text": "عن ماهان -من طريق أبي سنان- في قوله: {فإذا دخلتم بيوتا فسلموا على أنفسكم}، قال: يقول: السلام علينا مِن ربنا."}, "54169": {"num": 54169, "aya": 61, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق داود بن قيس- في قوله: {فسلموا على أنفسكم}، قال: إذا دخل المسلم على المسلم سلم عليه، مثل قوله: {ولا تقتلوا أنفسكم} [النساء: 29]، إنما هو: لا تقتل أخاك المسلم. وقوله: {ثم أنتم هؤلاء تقتلون أنفسكم} [البقرة: 85]، قال: يقتل بعضكم بعضًا، قريظة والنضير. وقوله: {جعل لكم من أنفسكم أزواجا} [الروم: 21]، كيف يكون زوجُ الإنسان مِن نفسه؟! إنما هي: جعل لكم أزواجًا من بني آدم، ولم يجعل من الإبل والبقر. وكل شيء في القرآن على هذا."}, "54178": {"num": 54178, "aya": 61, "qail": "جابر بن عبد الله", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن جابر بن عبد الله، قال: قال رسول الله صلى الله عليه وسلم: «إذا قام أحدُكم على حجرته ليدخل فليُسَمِّ الله، فإنه يرجع قرينه مِن الشيطان الذي معه ولا يدخل، وإذا دخلتم فسلِّموا؛ فإنه يخرج ساكنه منهم، وإذا وضع الطعام فسَمُّوا؛ فإنّكم تدحرون الخبيث إبليس عن أرزاقكم، ولا يَشْرَككم فيها، وإذا ارتحلتم دابة فسمُّوا الله حين تضعون أول حِلْس؛ فإنّ كلَّ دابة مقتعدة، وإنّكم إذا سميتم حططتموه عن ظهورها، وإن نسيتم ذلك شَرَككم في مراكبكم، ولا تُبَيِّتوا منديل الغَمَر معكم في البيت؛ فإنّه متن الشيطان ومضجعه، ولا تتركوا القُمامة ممسِيةً إذا جمعت في جانب الحجرة؛ فإنها مقعد الشيطان، ولا تسكنوا بيوتًا غير مغلقة، ولا تفترشوا الولايا التي تفضي إلى ظهور الدواب، ولا تبيتوا على سطح ليس بمحجور، وإذا سمعتم نباح الكلاب أو نهيق الحمار فاستعيذوا بالله من الشيطان؛ فإنهما لا يريان الشيطان إلا نبح الكلب ونهق الحمار»."}, "54185": {"num": 54185, "aya": 61, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن مجاهد بن جبر -من طريق عبد الكريم الجزري- قال: إذا دخلتَ بيتك وليس فيه أحد، أو بيت غيرك؛ فقل: بسم الله، والحمد لله، السلام علينا مِن ربنا، السلام علينا وعلى عباد الله الصالحين."}, "54186": {"num": 54186, "aya": 61, "qail": "أبي مالك غزوان الغفاري", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن أبي مالك غَزْوان الغِفاري -من طريق حصين- قال: إذا دخلتَ بيتًا فيه ناسٌ مِن المسلمين فسلِّم عليهم. وإن لم يكن فيه أحد، أو كان فيه ناس من المشركين؛ فقل: السلام علينا، وعلى عباد الله الصالحين."}, "54231": {"num": 54231, "aya": 63, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق الضحاك- في قوله: {لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضا}، قال: كانوا يقولون: يا محمد، يا أبا القاسم. فنهاهم الله عن ذلك إعظامًا لنبيه صلى الله عليه وسلم، فقالوا: يا نبي الله، يا رسول الله."}, "54232": {"num": 54232, "aya": 63, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس، في قوله: {لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضا}: يعني: كدعاء أحدكم اذا دعا أخاه باسمه، ولكن وقِّروه وعَظِّموه، وقولوا له: يا رسول الله، ويا نبيَّ الله."}, "54233": {"num": 54233, "aya": 63, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق ابن جُرَيْج- في قوله: {لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضا}: يريد: ولا تصيحوا به مِن بعيد: يا أبا القاسم. ولكن كما قال الله في الحجرات [3]: {إن الذين يغضون أصواتهم عند رسول الله}."}, "54234": {"num": 54234, "aya": 63, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق العوفي- في قوله: {لا تجعلوا دعاء الرسول بينكم} الآية، يقول: دعوة الرسول عليكم موجبة؛ فاحذَروها."}, "54239": {"num": 54239, "aya": 63, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في الآية، قال: أمرهم اللهُ أن يدعوه: يا رسول الله. في لين وتواضع، ولا يقولوا: يا محمد. في تَجَهُّم."}, "54244": {"num": 54244, "aya": 63, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- في الآية، قال: أمر الله أن يُهاب نبيُّه، وأن يُبَجَّل، وأن يُعَظَّم، وأن يُفَخَّم، ويُشرَّف."}, "54251": {"num": 54251, "aya": 63, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "قال عبد الله بن عباس: {لواذا}، أي: يلوذ بعضهم ببعض، وذلك أنّ المنافقين كان يثقل عليهم المقام في المسجد يوم الجمعة واستماع خطبة النبي صلى الله عليه وسلم، فكانوا يلوذون ببعض أصحابه، فيخرجون من المسجد في استتار."}, "54252": {"num": 54252, "aya": 63, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق حجاج، عن ابن جريج- في قوله: {لواذا}، قال: خِلافًا."}, "54256": {"num": 54256, "aya": 63, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- {قد يعلم الله الذين يتسللون منكم لواذا}، قال: يتسللون عن نبي الله، وعن كتابه، وعن ذِكْرِه."}, "54267": {"num": 54267, "aya": 63, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {فليحذر الذين يخالفون عن أمره أن تصيبهم فتنة}، قال: أي: قَتْل."}, "54268": {"num": 54268, "aya": 63, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، في قوله: {فليحذر الذين يخالفون عن أمره أن تصيبهم فتنة}، قال: بلاء في الدنيا."}, "54283": {"num": 54283, "aya": 63, "qail": "مجاهد", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن مجاهد، قال: أشدُّ حديثٍ سمعناه عن النبي صلى الله عليه وسلم قولُه في سعد بن معاذ في أمر القبر، ولَمّا كانت غزوة تبوك قال: «لا يخرج معنا إلا رجل مُقْوٍ». فخرج رجل على بَكر له صعب، فصرعه، فمات، فقال الناس: الشهيد، الشهيد. فأمر النبيُّ صلى الله عليه وسلم بلالًا أن يُنادي في الناس: «لا يدخل الجنةَ إلا نفسٌ مؤمنة، ولا يدخل الجنةَ عاصٍ»."}, "52251": {"num": 52251, "aya": 2, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "تفسير الآية، وأحكامها", "text": "عن سعيد بن جبير -من طريق عطاء- في قول الله: {الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة}: يعني: إذا كانا بِكْرَين لم يُحْصَنا يجلدهما الحُكّام إذا رُفِع إليهم، وشهد أربعة من المسلمين أحرارٌ عدول."}, "52269": {"num": 52269, "aya": 2, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء بن دينار- في قول الله: {ولا تأخذكم بهما}: يعني: في ضربهما {رأفة في دين الله} يعني: في حُكْم الله الذي حكم على الزاني."}, "52270": {"num": 52270, "aya": 2, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق داود- قال: الجلد."}, "52271": {"num": 52271, "aya": 2, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي: {لا تأخذكم بهما رأفة} فتُعَطِّلوا الحدود، ولا تقيموها."}, "52272": {"num": 52272, "aya": 2, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم [النخعي]، {ولا تأخذكم بهما رأفة}، قال: شدة الجلد في الزِّنا، ويُعْطى كلُّ عضوٍ منه حقُّه."}, "52275": {"num": 52275, "aya": 2, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {ولا تأخذكم بهما رأفة}، قال: في إقامة الحد."}, "52276": {"num": 52276, "aya": 2, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "", "text": "عن عامر الشعبي- {ولا تأخذكم بهما رأفة}، قال: شِدَّة الجلد في الزِّنا، ويُعْطى كلُّ عضوٍ منه حقُّه."}, "52277": {"num": 52277, "aya": 2, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "", "text": "عن عامر الشعبي -من طريق عطاء بن السائب- قوله: {ولا تأخذكم بهما رأفة}، قال: رحمة في شدة الجِلْد."}, "52278": {"num": 52278, "aya": 2, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "", "text": "قال عامر الشعبي ="}, "52283": {"num": 52283, "aya": 2, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "", "text": "عن عطاء [بن أبي رباح]-من طريق حجّاج، وابن جُرَيج- {ولا تأخذكم بهما رأفة في دين الله}، قال: في الحَدِّ، أن يُقام عليهم ولا يُعَطَّل، أما إنّه ليس بشِدَّة الجلد."}, "52284": {"num": 52284, "aya": 2, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {ولا تأخذكم بهما رأفة}، قال: رحْمةٌ."}, "52285": {"num": 52285, "aya": 2, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد-: الجلد في الزنا: المَتْحُ الشديد. ويقول: {ولا تأخذكم بهما رأفة في دين الله}، أي: الجلد الشديد."}, "52286": {"num": 52286, "aya": 2, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة -من طريق مَعْمَر-: يُخَفَّف في الشراب والفِرْية، ويجتهد في الزِّنا."}, "52293": {"num": 52293, "aya": 2, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الملك ابن جُرَيج-من طريق حجاج- {ولا تأخذكم بهما رأفة في دين الله}، قال: لا تُضَيِّعوا حدودَ الله."}, "52294": {"num": 52294, "aya": 2, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ولا تأخذكم بهما رأفة}: فتدعوهما من حدود الله التي أمر بها، وافترضها عليهما."}, "52298": {"num": 52298, "aya": 2, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء-: قوله: {إن كنتم} يعني: الحكام، {تؤمنون} يعني: تصدقون بالله يعني: بتوحيد الله، {واليوم الآخر} يعني: وتُصَدِّقون بالبعث الذي فيه جزاء الأعمال؛ فأقيموا الحدود."}, "52301": {"num": 52301, "aya": 2, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء- قوله: {وليشهد} يعني: وليحضر، {عذابهما} يعني: حدَّهما."}, "52303": {"num": 52303, "aya": 2, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في الآية، قال: أمر اللهُ أن يشهد عذابَهما طائفةٌ مِن المؤمنين؛ ليكون ذلك عبرةً وموعظةً ونكالًا بهم."}, "52309": {"num": 52309, "aya": 2, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء بن دينار-: {وليشهد عذابهما طائفة} يعني: رجلين فصاعدًا، {من المؤمنين} يعني: المُصَدِّقين."}, "52310": {"num": 52310, "aya": 2, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم [النخعي] ="}, "52312": {"num": 52312, "aya": 2, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق أبي بشر- قال: الطائفة: الرجل الواحد إلى الألف. قال: {وإن طائفتان من المؤمنين اقتتلوا} [الحجرات: 9] إنما كانا رجلين."}, "52316": {"num": 52316, "aya": 2, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "", "text": "عن عطاء [بن أبي رباح]-من طريق ابن أبي نجيح- في قوله: {وليشهد عذابهما طائفة من المؤمنين}، قال: أقلُّه رجلان."}, "52317": {"num": 52317, "aya": 2, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "", "text": "عن عطاء [بن أبي رباح]-من طريق إبراهيم الصائغ- {وليشهد عذابهما طائفة من المؤمنين}، قلتُ: يكفيه أن يكون معه رجل أو رجلان من أهل بيته؟ قال: نعم."}, "52318": {"num": 52318, "aya": 2, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- في قوله: {وليشهد عذابهما طائفة من المؤمنين}، قال: نَفَرٌ مِن المسلمين."}, "52319": {"num": 52319, "aya": 2, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة: ثلاثة فصاعدًا."}, "52326": {"num": 52326, "aya": 2, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في الآية، قال: الطائفة التي يجب بها الحدُّ أربعةٌ."}, "52329": {"num": 52329, "aya": 3, "qail": "عمرو بن شعيب", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن عمرو بن شعيب، عن أبيه، عن جده، قال: كان رجل -يُقال له: مَرْثَد- يحمل الأسارى مِن مكة حتى يأتي بهم المدينة، وكانت امرأة بَغِيٌّ بمكة يُقال لها: عَناق، وكانت صديقةً له، وأنّه وعد رجلًا مِن أسارى مكة يحمله، قال: فجئتُ حتى انتهيتُ إلى ظِلِّ حائط مِن حوائط مكة في ليلة مُقْمِرة، فجاءت عَناق، فأبصرت سواد ظِلٍّ تحت الحائط، فلمّا انتهت إلَيَّ عرفتني، فقالت: مرثد؟! فقلتُ: مرثد. فقالت: مرحبًا وأهلًا، هلُمَّ فبِتْ عندنا الليلة. قلت: يا عناقُ، حَرَّم الله الزِّنا. قالت: يا أهل الخيام، هذا الرجل يحمل أسراكم. قال: فتبعني ثمانية، وسلكت الخَندَمَةَ، فانتهيتُ إلى غارٍ أو كهف، فدخلتُ، فجاءوا حتى قاموا على رأسي، فبالوا، وظلَّ بولُهم على رأسي، وأعماهم الله عَنِّي، ثم رجعوا، ورجعتُ إلى صاحبي، فحملته، حتى قدمت المدينة، فأتيت رسول الله صلى الله عليه وسلم فقلت: يا رسول الله، أنكِح عَناقًا؟ فأمسك فلم يَرُدَّ عَلَيَّ شيئًا حتى نزلت: {الزاني لا ينكح إلا زانية أو مشركة} الآية. فقال رسول الله صلى الله عليه وسلم: «يا مَرْثَدُ، الزاني لا ينكح إلا زانية أو مشركة، والزانية لا ينكحها إلا زانٍ أو مشرك، وحُرِّم ذلك على المؤمنين؛ فلا تنكحها»."}, "52331": {"num": 52331, "aya": 3, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق عطية العوفي-: أنّها نزلت في بغايا مُعْلِناتٍ كُنَّ في الجاهلية، وكُنَّ زَوانيَ مشركات، فحرم الله نكاحهن على المؤمنين."}, "52332": {"num": 52332, "aya": 3, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن عطاء بن أبي رباح، قال: كانت بغايا في الجاهلية؛ بغايا آل فلان، وبغايا آل فلان، فقال الله: {الزاني لا ينكح إلا زانية أو مشركة والزانية لا ينكحها إلا زان أو مشرك}، فأحكم اللهُ ذلك مِن أمر الجاهلية بالإسلام. قيل له: أعنِ ابن عباس؟ قال: نعم."}, "52333": {"num": 52333, "aya": 3, "qail": "عبد الله بن عمرو", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عمرو -من طريق القاسم بن محمد- قال: كانت امرأةٌ يُقال لها: أم مهزول، وكانت تُسافِح الرجل، وتَشْرِطُ أن تُنفِق عليه، فأراد رجلٌ مِن أصحاب النبي صلى الله عليه وسلم أن يتزوجها؛ فأنزل الله: {الزانية لا ينكحها إلا زان أو مشرك}."}, "52334": {"num": 52334, "aya": 3, "qail": "سعيد بن المسيب", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن سعيد بن المسيب -من طريق قتادة- في هذه الآية: {والزانية لا ينكحها إلا زان أو مشرك}، قال: نزلت في نساء مَواردَ كنَّ بالمدينة."}, "52335": {"num": 52335, "aya": 3, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن سعيد بن جبير -من طريق سفيان الثوري- قال: كُنَّ نساء بغايا في الجاهلية، كان الرجل ينكح المرأة في الإسلام، فيُصِيب منها، فحُرِّمَ ذلك في الإسلام؛ فأنزل الله: {الزانية لا ينكحها إلا زان}."}, "52338": {"num": 52338, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر -من طريق عبد الملك، عمَّن أخبره- في قوله: {الزاني لا ينكح إلا زانية أو مشركة}، قال: كُنَّ نساء في الجاهلية بَغِيّات، فكانت منهنَّ امرأة جميلة تدعى: أم مهزول، فكان الرجل مِن فقراء المسلمين يتزوج إحداهن لتنفق عليه مِن كسبها، فنهى الله أن يتزوجهن أحدٌ مِن المسلمين."}, "52339": {"num": 52339, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر، قال: لَمّا حَرَّم الله الزِّنا، فكان زواني عندهن جمال، فقال الناس حين حُرِّم الزنا: لَنَنطَلقن فلنتزوجهن. فأنزل الله في ذلك: {الزاني لا ينكح إلا زانية} الآية."}, "52340": {"num": 52340, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر، قال: كان في بدء الإسلام قومٌ يزنون، قالوا: أفلا نتزوج النساءَ التي كُنّا نفجر بِهِنَّ؟ فأنزل الله: {الزاني لا ينكح إلا زانية} الآية."}, "52341": {"num": 52341, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر -من طريق ابن جريج- في قوله: {الزاني لا ينكح إلا زانية أو مشركة والزانية لا ينكحها إلا زان أو مشرك وحرم ذلك على المؤمنين}، قال: كُنَّ بغايا في الجاهلية معلومات معروفات، لَهُنَّ رايات يُعْرَفْن بها، فلما جاء الإسلام، وأرادوا أن يُزَوِّجُوهن، فنهوا عن ذلك، وأراد مرثد بن أبي مرثد أن يتزوج منهن واحدةً."}, "52342": {"num": 52342, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر -من طريق ورْقاء، عن ابن أبي نجيح- في قوله: {الزاني لا ينكح إلا زانية أو مشركة}، قال: رجال كانوا يريدون الزِّنا بنساءٍ زواني بغايا متعالمات، كُنَّ كذلك في الجاهلية. قيل لهم: هذا حرام. فأرادوا نكاحهن، فحرَّم اللهُ عليهم نكاحهنَّ."}, "52343": {"num": 52343, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر -من طريق مَعْمَر، عن ابن أبي نجيح-: كان في الجاهلية بغايا، معلومٌ ذلك مِنهُنَّ، فأراد ناسٌ مِن المسلمين نكاحهن؛ فأنزل الله: {الزاني لا ينكح إلا زانية أو مشركة والزانية لا ينكحها إلا زان أو مشرك} الآية."}, "52346": {"num": 52346, "aya": 3, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن عامر الشعبي -من طريق إسماعيل- في قوله: {الزاني لا ينكح إلا زانية أو مشركة والزانية لا ينكحها إلا زان أو مشرك}، قال: كُنَّ نساء يُكرين أنفسهنَّ في الجاهلية."}, "52351": {"num": 52351, "aya": 3, "qail": "عبد الله بن عمرو", "tabaqa": "صحابي", "bab": "تفسير الآية، وأحكامها", "text": "عن عبد الله بن عمرو -من طريق القاسم بن محمد- في قوله: {الزاني لا ينكح إلا زانية أو مشركة}، قال: كُنَّ نساء معلومات، فكان الرجل مِن فقراء المسلمين يتزوج المرأة منهن لتنفق عليه، فنهاهم الله عن ذلك."}, "52352": {"num": 52352, "aya": 3, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية، وأحكامها", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {الزاني لا ينكح إلا زانية}، قال: ليس هذا بالنكاح، ولكن الجماع، لا يزني بها حين يزني إلا زانٍ أو مُشرك، {وحرم ذلك على المؤمنين} يعني: الزِّنا."}, "52354": {"num": 52354, "aya": 3, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية، وأحكامها", "text": "عن عبد الله بن عباس -من طريق إسحاق بن عبد الله بن الحارث- {الزاني لا ينكح إلا زانية أو مشركة}، قال: الزاني لا يزني إلا بزانية أو مشركة، ولكن الله كنّى."}, "52355": {"num": 52355, "aya": 3, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية، وأحكامها", "text": "عن عبد الله بن عباس -من طريق سعيد- {وحرم ذلك على المؤمنين}، قال: حرَّم اللهُ الزِّنا على المؤمنين."}, "52356": {"num": 52356, "aya": 3, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية، وأحكامها", "text": "عن عبد الله بن عباس -من طريق علي- في هذه الآية، قال: الزاني مِن أهل القبلة لا يزني إلا بزانية مثلِه من أهل القبلة، أو مشركة مِن غير أهل القبلة، والزانية مِن أهل القبلة لا تزني إلا بزانٍ مثلها مِن أهل القبلة، أو مشرك مِن غير أهل القبلة، وحُرِّم الزنا على المؤمنين."}, "52357": {"num": 52357, "aya": 3, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "تفسير الآية، وأحكامها", "text": "عن عطاء [بن أبي رباح]-من طريق ابن جريج- قوله: {والزانية لا ينكحها إلا زان أو مشرك}، قال: أو مشرك لهن. ="}, "52359": {"num": 52359, "aya": 3, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "تفسير الآية، وأحكامها", "text": "قال سعيد بن جبير ="}, "52360": {"num": 52360, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية، وأحكامها", "text": "ومجاهد بن جبر -من طريق معمر- {الزاني لا ينكح إلا زانية أو مشركة}، قالا: هو الوَطْء."}, "52362": {"num": 52362, "aya": 3, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "تفسير الآية، وأحكامها", "text": "عن سعيد بن جبير -من طريق يعلى بن مسلم- {الزاني لا ينكح إلا زانية أو مشركة}، قال: لا يزني حين يزني إلا بزانية مثله، أو مشركة."}, "52366": {"num": 52366, "aya": 3, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية، وأحكامها", "text": "عن مجاهد بن جبر -من طريق سلمة- قال: {الزاني لا ينكح إلا زانية أو مشركة}، قال: هُنَّ نساء معلومات يدعون: القبلقيات."}, "52376": {"num": 52376, "aya": 3, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية، وأحكامها", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قول الله: {الزاني لا ينكح الا زانية أو مشركة}، قال: هؤلاء بغايا كُنَّ في الجاهلية، والنكاح في كتاب الله: الإصابة، لا يصيبها إلا زانٍ أو مشرك لا يُحَرِّم الزنا، ولا يصيب هو إلا مثلَها."}, "52379": {"num": 52379, "aya": 3, "qail": "يحيى بن سلام", "tabaqa": "من بعدهم", "bab": "تفسير الآية، وأحكامها", "text": "قال يحيى بن سلّام: قوله: {الزاني لا ينكح إلا زانية أو مشركة والزانية لا ينكحها إلا زان أو مشرك وحرم ذلك على المؤمنين}، وذلك أنّ النبيَّ قدم المدينة وبها نساءٌ مِن نساء أهل الكتاب، وإماء مشركات من إماء مشركي العرب، مجاهرات بالزِّنا، لهن رايات مثل رايات البياطرة. قال بعضهم: لا يحل مِن نساء أهل الكتاب إلا العفائف الحرائر، ولا نساء المشركين مِن غير أهل الكتاب، وإماء المشركين حرام على المؤمنين. وقال بعضهم في قوله: {الزاني لا ينكح إلا زانية أو مشركة}: يعني: مَن كان يزني بتلك المؤاجرات مِن نساء أهل الكتاب ومِن إماء المشركين، وإن كانت حرة من المشركات، لا ينكحها إلا زانٍ مِن أهل الكتاب أو مشرك من مشركي العرب. قال: {وحرم ذلك على المؤمنين} تزويجهن. ثم حرَّم نساء المشركات من غير أهل الكتاب؛ زَوانِيَ كُنَّ أو عفائف، فقال: {ولا تنكحوا المشركات حتى يؤمن} [البقرة: 221]، {ولا تنكحوا المشركين حتى يؤمنوا} [البقرة: 221]، قال: ولا بأس بتزويج الحُرَّة التي قد زَنَت، وإن أُقِيم عليها الحدُّ."}, "52380": {"num": 52380, "aya": 3, "qail": "سعيد بن المسيب", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "عن سعيد بن المسيب -من طريق يحيى بن سعيد- في هذه الآية: {الزاني لا ينكح إلا زانية}، قال: يرون أنّ هذه الآية التي بعدها نسختها: {وأنكحوا الأيامى منكم} [النور: 32]. فهُنَّ مِن أيامى المسلمين."}, "52381": {"num": 52381, "aya": 3, "qail": "يحيى بن سلام", "tabaqa": "من بعدهم", "bab": "النسخ في الآية", "text": "قال يحيى بن سلّام: وبعضهم يقول: نزلت في كل زانية ثُمَّ نسِخَت، فيما حدثني نصر بن طريف وأبو أمية، عن يحيى بن سعيد، عن سعيد بن المسيب، قال: نسختها: {وأنكحوا الأيامى منكم} [النور: 32]. وحدثني ابن أبي ذئب، عن شعبة مولى ابن عباس، عن ابن عباس أنّ رجلًا أتاه، فقال: إنِّي أصبتُ مِن امرأةٍ ما حَرَّم اللهُ، فأذهب اللهُ ذلك، ورزقني توبةً، فأردت أن أتزوجها، وإنهم يقولون: {الزاني لا ينكح إلا زانية أو مشركة}. فقال: كُنَّ بغايا لهن رايات مثل رايات البياطرة، فيدخل عليهن الناس. اذهب فتزوَّجها، فما كان مِن إثم فهو عَلَيَّ. وحدثني همام، عن قتادة: أنّ أُبي بن كعب ورجلًا من أصحاب النبي صلى الله عليه وسلم -لم يروا بأسًا إذا زنى الرجلُ بالمرأة أن يتزوجها، وقالوا: الشرك أعظم من ذلك. قال يحيى: يعنون: أنها قد تكون مشركة ثم تُسْلِم، فهو أعظم مِن الزنا."}, "52414": {"num": 52414, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، {والذين يرمون المحصنات ثم لم يأتوا بأربعة شهداء} الآية: ثم استثنى، فقال: {إلا الذين تابوا من بعد ذلك واصلحوا}، فتاب الله عليهم مِن الفسوق، وأما الشهادة فلا تجوز."}, "52415": {"num": 52415, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، {والذين يرمون المحصنات} إلى قوله: {رحيم}: فأنزل الله الجلدَ والتوبة، فالتوبة تُقبَل، والشهادة تُرَدُّ."}, "52416": {"num": 52416, "aya": 5, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {ولا تقبلوا لهم شهادة أبدًا}، ثم قال: {إلا الذين تابوا}، قال: فمَن تاب وأصلح فشهادته في كتاب الله تقبل."}, "52417": {"num": 52417, "aya": 5, "qail": "سعيد بن المسيب", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن سعيد بن المسيب، قال: {إلا الذين تابوا}، توبتُهم إكذابُهم أنفسَهم."}, "52419": {"num": 52419, "aya": 5, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إبراهيم النخعي -من طريق حماد- في قول الله تعالى: {إلا الذين تابوا من بعد ذلك وأصلحوا}، قال: يرفع الله عنه اسمَ الفسق، فأمّا الشهادة فلا تجوز أبدًا."}, "52420": {"num": 52420, "aya": 5, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضَّحّاك بن مُزاحِم -من طريق عبيد- يقول في قوله: {ولا تقبلوا لهم شهادة أبدا وأولئك هم الفاسقون إلا الذين تابوا} الآية، قال: مَن اعترفَ وأقَرَّ على نفسه علانيةً أنّه قال البُهتان، وتاب إلى الله توبة نصوحًا -والنصوح: ألّا يعودَ، وإقراره واعترافه عند الحد حين يؤخذ بالجلد-؛ فقد تاب، والله غفور رحيم."}, "52421": {"num": 52421, "aya": 5, "qail": "قتادة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة، في قوله: {ولا تقبلوا لهم شهادة أبدا}، قال: كان الحسن [البصري] يقول: لا تُقبَل شهادة القاذف أبدًا، توبتُه فيما بينه وبين الله."}, "52423": {"num": 52423, "aya": 5, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {ولا تقبلوا لهم شهادة أبدًا وأولئك هم الفاسقون}: ثم عاد الله بعد ذلك بعائدته ورحمته، فقال: {إلا الذين تابوا من بعد ذلك وأصلحوا فان الله غفور رحيم}."}, "52428": {"num": 52428, "aya": 5, "qail": "سعيد بن المسيب", "tabaqa": "تابعي", "bab": "أحكام الآية", "text": "عن سعيد بن المسيب، قال: شهدتُ عمر بن الخطاب حين جلد قذَفَة المغيرة بن شعبة، منهم أبو بكرة، وماتع، وشبل، ثم دعا أبا بكرة، فقال: إن تُكَذِّب نفسَك تَجُز شهادتُك. فأبى أن يُكَذِّب نفسَه، ولم يكن عمر يجيز شهادتهما حتى هلكا، فذلك قوله: {إلا الذين تابوا}، وتوبتهم إكذابهم أنفسهم."}, "52430": {"num": 52430, "aya": 5, "qail": "سعيد بن المسيب", "tabaqa": "تابعي", "bab": "أحكام الآية", "text": "عن سعيد بن المسيب، قال: شهد على المغيرة بن شعبة ثلاثةٌ بالزنا، ونكَلَ زيادٌ، فحدَّ عمرُ بن الخطاب الثلاثة، وقال لهم: توبوا تقبل شهادتكم. فتاب رجلان، ولم يتب أبو بكرة، فكان لا تقبل شهادته، وكان أبو بكرة أخا زياد لأُمِّه، فلما كان مِن أمر زياد ما كان حلف أبو بكرة أن لا يكلمه أبدًا، فلم يكلمه حتى مات."}, "52435": {"num": 52435, "aya": 5, "qail": "شريح القاضي", "tabaqa": "تابعي", "bab": "أحكام الآية", "text": "عن شريح القاضي -من طريق الشعبي- قال: كلُّ صاحبِ حَدٍّ تجوز شهادتُه، إلا القاذفَ، فإنّ توبته فيما بينه وبين ربِّه."}, "52436": {"num": 52436, "aya": 5, "qail": "سعيد بن المسيب", "tabaqa": "تابعي", "bab": "أحكام الآية", "text": "عن سعيد بن المسيب ="}, "52437": {"num": 52437, "aya": 5, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "أحكام الآية", "text": "والحسن البصري، قالا: القاذِفُ إذا تاب فتوبتُه فيما بينه وبين الله، ولا تجوز شهادته."}, "52440": {"num": 52440, "aya": 5, "qail": "عمران بن عمير", "tabaqa": "", "bab": "أحكام الآية", "text": "عن عمران بن عمير: أنّ عبد الله بن عتبة كان يجيز شهادة القاذف إذا تاب."}, "52441": {"num": 52441, "aya": 5, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "أحكام الآية", "text": "عن إبراهيم النخعي -من طريق الثوري- قال: لا تقبل للقاذف شهادة، توبته بينه وبين ربه."}, "52445": {"num": 52445, "aya": 5, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "أحكام الآية", "text": "وعامر الشعبي -من طريق قتادة- قالا: إذا تاب القاذفُ عند الجلد جازت شهادته."}, "52446": {"num": 52446, "aya": 5, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "أحكام الآية", "text": "عن عامر الشعبي -من طريق إسماعيل بن أبي خالد-أنّه كان يقول: يقبل الله توبتَه، وتَرُدُّون شهادتَه؟! وكان يقبل شهادتَه إذا تاب."}, "52447": {"num": 52447, "aya": 5, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "أحكام الآية", "text": "عن الضحاك بن مزاحم -من طريق جُوَيْبِر- قال: إذا تاب وأصلح قُبِلَت شهادته، يعني: القاذف."}, "52448": {"num": 52448, "aya": 5, "qail": "قتادة", "tabaqa": "تابعي", "bab": "أحكام الآية", "text": "عن قتادة: أنّ عمر بن عبد الله بن أبي طلحة جلد رجلًا في قَذْف، فقال: أكْذِبْ نفسَك حتى تجوزَ شهادتُك."}, "52465": {"num": 52465, "aya": 5, "qail": "سعيد بن المسيب", "tabaqa": "تابعي", "bab": "أحكام الآية", "text": "وسعيد بن المسيب: أنّ شهادته لا تجوز أبدًا. ="}, "52469": {"num": 52469, "aya": 5, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن الحسن البصري -من طريق إسماعيل- قال: الزِّنا أشدُّ مِن القذف، والقذفُ أشدُّ مِن الشرب."}, "52523": {"num": 52523, "aya": 11, "qail": "عائشة", "tabaqa": "صحابي", "bab": "نزول الآيات، وبيان قصة الإفك", "text": "عن عائشة، قالت: كان رسولُ الله صلى الله عليه وسلم إذا أراد أن يخرج سفرًا أقْرَع بين أزواجه، فأيتهن خرج سهمُها خرج بها رسول الله صلى الله عليه وسلم معه. قالت عائشة: فأقرع بيننا في غزوة غزاها، فخرج سهمي، فخرجتُ مع رسول الله صلى الله عليه وسلم بعد ما نزل الحجاب، فأنا أُحْمَل في هَوْدَجِي، وأنزل فيه، فسِرنا حتى إذا فرغ رسول الله صلى الله عليه وسلم من غزوته تلك وقَفَلَ ودَنَوْنا من المدينة قافِلين آذَنَ ليلةً بالرحيل، فقمت حين آذنوا بالرحيل، فمشيت حتى جاوزت الجيشَ، فلمّا قضيت شأني أقبلت إلى رَحْلي، فإذا عِقْدٌ لي من جَزْع ظَفارٍ قد انقطع، فالتمست عِقْدي، وحَبَسَني ابتغاؤه، وأقبل الرَّهْطُ الذين كانوا يُرَحِّلُون لي، فاحتملوا هَوْدَجي، فرَحَّلوه على بعيري الذي كنتُ ركبتُ، وهم يحسبون أنِّي فيه، وكان النساء إذ ذاك خِفافًا لم يثقلهن اللحمُ، إنما تأكل المرأة العُلْقَةَ من الطعام، فلم يستنكر القومُ خِفَّةَ الهَوْدَج حين رفعوه، وكنت جاريةً حديثةَ السِّنِّ، فبعثوا الجمل، فساروا، فوجدت عِقْدي بعد ما اسْتَمَرَّ الجيشُ، فجئت منازلَهم، وليس بها داعٍ ولا مُجِيب، فأَمَمْتُ منزلي الذي كنتُ به، فظننتُ أنّهم سيفقدوني، فيرجعون إلَيَّ، فبينا أنا جالسةٌ في منزلي غَلَبَتْني عيني، فنِمْتُ، وكان صفوان بن المُعَطِّل السُّلَمي ثم الذَّكْوانِي مِن وراء الجيش، فأَدْلَجَ، فأصبح عند منزلي، فرأى سواد إنسان نائم، فأتاني، فعرفني حين رآني، وكان يراني قبل الحجاب، فاستيقظتُ باسترجاعه حين عرفني، فخمَّرْتُ وجهي بجلبابي، واللهِ، ما كَلَّمَنِي كلمةً، ولا سمعت منه كلمةً غيرَ استرجاعه، حتى أناخ راحلته، فوَطِئ على يدَيْها، فركبتها، فانطلق يقود بي الراحلةَ حتى أتينا الجيشَ بعد ما نزلوا مُوغِرين في نَحْرِ الظَّهِيرَة، فهلك فِيَّ مَن هلك. وكان الذي تَوَلّى الإفكَ عبدُ الله بن أُبَيّ بن سَلُول، فقدمنا المدينة، فاشتكيت حين قدمت شهرًا، والناسُ يُفيضون في قول أصحاب الإفك، لا أشعر بشيء من ذلك، وهو يَرِيبُني في وجعي أنِّي لا أعرف مِن رسول الله صلى الله عليه وسلم اللُّطْفَ الذي كنت أرى منه حين أشتكى، إنّما يدخل عَلَيَّ، فيُسَلِّم، ثم يقول: «كيف تيكم؟». ثم ينصرف، فذاك الذي يَرِيبُني، ولا أشعر بالشرِّ حتى خرجت بعدما نَقَهْتُ، وخرجت معي أمُّ مِسْطَح قِبَل المناصِع، وهي مُتَبَرَّزُنا، وكُنّا لا نخرج إلا ليلًا إلى ليل، وذلك قبل أن نتَّخِذ الكُنُف قريبًا مِن بيوتنا، وأَمْرُنا أمْرُ العربِ الأول في التَّبَرُّز قبل الغائط؛ فكُنّا نتأذى بالكُنُف أن نتَّخذها عند بيوتنا، فانطلقت أنا وأمُّ مِسْطَح، فأقبلتُ أنا وأمُّ مسطح قِبَل بيتي قد فرغنا مِن شأننا، فعَثَرَت أمُّ مِسْطَح في مِرْطها، فقالت: تَعِس مِسْطَحُ. فقلتُ لها: بِئْسَ ما قلتِ، أتسبين رجلًا شهد بدرًا؟! قالت: أيْ هَنَتاهُ، أوَلَمْ تسمعي ما قال؟ قلتُ: وما قال؟ فأخبرتني بقول أهل الإفك، فازددتُ مرضًا على مرضي، فلمّا رجعتُ إلى بيتي دَخَل عَلَيَّ رسولُ الله صلى الله عليه وسلم، فسَلَّم، ثم قال: «كيف تيكم؟». فقلتُ: أتأذن لي أن آتي أبَوَيَّ؟ قالت: وأنا حينئذ أريد أن أستيقن الخبر مِن قِبَلِهما. قالت: فأذِنَ لي رسولُ الله صلى الله عليه وسلم، فجئتُ أبَوَيَّ، فقلتُ لأمي: يا أُمَّتاهُ، ما يتحدثُ الناسُ؟ قالت: يا بُنَيَّةُ، هَوِّني عليكِ، فواللهِ، لقَلَّما كانتِ امرأةٌ قَطُّ وضيئة عند رجل يحبها ولها ضَرائِرُ إلّا أكْثَرْن عليها. فقلت: سبحان الله، ولقد تحدث الناسُ بهذا؟! فبكيتُ تلك الليلةَ حتى أصبحتُ لا يَرْقَأُ لي دَمْعٌ، ولا أكتحل بنوم، ثم أصبحتُ أبكي. ودعا رسولُ الله صلى الله عليه وسلم عليَّ بن أبي طالب وأسامةَ بن زيد حين اسْتَلْبَثَ الوحيُ، يَسْتَأْمِرُهما في فراق أهله، فأمّا أسامةُ فأشار على رسول الله صلى الله عليه وسلم بالَّذي يعلم مِن براءة أهله، وبالذي يعلم لهم في نفسه مِن الوُدِّ، فقال: يا رسول الله، أهلُك، ولا نعلم إلا خيرًا. وأما عليُّ بن أبي طالب فقال: يا رسول الله، لم يُضَيِّق اللهُ عليك، والنساءُ سواها كثيرٌ، وإن تسأل الجاريةَ تصدُقْكَ. فدعا رسولُ الله صلى الله عليه وسلم بَرِيرَةَ، فقال: «أيْ بريرةُ، هل رأيتِ شيئًا يَريبُكِ؟». قالت بريرةُ: لا، والذي بعثك بالحق، إن رأيت عليها أمرًا أغْمِصُه أكثرَ مِن أنّها جاريةٌ حديثةُ السِّنِّ، تنامُ عن عجين أهلها، فتأتي الدِّاجِنُ فتأكله. فقام رسول الله صلى الله عليه وسلم، فاسْتَعْذَرَ يومئذٍ مِن عبد الله بن أُبَيٍّ، فقال وهو على المنبر: «يا معشرَ المسلمين، مَن يعذرني مِن رجل بلغني أذاهُ في أهل بيتي؟ فواللهِ، ما علمتُ على أهلي إلا خيرًا، ولقد ذكروا رجلًا ما علمتُ عليه إلا خيرًا، وما كان يدخل على أهلي إلا معي». فقام سعدُ بن معاذ الأنصاريُّ، فقال: يا رسول الله، أنا أعذرك منه، إن كان مِن الأوس ضربنا عنقه، وإن كان من إخواننا مِن الخزرج أمرتنا ففعلنا أمرَك. فقام سعد بن عبادة -وهو سيِّدُ الخزرج، وكان قبلَ ذلك رجلًا صالحًا، ولكن احتملته الحَمِيَّةُ- فقال لسعد: كذبتَ، لَعَمْرُ اللهِ، ما تقتلُه، ولا تقدر على قتله. فقام أُسَيْد بن حُضَيْر، وهو ابنُ عمِّ سعد، فقال لسعد بن عبادة: كذبتَ، لَعَمْرُ الله، لنَقْتُلَنَّه، فإنّك مُنافِق تُجادِل عن المنافقين. فتَثاوَر الحيّانِ الأوسُ والخزرج، حتى همُّوا أن يقتتلوا، ورسولُ الله صلى الله عليه وسلم قائِم على المنبر، فلم يزل رسولُ الله صلى الله عليه وسلم يُخَفِّضهم حتى سكتوا وسَكَت. فمكثتُ يومي ذلك فلا يرقأ لي دمع، ولا أكتحل بنوم، فأصبح أبواي عندي، وقد بكيت ليلتين ويومًا لا أكتحل بنوم، ولا يرقأ لي دمع، وأبواي يظُنّانِ أنّ البكاءَ فالِقٌ كَبِدِي، فبينما هما جالسان عندي وأنا أبكي، فاستأذَنَتْ عَلَيَّ امرأةٌ مِن الأنصار، فأذِنتُ لها، فجلست تبكي معي، فبينا نحن على ذلك دخل علينا رسولُ الله صلى الله عليه وسلم، ثم جلس، ولم يجلس عندي مُنذ قيل فِيَّ ما قيل قبلها، وقد لَبِث شهرًا لا يُوحى إليه في شأني بشيء، فتَشَهَّد حين جلس، ثم قال: «أمّا بعدُ، يا عائشة، فإنّه بلغني عنكِ كذا وكذا، فإن كنتِ بريئة فسَيُبَرِّئُكِ اللهُ، وإن كنتِ ألْممتِ بذنب فاستغفري الله وتوبي إليه؛ فإنّ العبد إذا اعترف بذنبه ثم تاب تاب اللهُ عليه». فلمّا قضى رسولُ الله صلى الله عليه وسلم مقالتَه قَلَصَ دمعي حتى ما أُحِسُّ منه قطرةً، فقلتُ لأبي: أجِبْ عَنِّي رسولَ الله صلى الله عليه وسلم. قال: واللهِ، ما أدري ما أقولُ لرسول الله صلى الله عليه وسلم! فقلتُ لأمي: أجيبي عَنِّي رسولَ الله صلى الله عليه وسلم. قالت: ما أدري ما أقول لرسول الله صلى الله عليه وسلم! فقلتُ وأنا جاريةٌ حديثةُ السِّنِّ لا أقرأ كثيرًا مِن القرآن: إني -واللهِ- لقد علمتُ أنّكم سمعتُم هذا الحديثَ حتى اسْتَقَرَّ في أنفسكم، وصدَّقْتُم به، فلَئِن قلتُ لكم: إني بريئة. واللهُ يعلم أنِّي بريئة، لا تُصَدِّقوني، ولئن اعترفتُ لكم بأمرٍ، واللهُ يعلم أنِّي منه بريئة، لتُصَدِّقُنِّي، واللهِ، لا أجد لي ولكم مَثَلًا إلا قول أبي يوسف: {فصبر جميل والله المستعان على ما تصفون} [يوسف: 18]. ثم تَحَوَّلتُ، فاضطجعتُ على فراشي، وأنا حينئذ أعلمُ أنِّي بريئة، وأنّ الله مُبَرِّئي ببراءتي، ولكن -واللهِ- ما كنتُ أظُنَّ أنّ الله مُنزِلٌ في شأني وحيًا يُتْلى، ولَشأني في نفسي كان أحقرَ مِن أن يتكلم اللهُ فِيَّ بأمر يُتْلى، ولكن كنت أرجو أن يرى رسولُ الله صلى الله عليه وسلم في النوم رؤيا يُبَرِّئني الله بها. قالت: فواللهِ، ما رام رسول الله صلى الله عليه وسلم مجلسَه ولا خرج أحدٌ مِن أهل البيت حتى أُنزِل عليه، فأخذه ما كان يأخذه مِن البُرَحاء عند الوحي، حتى إنّه لَيَتَحَدَّر مِنه مِثْلُ الجُمانِ مِن العَرَق وهو في يوم شاتٍ، مِن ثِقَل القول الذي أُنزِل عليه، فلمّا سُرِّي عن رسول الله صلى الله عليه وسلم سُرِّي عنه وهو يضحك، فكان أول كلمة تكلم بها أن قال: «أبشري، يا عائشة، أمّا اللهُ فقد برأك». فقالت أمي: قومي إليه. فقلت: واللهِ، لا أقوم إليه، ولا أحمدُ إلا اللهَ الذي أنزل براءتي. وأنزل الله: {ان الذين جاءوا بالافك عصبة منكم} العشرَ الآياتِ كلَّها. فلمّا أنزل الله هذا في براءتي قال أبو بكر -وكان يُنفِق على مِسْطَح بن أثاثة لقرابته منه وفقره-: واللهِ، لا أُنفِق على مِسْطَح شيئًا أبدًا بعد الذي قال لعائشة ما قال. فأنزل الله: {ولا يأتل أولو الفضل منكم والسعة أن يؤتوا أولي القربي والمساكين} إلى قوله: {رحيم}. قال أبو بكر: بلى، واللهِ، إنِّي أُحِبُّ أن يغفر الله لي. فرَجَع إلى مِسْطَحٍ النفقة التي كان يُنفِق عليه، وقال: واللهِ، لا أنزعها منه أبدًا. قالت عائشة: فكان رسول الله صلى الله عليه وسلم يسأل زينبَ ابنةَ جحش عن أمري، فقال: «يا زينبُ، ماذا علمتِ أو رأيتِ؟». فقالت: يا رسول الله، أحمي سمعي وبصري، ما علمت إلا خيرًا. قالت: وهي التي كانت تُسامِينِي مِن أزواج النبيِّ صلى الله عليه وسلم، فعصمها اللهُ بالوَرَع، وطَفِقَتْ أختُها حَمْنَةُ تُحارِب لها؛ فهلكت فيمن هلك مِن أصحاب الإفك."}, "52524": {"num": 52524, "aya": 11, "qail": "عائشة", "tabaqa": "صحابي", "bab": "نزول الآيات، وبيان قصة الإفك", "text": "عن عائشة، قالت: لَمّا ذكر من شأني الذي ذكر، وما علمت به، قام رسول الله صلى الله عليه وسلم فِيَّ خطيبًا، فتَشَهَّدَ، فحمِد الله، وأثنى عليه، ثم قال: «أمّا بعدُ، أشِيروا عَلَيَّ في أُناسٍ أبَنُوا أهلي، وأيْمُ اللهِ، ما علمتُ على أهلي مِن سوء، وأبَنُوهم بِمَن -واللهِ- ما علمتُ عليه مِن سوء قطُّ، ولا يدخل بيتيَ قطُّ إلا وأنا حاضر، ولا غبت في سفر إلا غاب معي». فقام سعدُ بن معاذ، فقال: ائذن لي -يا رسول الله- أن أضرب أعناقهم. وقام رجلٌ مِن بني الخزرج -وكانت أم حسان بن ثابت مِن رهط ذلك الرجل-، فقال: كذبتَ، أما -واللهِ- أن لو كانوا مِن الأوس ما أحببتَ أن تضرب أعناقهم. حتى كاد أن يكون بين الأوس والخزرج شرٌّ في المسجد، وما علمت، فلمّا كان مساء ذلك اليوم خرجتُ لبعض حاجتي، ومعي أُمُّ مِسْطَح، فعثَرتْ، فقالت: تَعِس مِسْطَح. فقلت: أي أُمّ، تَسُبِّين ابنَك؟! فسكتت، ثم عثرت الثانية، فقالت: تَعِس مِسْطَح. فقلتُ لها: أيْ أم، تسبين ابنكِ؟! ثم عثرت الثالثة، فقالت: تَعِس مِسْطَح. فانتَهَرْتُها، فقالت: واللهِ، لم أسُبَّه إلا فيكِ. فقلت: فِيَّ؛ أي شأني؟! فبَقَرَت لي الحديث، فقلتُ: وقد كان هذا؟! قالت: نعم، والله. فرجعت إلى بيتي كأنّ الذي خرجت له لا أجد منه قليلًا ولا كثيرًا، ووعكت، فقلتُ لرسول الله صلى الله عليه وسلم: أرسِلْني إلى بيت أبي. فأرسل معي الغلام، فدخلت الدارَ، فوجدت أمَّ رَوْمان في السفل، وأبا بكر فوق البيت يقرأ، فقالت أمي: ما جاء بك، يا بنية؟ فأخبرتها، وذكرت لها الحديث، وإذا هو لم يبلغ منها مثل ما بلغ مِنِّي، فقالت: يا بُنَيَّة، خفضي عليك الشأن، فإنّه -واللهِ- لقَلَّما كانت امرأةٌ حسناء عند رجل يحبها لها ضرائر إلا حَسَدْنها، وقيل فيها. قلت: وقد علم به أبي؟ فقالت: نعم. قلت: ورسول الله صلى الله عليه وسلم؟ قالت: نعم. فاسْتَعْبَرْتُ وبكيت، فسمع أبو بكر صوتي وهو فوق البيت يقرأ، فنزل، فقال لأمي: ما شأنها؟ قالت: بلغها الذي ذُكِر مِن شأنها. ففاضت عيناه، فقال: أقسمتُ عليك -أي بنية- إلا رجعتِ إلى بيتك. فرجعتُ. ولقد جاء رسول الله صلى الله عليه وسلم بيتي، فسأل عني خادمي، فقالت: لا، واللهِ، ما علمتُ عليها عيبًا إلا أنها كانت ترقد حتى تدخل الشاةُ فتأكلُ خميرَها أو عجينها. وانتهرها بعضُ أصحابه، فقال: اصدقي رسول الله صلى الله عليه وسلم. حتى أسقطوا لها به، فقالت: سبحان الله! ما علمتُ عليها إلا ما يعلم الصائِغُ على تِبْرِ الذهب الأحمر. وبلغ الأمرُ إلى ذلك الرجل الذي قيل له، فقال: سبحان الله! واللهِ، ما كشفتُ كَنَف أُنثى قَطُّ. قالت عائشة: فقُتِل شهيدًا في سبيل الله. قالت: وأصبح أبواي عندي، فلم يزالا حتى دخل عَلَيَّ رسولُ الله صلى الله عليه وسلم وقد صَلّى العصرَ، ثم دخل وقد اكتنفني أبواي عن يميني وعن شمالي، فحمد الله وأثنى عليه، ثم قال: «أما بعدُ، يا عائشة، إن كنتِ قارفتِ سوءًا أو ظلمتِ فتوبي إلى الله؛ فإنّ الله يقبل التوبة عن عباده». قالت: وقد جاءت امرأةٌ من الأنصار فهي جالسة بالباب، فقلت: ألا تستحي مِن هذه المرأة أن تذكر شيئًا؟! فوعظ رسولُ الله صلى الله عليه وسلم، فالتفتُّ إلى أبي، فقلتُ: أجبه. قال: ماذا أقول؟ فالتفتُّ إلى أمي، فقلتُ: أجيبيه. قالت: أقول ماذا؟ فلمّا [لم] يجيباه تشهدتُ، فحمدت الله، وأثنيت عليه، ثم قلت: أما بعد، فواللهِ، لئن قلتُ لكم: إني لم أفعل. واللهُ يشهد إني لصادقة؛ ما ذاك بنافعي عندكم، وقد تكلمتُم به، وأُشْرِبَتْه قلوبُكم، وإن قلت: إني فعلت. واللهُ يعلم أني لم أفعل؛ لَتَقُولُنَّ: قد باءت به على نفسها. وإني -واللهِ- ما أجد لي ولكم مثلًا -والتَمَسْتُ اسم يعقوب فلم أقدر عليه- إلا أبا يوسف حين قال: {فصبر جميل والله المستعان على ما تصفون} [يوسف: 18]. وأُنزِل على رسول الله صلى الله عليه وسلم مِن ساعته، فسكتنا، فرُفِع عنه وإنِّي لأتبين السرور في وجهه وهو يمسح جبينه، ويقول: «أبشري، يا عائشة، فقد أنزل الله براءتك». قالت: وقد كنت أشدَّ مِمّا كنتُ غضبًا، فقال لي أبواي: قومي إليه. فقلت: واللهِ، لا أقوم إليه، ولا أحمده، ولا أحمدكما، ولكن أحمد الله الذي أنزل براءتي، لقد سمعتموه فما أنكرتموه ولا غَيَّرتموه. وكانت عائشةُ تقول: أمّا زينب ابنة جحش فعصمها الله لدينها؛ فلم تقل إلا خيرًا، وأما أختها حَمْنَة فهلكت في مَن هلك. وكان الذي تَكَلَّم فيه مسطح، وحسان بن ثابت، والمنافق عبد الله بن أُبَيّ، وهو الذي كان يَسْتَوْشِيهِ ويجمعه، وهو الذي كان تَوَلّى كبره منهم هو وحَمْنَة. قال: فحلف أبو بكر ألّا ينفع مِسْطَحًا بنافعةٍ أبدًا؛ فأنزل الله: {ولا يأتل أولو الفضل منكم} يعني: أبا بكر، {والسعة أن يؤتوا أولي القربى والمساكين} يعني: مسطحًا. إلى قوله: {ألا تحبون أن يغفر الله لكم والله غفور رحيم} قال أبو بكر: بلى، يا ربنا، إنّا لَنُحِبُّ أن تغفر لنا. وعاد له بما كان يصنع."}, "52530": {"num": 52530, "aya": 11, "qail": "عائشة", "tabaqa": "صحابي", "bab": "نزول الآيات، وبيان قصة الإفك", "text": "عن عائشة -من طريق عمرة- قالت: لَمّا نزل عُذري قام رسولُ الله صلى الله عليه وسلم على المِنبر، فذكر ذلك، وتلا القرآن، فلما نزل أمَر برجلين وامرأة، فضُرِبوا حَدَّهُم."}, "52531": {"num": 52531, "aya": 11, "qail": "عائشة", "tabaqa": "صحابي", "bab": "نزول الآيات، وبيان قصة الإفك", "text": "عن عائشة -من طريق الأسود- قالت: أنزل الله عذري، وكادتِ الأُمَّة تهلك في سَبَبِي، فلمّا سُرِّيَ عن رسول الله صلى الله عليه وسلم وعَرَج الملَكُ قال رسول الله صلى الله عليه وسلم لأَبي: «اذهب إلى ابنتك، فأخبِرها أنّ الله قد أنزل عُذْرَها مِن السماء». قالت: فأتاني أبي وهو يعدو يكاد أن يعثر، فقال: أبشِري، يا بنية، بأبي وأمي؛ فإنّ الله قد أنزل عذركِ. قلتُ: بحمد الله، لا بحمدك، ولا بحمد صاحبك الذي أرسلك. ثم دخل رسول الله صلى الله عليه وسلم، فتناول ذراعي، فقلت بيده هكذا، فأخذ أبو بكر النَّعْلَ ليعلوني بها، فمَنَعَتْهُ أُمِّي، فضحك رسول الله صلى الله عليه وسلم، فقال: «أقسمتُ لا تفعل»."}, "52539": {"num": 52539, "aya": 11, "qail": "عائشة", "tabaqa": "صحابي", "bab": "آثار متعلقة بالقصة", "text": "عن عائشة -من طرقٍ- قالت: واللهِ، ما كنتُ أرجو أن ينزل فِيَّ كتابُ الله، ولا أطمع فيه، ولكني كنت أرجو أن يرى رسولُ الله صلى الله عليه وسلم رؤيا، فيذهبُ ما في نفسه، وقد سأل الجاريةَ الحبشيةَ، فقالت: واللهِ، لعائشة أطيب مِن طيب الذهب، ولكنها ترقد حتى تدخل الشاةُ فتأكل عجينها، واللهِ، لئن كان ما يقول الناسُ حقًّا ليخبرنَّك اللهُ. فعجب الناسُ مِن فقهها."}, "52540": {"num": 52540, "aya": 11, "qail": "عائشة", "tabaqa": "صحابي", "bab": "آثار متعلقة بالقصة", "text": "عن عائشة، قالت: لَمّا رُمِيتُ بما رُمِيت به هممتُ أن آتي قَلِيبًا فأطرحَ نفسي فيه."}, "52541": {"num": 52541, "aya": 11, "qail": "عائشة", "tabaqa": "صحابي", "bab": "آثار متعلقة بالقصة", "text": "عن عائشة: أنّه لَمّا نزل عذرها قَبَّلَ أبو بكر رأسها، فقالت: ألا عذرتني؟ فقال: أيُّ سماء تُظِلُّني، وأيُّ أرض تُقِلُّني؛ إن قلتُ ما لا أعلم."}, "52544": {"num": 52544, "aya": 11, "qail": "عائشة", "tabaqa": "صحابي", "bab": "آثار متعلقة بالقصة", "text": "عن عائشة، قالت: خِلالٌ لي تِسعٌ لم تكن لأحدٍ إلا ما آتى الله مريمَ: جاء الملَك بصورتي إلى رسول الله صلى الله عليه وسلم، وتزوجني وأنا ابنة سبع سنين، وأُهديت اليه وأنا ابنة تسع، وتزوجني بِكْرًا، وكان يأتيه الوحي وأنا وهو في لحاف واحد، وكنت مِن أحبِّ الناس إليه، ونزل فِيَّ آياتٌ مِن القرآن كادت الأمةُ تهلك فيها، ورأيت جبريلَ ولم يره أحدٌ مِن نسائه غيري، وقُبِض في بيتي لم يَلِه أحدٌ غير الملَك إلا أنا."}, "52545": {"num": 52545, "aya": 11, "qail": "عائشة", "tabaqa": "صحابي", "bab": "آثار متعلقة بالقصة", "text": "عن عائشة، قالت: فُضِّلتُ على نساء النبي صلى الله عليه وسلم بعشرٍ. قيل: ما هُنَّ، يا أم المؤمنين؟ قالت: لم ينكح بِكْرًا قطُّ غيري، ولم ينكح امرأةً أبواها مهاجران غيري، وأنزل الله براءتي مِن السماء، وجاءه جبريل بصورتي من السماء في حريرة، وقال: تَزَوَّجْها؛ فإنّها امرأتك. وكنت أغتسل أنا وهو مِن إناء واحد، ولم يكن يصنع ذلك بأحدٍ مِن نسائه غيري، وكان يصلي وأنا معترضة بين يديه، ولم يكن يفعل ذلك بأحد مِن نسائه غيري، وكان ينزل عليه الوحيُ وهو معي، ولم يكن ينزل عليه وهو مع أحد من نسائه غيري، وقَبض الله نفسَه وهو بين سَحْري ونَحْري، ومات في الليلة التي كان يدور عَلَيَّ فيها، ودُفِن في بيتي."}, "52559": {"num": 52559, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جُرَيج- في قوله: {إن الذين جاءوا بالإفك عصبة منكم}، قال: أصحابُ عائشة؛ عبد الله بن أُبي بن سلول، ومسطح، وحسان."}, "52567": {"num": 52567, "aya": 11, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {إن الذين جاءوا بالإفك عصبة منكم لا تحسبوه شرا لكم بل هو خير لكم}، قال: الشرُّ لكم بالإفك الذي قالوا، الذي تكلموا به كان شرًا لهم، وكان فيهم مَن لم يقله إنما سمعه، فعاتبهم الله، فقال أول شيء: {إن الذين جاءوا بالإفك عصبة منكم لا تحسبوه شرا لكم، بل هو خير لكم}. ثم قال: {والذي تولى كبره منهم له عذاب عظيم}."}, "52573": {"num": 52573, "aya": 11, "qail": "مسروق", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن مسروق، قال: في قراءة عبد الله [بن مسعود]: (والَّذِي تَوَلّى كِبْرَهُ مِنهُمْ لَهُ عَذابٌ ألِيمٌ)."}, "52575": {"num": 52575, "aya": 11, "qail": "عائشة", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عائشة -من طريق عروة- قالت: كان الذين تَكَلَّموا فيه: المنافق عبد الله بن أُبي بن سلول، وكان يَسْتَوْشِيه، ويجمعه، وهو الذي تولّى كِبْرَه، ومِسْطحًا، وحسان بن ثابت، وحمنة."}, "52580": {"num": 52580, "aya": 11, "qail": "عائشة", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عائشة -من طريق الشعبي- أنّها قالتْ: ما سمعتُ بشيء أحسنَ من شِعر حسان، وما تَمَثَّلْتُ به إلا رجوتُ له الجنةَ، قوله لأبي سفيان بن الحارث بن عبد المطلب: هجوت محمدًا وأجبت عنه … وعند الله في ذاك الجزاء فإن أبي ووالده وعرضي … لعرض محمد منكم وِقاء أتشتمه ولست له بكفو … فشرُّكما لخيركما الفداء لساني صارِم لا عيب فيه … وبحري لا تُكَدِّره الدِّلاء فقيل: يا أم المؤمنين، أليس هذا لغوًا؟ قالت: لا، إنّما اللغوُ ما قيل عند النساء. قيل: أليس الله يقول: {والذي تولى كبره منهم له عذاب عظيم}؟ قالت: أليس قد أصابه عذاب عظيم؟ أليس قد ذهب بصره، وكُسِعَ بالسيف؟ وتعني: الضربة التي ضربها إياه صفوان بن المعطل حين بلغه عنه أنه تكلَّم في ذلك، فعلاه بالسيف، وكاد يقتله."}, "52581": {"num": 52581, "aya": 11, "qail": "مسروق", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مسروق، قال: دخل حسانُ بن ثابت على عائشة، فشبَّب، وقال: حَصانٌ رَزانٌ ما تُزَنُّ بِرِيبَةٍ … وتُصْبِحُ غَرْثى مِن لُحومِ الغَوافِلِ قالت: لكنك لست كذلك. قلت: تَدَعِين مثل هذا يدخلُ عليكِ، وقد أنزل الله: {والذي تولى كبره منهم له عذاب عظيم}؟! فقالت: وأي عذاب أشدُّ مِن العَمى؟! ولفظ ابن مردويه: أوَلَيس في عذابٍ؟ قد كُفَّ بَصَرُه."}, "52585": {"num": 52585, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {والذي تولى كبره}، قال: هو عبد الله بن أُبي بن سلول، وهو بدأه."}, "52593": {"num": 52593, "aya": 11, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب-: أمّا الذي تولى كبره منهم فعبد الله بن أبي بن سلول الخبيث، هو الذي ابتدأ هذا الكلام، وقال: امرأةُ نبيِّكم باتت مع رجل حتى أصبحت، ثم جاء يقود بها!."}, "52729": {"num": 52729, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {إن الذين يرمون المحصنات الغافلات المؤمنات}، قال: نزلت في عائشة خاصةً. زاد ابن أبي حاتم: {لعنوا في الدنيا والآخرة}، قال: واللعنةُ في المنافقين عامَّةً. (10/ 708)"}, "52730": {"num": 52730, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق العَوّام بن حَوْشَب، عن شيخ من بني أسد-: أنّه قرأ سورة النور، ففسَّرها، فلمّا أتى على هذه الآية: {إن الذين يرمون المحصنات الغافلات} قال: هذه في عائشةَ وأزواجِ النبيِّ صلى الله عليه وسلم، ولم يجعل لِمَن فعل ذلك توبةً، وجعل لِمَن رمى امرأةً مِن المؤمنات مِن غير أزواج النبي صلى الله عليه وسلم التوبة. ثم قرأ: {إن الذين يرمون المحصنات ثم لم يأتوا بأربعة شهداء} إلى قوله: {إلا الذين تابوا}. فجعل لِمَن قذف امرأةً مِن المؤمنين التوبة، ولم يجعل لِمَن قذف امرأةً مِن أزواج النبي صلى الله عليه وسلم توبة. ثم تلا هذه الآية: {لعنوا في الدنيا والآخرة ولهم عذاب عظيم}. فهَمَّ بعضُ القوم أن يقومَ إلى ابن عباس فيُقَبِّل رأسه؛ لِحُسْن ما فَسَّر."}, "52731": {"num": 52731, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق العوفي- قوله: {إن الذين يرمون المحصنات الغافلات المؤمنات} إلى {عذاب عظيم}، يعني: أزواج النبيَّ صلى الله عليه وسلم، رَماهُنَّ أهلُ النفاق، فأوجب الله لهم اللعنة والغضب، وباءوا بسخط مِن الله. وكان ذلك في أزواج النبي صلى الله عليه وسلم، ثم نزل بعد ذلك: {والذين يرمون المحصنات ثم لم يأتوا بأربعة شهداء} إلى قوله: {فإن الله غفور رحيم}، فأنزل الله الجلدَ والتوبةَ، فالتوبة تُقبَل، والشهادةُ تُرَدّ."}, "52741": {"num": 52741, "aya": 23, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "نزول الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- {إن الذين يرمون المحصنات الغافلات المؤمنات لعنوا في الدنيا والآخرة ولهم عذاب عظيم}، قال: هذا في عائشة، ومَن صنع هذا اليوم في المسلمات فله ما قال الله، ولكن عائشة كانت إمام ذلك."}, "52742": {"num": 52742, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق ابن جُرَيج عن عطاء، ومقاتل بن سليمان عن الضحاك-: {ان الذين يرمون المحصنات} يريد: العفائف، {الغافلات المؤمنات} يريد: المُصَدِّقات بتوحيد الله وبرسله. وقد قال حسان بن ثابت في عائشة: حَصانٌ رَزانٌ ما تُزَنُّ برِيبة … وتُصْبِحُ غَرْثى مِن لحومِ الغَوافِل فقالت عائشة: لكنك لست كذلك. {لعنوا في الدنيا والآخرة ولهم عذاب عظيم} يقول: أخرجهم من الإيمان. مثل قوله في سورة الأحزاب [61] للمنافقين: {ملعونين أينما ثقفوا أخذوا وقتلوا تقتيلا}."}, "52746": {"num": 52746, "aya": 23, "qail": "جعفر بن برقان", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن جعفر بن بُرْقان، قال: سألتُ ميمون بن مِهْران، قلتُ: الذي ذكر الله: {الذين يرمون المحصنات ثم لم يأتوا بأربعة شهداء} إلى قوله: {إلا الذين تابوا من بعد ذلك وأصلحوا فإن الله غفور رحيم}، فجَعَل في هذه توبة، وقال في الأخرى: {إن الذين يرمون المحصنات الغافلات} إلى قوله: {لهم عذاب عظيم}؟ قال ميمون: أمّا الأولى فعسى أن تكون قد قارَفَتْ، وأما هذه فهي التي لم تُقارِف شيئًا مِن ذلك."}, "52776": {"num": 52776, "aya": 26, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- في قوله: {الخبيثات} قال: مِن الكلام {للخبيثين} قال: مِن الرجال، {والخبيثون} مِن الرجال {للخبيثات} من الكلام، {والطيبات} مِن الكلام {للطيبين} من الناس، {والطيبون} من الناس، {للطيبات} مِن الكلام؛ نزلت في الذين قالوا في زوجة النبي صلى الله عليه وسلم ما قالوا من البهتان."}, "52777": {"num": 52777, "aya": 26, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق ابن جريج عن عطاء [بن أبي رباح]، ومقاتل بن سليمان عن الضحاك-: {الخبيثات للخبيثين} يريد: أمثال عبد الله بن أبي، ومَن شكَّ في الله، ويقذف مثل سيدة نساء العالمين، {والطيبات للطيبين} عائشة طيَّبها الله لرسوله، أتى بها جبريلُ في سَرَقَةٍ من حرير قبل أن تُصَوَّر في رَحِم أُمِّها، فقال له: عائشة بنت أبي بكر زوجتك في الدنيا، وزوجتك في الجنة، عِوَضًا من خديجة. وذلك عند موتها، فسُرَّ بها رسولُ الله صلى الله عليه وسلم، وقَرَّ بها عينًا، {والطيبون للطيبات} يريد: رسول الله صلى الله عليه وسلم، طيَّبه الله لنفسه، وجعله سَيِّد ولد آدم، والطيبات يريد: عائشة، {أولئك مبرؤن مما يقولون} يريد: برَّأها اللهُ مِن كَذِب عبد الله بن أُبَيٍّ، {لهم مغفرة} يريد: عِصْمة في الدنيا، ومغفرة في الآخرة، {ورزق كريم} يريد: رزق الجنة، وثواب عظيم."}, "52778": {"num": 52778, "aya": 26, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق طلحة بن عمرو، عن عطاء [بن أبي رباح]- في قوله: {الخبيثات للخبيثين والخبيثون للخبيثات والطيبات للطيبين والطيبون للطيبات}، قال: الخبيثات مِن القول للخبيثين من الناس، والخبيثون مِن الناس للخبيثات من القول، والطيِّبات مِن القول للطيبين من الناس، ألا ترى أنك تسمع الكلمة الخبيثة مِن الرجل الصالح، فتقول: غفر اللهُ لفلان، ما هذا من خُلُقِه، ولا مِمّا يقول!."}, "52779": {"num": 52779, "aya": 26, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق عبد الله بن مسلم، عن سعيد بن جبير- {الخبيثات للخبيثين} قال: الخبيثات من الناس للخبيثين من الناس، {والخبيثون للخبيثات} قال: الخبيث مِن الناس له الخبيث من الكلام، {والطيبات للطيبين} قال: الطيبات مِن الكلام للطيبين من الناس، {والطيبون للطيبات} قال: الطيِّبُ مِن الناس له الطيِّب من الكلام."}, "52782": {"num": 52782, "aya": 26, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "ومجاهد بن جبر-من طريق القاسم بن أبي بَزَّة- في قوله: {والخبيثون للخبيثات} قال: الخبيثون من القوم للخبيثات من النساء."}, "52783": {"num": 52783, "aya": 26, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {الخبيثات للخبيثين والخبيثون للخبيثات والطيبات للطيبين والطيبون للطيبات}، يقول: الخبيثات والطيبات: القول السيئ والحسن؛ للمؤمنين الحسن، وللكافرين السيئ، {أولئك مبرؤون مما يقولون} وذلك بأنّه ما قال الكافرون مِن كلمة طيِّبة فهي للمؤمنين، وما قال المؤمنون مِن كلمة خبيثة فهي للكافرين، كلٌّ بريء مِمّا ليس بحقٍّ مِن الكلام."}, "52784": {"num": 52784, "aya": 26, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {الخبيثات} قال: مِن الكلام {للخبيثين} من الناس، {والخبيثون} من الناس {للخبيثات} مِن الكلام، {والطيبات} مِن الكلام {للطيبين} مِن الناس، {والطيبون} من الناس {للطيبات} من الكلام، {أولئك مبرؤون مما يقولون} قال: مَن كان طيِّبًا فهو مُبَرَّأٌ مِن كلِّ قول خبيث، يقول: يغفر الله له. ومَن كان خبيثًا فهو مُبَرَّأ مِن كل قول صالح، يقول: يرُدُّه الله عليه، لا يقبله منه."}, "52785": {"num": 52785, "aya": 26, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن الضحاك بن مزاحم ="}, "52791": {"num": 52791, "aya": 26, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "والضحاك بن مزاحم -من طريق عبيد-، مثله."}, "52792": {"num": 52792, "aya": 26, "qail": "عطاء", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن عطاء: {الخبيثات} قال: مِن القول {للخبيثين} مِن الناس، {والخبيثون} مِن الناس {للخبيثات} من القول، {والطيبات} من القول {للطيبين} من الناس، {والطيبون} مِن الناس {للطيبات} مِن القول، ألا ترى أنّك تسمع بالكلمة الخبيثة مِن الرجل الصالح فتقول: غفر الله لفلان، ما هذا مِن خُلُقِه، ولا مِن شِيَمه، ولا مِمّا يقول! قال الله: {أولئك مبرؤون مما يقولون} أن يكون ذلك مِن شِيَمِهم، وأخلاقهم، ولكن الزَّلَل قد يكون."}, "52796": {"num": 52796, "aya": 26, "qail": "عطاء الخراساني", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن عطاء الخراساني -من طريق ابنه عثمان- قال: وأمّا {الخبيثات للخبيثين} الأعمال الخبيثة والكلام الخبيث للخبيثين من الناس، وأمّا {الطيبات للطيبين} فالأعمال الصالحة والكلام الطيب للطيبين، {وهُدُوا إلى الطَّيِّبِ مِنَ القَوْلِ وهُدُوا إلى صِراطِ الحَمِيدِ} [الحج: 24]."}, "52799": {"num": 52799, "aya": 26, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {الخبيثات للخبيثين} الآيةَ، قال: نزلت في عائشة حين رماها المنافق بالبهتان والفِرْيَة، فبرَّأها الله مِن ذلك، وكان عبد الله بن أبي هو الخبيث، فكان هو أولى بأن تكون له الخبيثة، ويكون لها، وكان رسول الله صلى الله عليه وسلم طيِّبًا، وكان أولى أن تكون له الطيبة، وكانت عائشة الطيبة، وكانت أولى أن يكون لها الطيب. وفي قوله: {أولئك مبرؤون مما يقولون} قال: ههنا بَرِئَت عائشة."}, "52802": {"num": 52802, "aya": 26, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس مرفوعًا، قال: «إذا كان يومُ القيامة حدَّ الله الذين شتموا عائشة ثمانين ثمانين على رؤوس الخلائق، فيَسْتَوْهِبُ ربي المهاجرين منهم، فأستأمِرُكِ، يا عائشة». فسمعتْ عائشةُ الكلامَ، فبَكَتْ، وهي في البيت، ثم قالت: والذي بعثك بالحقِّ نبيًّا، لَسُرورُكَ أحَبُّ إلَيَّ مِن سروري. فتَبَسَّم رسولُ الله صلى الله عليه وسلم ضاحكًا، وقال: «إنها ابنة أبيها»."}, "52807": {"num": 52807, "aya": 27, "qail": "إبراهيم", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن إبراهيم، قال: في مصحف عبد الله [بن مسعود]: (حَتىَّ تُسَلِّمُواْ عَلى أهْلِها وتَسْتَأْذِنُواْ)."}, "52808": {"num": 52808, "aya": 27, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {حَتّى تَسْتَأْنِسُواْ وتُسَلِّمُواْ عَلى أهْلِها}، قال: أخطأ الكاتب، إنّما هي: (حَتىَّ تَسْتَأْذِنُواْ)."}, "52809": {"num": 52809, "aya": 27, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات", "text": "عن عبد الله بن عباس -من طريق سعيد- أنّه كان يقرأ: (حَتىَّ تَسْتَأْذِنُواْ وتُسَلِّمُواْ) ="}, "52811": {"num": 52811, "aya": 27, "qail": "سليمان الأعمش", "tabaqa": "تابع التابعين", "bab": "قراءات", "text": "عن سليمان الأعمش، قال: كان أصحاب عبد الله يقرؤونها: (حَتىَّ تَسْتَأْذِنُواْ وتُسَلِّمُواْ عَلى أهْلِها)."}, "52817": {"num": 52817, "aya": 27, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- قوله: {يا أيها الذين آمنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا وتسلموا على أهلها}، قال: الاستئناس: الاستئذان."}, "52818": {"num": 52818, "aya": 27, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- في قوله: {حتى تستأنسوا}، قال: حتى تستأذنوا."}, "52819": {"num": 52819, "aya": 27, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق جُوَيْبِر عن الضحاك- {يا أيها الذين آمنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا} قال: حتى تستأذنوا، {وتسلموا على أهلها} قال: فيه تقديم وتأخير، حتى تسلموا على أهلها وتستأنسوا."}, "52821": {"num": 52821, "aya": 27, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إبراهيم النخعي -من طريق المغيرة- قوله: {لا تدخلوا بيوتا غير بيوتكم}، قال: حتى تُسَلِّموا على أهلها وتستأذنوا."}, "52822": {"num": 52822, "aya": 27, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن جريج- في قوله: {حتى تستأنسوا}، قال: تَنَحْنحوا وتَنَخَّموا."}, "52823": {"num": 52823, "aya": 27, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قول الله: {حتى تستأنسوا}، قال: حتى تَحَسَّسوا، وتسلموا."}, "52825": {"num": 52825, "aya": 27, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- {حتى تستأنسوا}، قال: حتى تستأذنوا، وتُسَلِّموا."}, "52826": {"num": 52826, "aya": 27, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {حتى تستأنسوا}، قال: هو الاستئذان. قال: وكان يقال: الاستئذان ثلاث، فمن لم يُؤذَن له فيهنَّ فليرجع؛ أمّا الأولى فيسمع الحي، وأما الثانية فيأخذوا حِذْرَهم، وأما الثالثة فإن شاءوا أذِنوا، وإن شاءوا ردُّوا، ولا تقعدوا على باب قوم ردُّوكم عن بابهم، فإنّ للناس حاجات، ولهم أشغال، والله أوْلى بالعُذْر."}, "52831": {"num": 52831, "aya": 27, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قول الله: {يا أيها الذين آمنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا}، قال: الاستئناس: التنحنح والتَّجَرُّسُ، حتى يعرفوا أن قد جاءهم أحد. قال: والتجرُّس: كلامه وتنحنحه."}, "52837": {"num": 52837, "aya": 27, "qail": "ابن عباس", "tabaqa": "صحابي", "bab": "أحكام، وآثار متعلقة بالآية", "text": "عن ابن عباس، قال: استأذن عمر على النبي صلى الله عليه وسلم، فقال: السلام على رسول الله، السلام عليكم، أيدخل عمر؟."}, "52844": {"num": 52844, "aya": 27, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "أحكام، وآثار متعلقة بالآية", "text": "عن عبد الله بن مسعود -من طريق كُرْدُوسٍ- قال: عليكم أن تستأذنوا على أُمَّهاتكم وأخواتكم."}, "52849": {"num": 52849, "aya": 27, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "أحكام، وآثار متعلقة بالآية", "text": "عن ابن جُرَيج، قال: سمعتُ عطاء بن أبي رباح يُخبِر عن عبد الله بن عباس، قال: ثلاث آياتٍ قد جَحَدَهُنَّ الناسُ: قال الله: {إن أكرمكم عند الله أتقاكم} [الحجرات: 13]، قال: ويقولون: إنّ أكرمهم عند الله أعظمهم شأنًا. قال: والإذن كله قد جحده الناسُ. فقلت له: أستأذن على أخواتي أيتام في حجري معي في بيت واحد؟ قال: نعم. فردَدْتُ على مَن حضرني … ؟ فأبى، قال: أتُحِبُّ أن تراها عُريانة؟ قلت: لا. قال: فاستأذِنْ. فراجعته أيضًا، قال: أتُحِبُّ أن تطيع الله؟ قلت: نعم. قال: فاستأذن. فقال لي سعيد بن جبير: إنّك لَتُرَدِّدُ عليه. قلت: أردتُ أن يُرَخِّص لي."}, "52853": {"num": 52853, "aya": 27, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "أحكام، وآثار متعلقة بالآية", "text": "قال مجاهد بن جبر: جاء عبد الله بن عمر مِن حاجة، وقد آذاه الرَّمضاء، فأتى فُسطاط امرأةٍ من قريش، فقال: السلام عليكم، أدخل؟ فقالت: ادخل بسلام. فأعاد، فأعادت، وهو يُراوِح بين قدميه، قال: قولي: ادخل. قالت: ادخل. فدخل."}, "52854": {"num": 52854, "aya": 27, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "أحكام، وآثار متعلقة بالآية", "text": "عن مجاهد بن جبر -من طريق عبد الكريم أبي أمية- قال: إذا دخلتَ بيتًا غيرَ مسكون ليس فيه أحدٌ؛ فقل: السلام علينا مِن ربنا، السلام علينا وعلى عباد الله الصالحين."}, "52859": {"num": 52859, "aya": 27, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "أحكام، وآثار متعلقة بالآية", "text": "قال ابن جريج، وقال عطاء بن أبي رباح: {وإذا بلغ الأطفال منكم الحلم فليستأذنوا} [النور: 59]: فواجب على الناس أجمعين إذا احتلموا أن يستأذنوا على مَن كان من الناس. قلت لعطاء: أواجِبٌ على الرجل أن يستأذن على أُمِّه ومَن وراءها من ذات قرابته؟ قال: نعم. قلت: بأيٍّ وجبت؟ قال: قوله: {وإذا بلغ الأطفال منكم الحلم فليستأذنوا}."}, "52860": {"num": 52860, "aya": 27, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "أحكام، وآثار متعلقة بالآية", "text": "عن ابن جريج، قال: قلت لعطاء [بن أبي رباح]: أيستأذن الرجل على امرأته؟ قال: لا."}, "52887": {"num": 52887, "aya": 29, "qail": "محمد ابن الحنفية", "tabaqa": "", "bab": "تفسير الآية", "text": "عن محمد ابن الحنفية -من طريق هشيم، عن حجاج، عن سالم المكي- في قوله: {بيوتا غير مسكونة}، قال: هي هذه الخانات التي في الطُرُق."}, "52888": {"num": 52888, "aya": 29, "qail": "محمد ابن الحنفية", "tabaqa": "", "bab": "تفسير الآية", "text": "عن محمد ابن الحنفية -من طريق عبد الله بن قُبَيْصة الفَزاري، عن حجّاج عن سالم المكي- {بيوتًا غير مسكونة}، قال: هي بيوتكم التي في السوق."}, "52889": {"num": 52889, "aya": 29, "qail": "محمد ابن الحنفية", "tabaqa": "", "bab": "تفسير الآية", "text": "عن محمد ابن الحنفية -من طريق سعيد بن سابق، عن الحجاج بن أرطاة، عن سالم المكي- في: {بيوتا غير مسكونة}، قال: هي بيوت مكة."}, "52893": {"num": 52893, "aya": 29, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر ="}, "52895": {"num": 52895, "aya": 29, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ليس عليكم جناح}، قال: كانوا يضعون بطريق المدينة أقْتابًا وأمتعات في بيوت ليس فيها أحد، فأُحِلَّت لهم أن يدخلوها بغير إذن."}, "52896": {"num": 52896, "aya": 29, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {بيوتا غير مسكونة}، قال: هي البيوت التي ينزلها السَّفْرُ، لا يسكنها أحد."}, "52910": {"num": 52910, "aya": 29, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ليس عليكم جناح أن تدخلوا بيوتا غير مسكونة فيها متاع لكم}، قال: بيوت التُّجّار، ليس عليكم جناح أن تدخلوها بغير إذن، الحوانيت التي بالقَيْساريات والأسواق. وقرأ: {فيها متاع لكم} متاع للناس، ولبني آدم."}, "52913": {"num": 52913, "aya": 29, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح - قوله: {وما تكتمون}، قال: ما تغيبون."}, "52954": {"num": 52954, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي بن أبي طلحة- قوله: {وقل للمؤمنات يغضضن من أبصارهن}، قال: يغضضن أبصارهنَّ مِن شهواتهن فيما يكره الله."}, "52955": {"num": 52955, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: عمّا لا يحِلُّ لهم مِن النظر."}, "52960": {"num": 52960, "aya": 31, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء- {ويحفظن فروجهن}: يعني: عن الفواحش."}, "52967": {"num": 52967, "aya": 31, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق أبي الأحْوَص- في قوله: {ولا يبدين زينتهن} قال: الزينة: السِّوار، والدُّمْلُج، والخلخال، والقرط، والقلادة، {إلا ما ظهر منها} قال: الثياب، والجلباب."}, "52968": {"num": 52968, "aya": 31, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق أبي الأحوص- قال: الزينة زينتان: زينة ظاهرة، وزينة باطنة لا يراها إلا الزوج. فأمّا الزينة الظاهرة: فالثياب. وأما الزينة الباطنة: فالكحل، والسوار، والخاتم. -ولفظ ابن جرير-: فالظاهرة منها: الثياب. وما خفي: فالخلخالان، والقرطان، والسوارن."}, "52969": {"num": 52969, "aya": 31, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق أبي إسحاق [السبيعي]، عن أبي الأحوص- {إلا ما ظهر منها}، قال: الثياب. ="}, "52973": {"num": 52973, "aya": 31, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن ابن جُرَيج، قال: قال ابنُ عباس في قوله: {ولا يبدين زينتهن إلا ما ظهر منها}، قال: الخاتم، والمسكة. ="}, "52974": {"num": 52974, "aya": 31, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "قال ابن جريج: وقالت عائشة: القلب والفتخة. ="}, "52977": {"num": 52977, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق مجاهد- في قوله: {إلا ما ظهر منها}، قال: هو خِضاب الكفِّ والخاتم."}, "52978": {"num": 52978, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضحاك- قال: الظاهر منها: الكحل والخدّان."}, "52979": {"num": 52979, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- {ولا يبدين زينتهن إلا ما ظهر منها}، قال: الكحل، والخاتم، والقرط، والقِلادة."}, "52980": {"num": 52980, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- {ولا يبدين زينتهن إلا ما ظهر منها}، قال: الكحل، والخاتم."}, "52981": {"num": 52981, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {إلا ما ظهر منها}، قال: رُقعة الوجه، وباطن الكف."}, "52982": {"num": 52982, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله: {إلا ما ظهر منها}، قال: وجهها، وكفّاها، والخاتم."}, "52983": {"num": 52983, "aya": 31, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عمر ="}, "52987": {"num": 52987, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- قوله: {ولا يبدين زينتهن إلا ما ظهر منها}، قال: والزينة الظاهرة: الوجه، وكُحل العين، وخِضاب الكف، والخاتم؛ فهذه تظهر في بيتها لِمَن دخل مِن الناس عليها."}, "52988": {"num": 52988, "aya": 31, "qail": "المسور بن مخرمة", "tabaqa": "صحابي", "bab": "", "text": "عن المِسْور بن مخرمة -من طريق الزهري، عن رجل- في قوله: {إلا ما ظهر منها}، قال: القُلْبَيْن -يعني: السوار-، والخاتم، والكحل."}, "52994": {"num": 52994, "aya": 31, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء بن السائب- {ولا يبدين زينتهن إلا ما ظهر منها}: الخاتم، والخِضاب، والكحل."}, "52995": {"num": 52995, "aya": 31, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عبد الله بن مسلم- في قوله: {إلا ما ظهر منها}، قال: الوجه، والكفُّ."}, "52996": {"num": 52996, "aya": 31, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء بن دينار- في قول الله: {ولا يبدين زينتهن الا ما ظهر منها}: يعني: الوجه، والكفين؛ فزينة الوجه الكُحْل، وزينة الكفين الخضاب، ولا يَحِلُّ أن يرى منها غريبٌ غيرَ ذلك."}, "53002": {"num": 53002, "aya": 31, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضحاك بن مزاحم -من طريق جُوَيبر- في قوله: {ولا يبدين زينتهن}، قال: الكَفُّ، والوَجْه."}, "53006": {"num": 53006, "aya": 31, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "", "text": "عن عامر الشعبي -من طريق عاصم- {إلا ما ظهر منها}، قال: الكحل، والخضاب، والثياب."}, "53007": {"num": 53007, "aya": 31, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق يونس، أو غيره- في قوله: {إلا ما ظهر منها}، قال: الثياب."}, "53008": {"num": 53008, "aya": 31, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق يونس- في قوله: {ولا يبدين زينتهن}، قال: الوجه، والثياب."}, "53011": {"num": 53011, "aya": 31, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "", "text": "عن عطاء [بن أبي رباح]-من طريق أبي عمرو- في قوله: {إلا ما ظهر منها}، قال: الكفّان، والوجه."}, "53012": {"num": 53012, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- {ولا يبدين زينتهن إلا ما ظهر منها}، قال: المسكتان، والخاتم، والكحل. قال قتادة: وبلغني: أنّ النبي صلى الله عليه وسلم قال: «لا يحِلُّ لامرأة تؤمن بالله واليوم الآخر أن تُخرِج يدها إلّا إلى ههنا». ويقبض نصف الذراع."}, "53019": {"num": 53019, "aya": 31, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ولا يبدين زينتهن إلا ما ظهر منها}: مِن الزينة: الكحل، والخضاب، والخاتم، هكذا كانوا يقولون، وهذا يراه الناس."}, "53024": {"num": 53024, "aya": 31, "qail": "قتادة", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن قتادة، أن النبي صلى الله عليه وسلم قال: «إن الجارية إذا حاضت لم يصلح أن يرى منها إلا وجهها ويداها إلى المفصل»."}, "53028": {"num": 53028, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس: قال في سورة النور: {ولا يبدين زينتهن إلا ما ظهر منها وليضربن بخمرهن على جيوبهن}، وقال: {يدنين عليهن من جلابيبهن}، ثم استثنى فقال: {والقواعد من النساء اللاتي لا يرجون نكاحا فليس عليهن جناح ان يضعن ثيابهن} الآية. والمتبرجات: اللاتي يُخْرِجْن عن نُحُورِهِنَّ."}, "53029": {"num": 53029, "aya": 31, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء-: {وليضربن} وليشددن {بخمرهن على جيبوبهن} يعني: على النحر، والصدر، فلا يُرى منه شيء."}, "53035": {"num": 53035, "aya": 31, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق ابن جريج- في قوله: {ولا يبدين زينتهن إلا لبعولتهن} {أو}، {أو}، قال: الطَّوق، والقرطين."}, "53036": {"num": 53036, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {ولا يبدين زينتهن إلا ما ظهر منها}: والزينة الظاهرة: الوجه، وكحل العينين، وخِضاب الكف، والخاتم، فهذا تُظْهِرُه في بيتها لِمَن دخل مِن الناس عليها. ثم قال: {ولا يبدين زينتهن إلا لبعولتهن أو آبائهن} الآية، والزينة التي تبديها لهؤلاء: قرطاها، وقلادتها، وسوارها، فأمّا خلخالها، ومعضدها، ونحرها، وشعرها؛ فإنّها لا تُبديه إلا لزوجها."}, "53037": {"num": 53037, "aya": 31, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء- {ولا يبدين زينتهن}: يعني: ولا يضعن الجلباب -وهو القناع- مِن فوق الخمار، {إلا لبعولتهن أو آبائهن} الآية، قال: فهو مَحْرَمٌ، وكذلك العمُّ والخال."}, "53043": {"num": 53043, "aya": 31, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "", "text": "عن الضَّحّاك بن مُزاحِم -من طريق جُوَيْبِر- {ولا يبدين زينتهن الا لبعولتهن أو ابائهن}، قال: النحر، والقرط."}, "53044": {"num": 53044, "aya": 31, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "", "text": "عن عامر الشعبي ="}, "53046": {"num": 53046, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد بن أبي عروبة- في قوله: {ولا يبدين زينتهن إلا لبعولتهن}، قال: تُبدي لهؤلاء الرأس."}, "53051": {"num": 53051, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الكلبي، عن أبي صالح- {أو نسائهن}، قال: هُنَّ المسلمات، لا تبديه ليهودية، ولا نصرانية، وهو النَّحر، والقرط، والوشاح، وما يحرم أن يراه إلا محرم."}, "53052": {"num": 53052, "aya": 31, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء- {أو نسائهن}: يعني: نساء المؤمنات."}, "53057": {"num": 53057, "aya": 31, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الملك ابن جريج -من طريق حجاج- قوله: {أو نسائهن}، قال: بلغني: أنّهُنَّ نساء المسلمين، لا يحل لمسلمة أن تُرِي مشركة عِرْيتَها، إلّا أن تكون أمة لها، فذلك قوله: {أو ما ملكت أيمانهن}."}, "53062": {"num": 53062, "aya": 31, "qail": "عطاء بن أبي مسلم الخراساني", "tabaqa": "تابعي", "bab": "من أحكام الآية", "text": "قال عطاء بن أبي مسلم الخراساني -من طريق ابنه عثمان-: لَمّا قدم أصحاب النبيِّ صلى الله عليه وسلم بيت المقدس كان قوابلُ نسائهم اليهودياتِ والنصرانياتِ."}, "53064": {"num": 53064, "aya": 31, "qail": "الحسن", "tabaqa": "تابعي", "bab": "من أحكام الآية", "text": "عن الحسن -من طريق الحسن بن دينار- قال: لا تضع المرأةُ خمارها عند أبيها، ولا ابنها، ولا أختها، ولا أخيها. ="}, "53065": {"num": 53065, "aya": 31, "qail": "ابن عباس", "tabaqa": "صحابي", "bab": "من أحكام الآية", "text": "وقال ابن عباس: ينظرون إلى موضع القرطين، والقلادة، والسوارين، والخلخالين. ="}, "53072": {"num": 53072, "aya": 31, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "قراءات", "text": "عن ابن جريج، قال: أخبرني عمرو بن دينار، عن مخلد التميمي، أنّه قال في قوله: {أوْ ما مَلَكَتْ أيْمانُهُنَّ}، قال: في القراءة الأولى: (أيْمانُكُمْ)."}, "53073": {"num": 53073, "aya": 31, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "قراءات", "text": "عن عبد الملك ابن جريج، في قوله: {أوْ ما مَلَكَتْ أيْمانُهُنَّ}، قال: في القراءة الأولى: (الَّذِينَ لَمْ يَبْلُغُواْ الحُلُمَ مِمّا مَلَكَتْ أيْمانُكُمْ)."}, "53074": {"num": 53074, "aya": 31, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "قراءات", "text": "عن سعيد بن جبير -من طريق عطاء- في قوله: {أو ما ملكت أيمانهن}: يعني: عبد المرأة، لا يحِلُّ لها أن تضع جلبابها عند عَبْدِ زوجها."}, "53078": {"num": 53078, "aya": 31, "qail": "عبد الملك ابن جريج", "tabaqa": "تابع التابعين", "bab": "قراءات", "text": "عن عبد الملك ابن جُرَيْج -من طريق حجاج- {أو ما ملكت أيمانهن}: مِن الإماء المشركات."}, "53085": {"num": 53085, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "من أحكام الآية", "text": "عن عبد الله بن عباس، قال: لا بأس أن يرى العبدُ شعرَ سيدته."}, "53090": {"num": 53090, "aya": 31, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "من أحكام الآية", "text": "عن عامر الشعبي -من طريق المغيرة- قال: لا تضع المرأةُ خمارَها عند مملوكها؛ فإن فجأها فلا شيء."}, "53091": {"num": 53091, "aya": 31, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "من أحكام الآية", "text": "عن عطاء [بن أبي رباح]-من طريق ابن جُريج- أنّه سُئِل: هل يرى غلامُ المرأة رأسَها وقدمها؟ قال: ما أُحِبُّ ذلك، إلا أن يكون غلامًا يسيرًا، فأمّا رجل ذو لحية فلا."}, "53093": {"num": 53093, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي - في قوله: {أو التابعين غير أولي الأربة}، قال: هذا الرجل يتبع القومَ وهو مُغَفَّل في عقله، لا يكْتَرِث للنساء، ولا يشتهي النساء."}, "53094": {"num": 53094, "aya": 31, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "", "text": "قال عامر الشعبي: هم الذين يتبعون القومَ لِيصيبوا مِن فضل طعامهم، لا هِمَّة لهم إلا ذلك، ولا حاجة لهم في النساء."}, "53095": {"num": 53095, "aya": 31, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "قال الحسن البصري: يتبع الرجلُ منهم الرجلَ يخدمه بطعام بطنه."}, "53096": {"num": 53096, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {أو التابعين}، قال: هو التابع يتبعك، يُصِيب مِن طعامك."}, "53098": {"num": 53098, "aya": 31, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {أو التابعين غير أولي الإربة من الرجال}، قال: هو الذي يتبع القومَ حتى كأنّه كان منهم، ونشأ فيهم، وليس يتبعهم لإربة نسائهم، وليس له في نسائهم إربة، وإنما يتبعهم لإرفاقهم إيّاه. (ز)  {غَيْرِ أُولِي الْإِرْبَةِ مِنَ الرِّجَالِ}"}, "53099": {"num": 53099, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق أبي إسحاق، عن رجل- في قوله: {أو التابعين غير أولي الأربة من الرجال}، قال: هو الذي لا يستحي منه النساء."}, "53100": {"num": 53100, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- في قوله: {أو التابعين غير أولي الأربة من الرجال}، قال: كان الرجلُ يتبع الرجلَ في الزمان الأول، لا يَغار عليه، ولا تَرْهَب المرأةُ أن تضع خِمارها عنده، وهو الأحمقُ الذي لا حاجة له في النساء."}, "53101": {"num": 53101, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، {غير أولي الإربة}، قال: هو المُخَنَّث الذي لا يقوم زُبُّه."}, "53102": {"num": 53102, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس: الأحمق والعِنِّين."}, "53108": {"num": 53108, "aya": 31, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير، {غير أولي الإربة من الرجال}، قال: هو الشيخ الكبير الذي لا يطيق النساء."}, "53109": {"num": 53109, "aya": 31, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء بن السائب- قال: هو المَعْتُوه."}, "53117": {"num": 53117, "aya": 31, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "", "text": "عن عامر الشعبي-من طريق جابر- قال: الأبله."}, "53118": {"num": 53118, "aya": 31, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "", "text": "قال عامر الشعبي: {غير أولي الإربة} مَن ليس له أرب."}, "53119": {"num": 53119, "aya": 31, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "", "text": "عن عامر الشعبي -من طريق مغيرة- قال: هو الذي لم يبلغ إربه أن يَطَّلِع على عورة النساء."}, "53120": {"num": 53120, "aya": 31, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق أشعث- قال: هو الأحمق الذي لا حاجة له بالنساء."}, "53121": {"num": 53121, "aya": 31, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق عمرو بن عبيد- {غير أولي الإربة}، قال: المُخَنَّث."}, "53122": {"num": 53122, "aya": 31, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "قال الحسن البصري: هو الذي لا ينتشر، ولا يستطيع غِشْيان النساء، ولا يشتهيهن."}, "53123": {"num": 53123, "aya": 31, "qail": "عطاء بن أبي رباح", "tabaqa": "تابعي", "bab": "", "text": "عن عطاء بن أبي رباح -من طريق جابر-: الذي لا يحمله أربه على أن يُراوِد النساء."}, "53124": {"num": 53124, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: هو الرجل الأحمقُ الذي لا تشتهيه المرأةُ، ولا يَغارُ عليه الرجلُ."}, "53138": {"num": 53138, "aya": 31, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء [بن دينار]- في قوله: {أو الطفل الذين لم يظهروا على عورات النساء}، قال: الغِلمان الصِّغار."}, "53140": {"num": 53140, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: الذي لم يبلغ الحُلُم، ولا النِّكاح."}, "53151": {"num": 53151, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- {ولا يضربن بأرجلهن}، قال: كانت المرأة تضرب برجلها ليسمع قَعْقَعة الخُلخال فيها؛ فنهي عن ذلك."}, "53153": {"num": 53153, "aya": 31, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن مسعود -من طريق أبي الأحوص- {ليعلم ما يخفين من زينتهن}، قال: الخُلخال."}, "53155": {"num": 53155, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {ولا يضربن بأرجلهن}: وهو أن تَقْرَع الخلخالَ بالآخر عند الرجال، أو يكون على رجليها خلاخل فتُحَرِّكهن عند الرجال، فنهى الله عن ذلك؛ لأنه مِن عمل الشيطان."}, "53156": {"num": 53156, "aya": 31, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن سعيد بن جبير -من طريق عطاء [بن دينار]- قال: إنّ المرأة كانت يكون في رجلها الخلخال فيه الجلاجل، فإذا دخل عليها غريبٌ تُحَرِّك رِجلها عمدًا؛ ليسمع صوت الخلخال، فقال: {ولا يضربن} يعني: لا يُحَرِّكن أرجلهن؛ {ليعلم ما يخفين} يعني: ليعلم الغريبُ إذا دخل عليها ما تُخْفِي من زينتها."}, "53158": {"num": 53158, "aya": 31, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق مَعْمَر- {ولا يضربن بأرجلهن}، قال:: هو الخلخال، لا تضرب امرأةٌ برجلها لِيُسْمع صوت خلخالها."}, "53160": {"num": 53160, "aya": 31, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ولا يضربن بأرجلهن ليعلم ما يخفين من زينتهن}، قال: الأجراس مِن حليهن يجعلنها في أرجلهن في مكان الخلاخل، فنهاهنَّ اللهُ أن يضربن بأرجلهن لتسمع تلك الأجراس."}, "53162": {"num": 53162, "aya": 31, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء [بن دينار]- في قوله: {المؤمنون}: يعني: المصدقين بتوحيد الله."}, "53169": {"num": 53169, "aya": 31, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن مسعود، قال: سمعتُ النبيَّ صلى الله عليه وسلم يقول: «الندم توبة»."}, "53170": {"num": 53170, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- أنّه سُئِل عن الرجل يزني بالمرأة ثم يتزوجها. فقال: أوله سفاح، وآخره نكاح، وتوبتهما جميعًا أحبُّ إلَيَّ مِن توبتهما متفرقين؛ إن الله يقول: {وتوبوا إلى الله جميعًا أيها المؤمنون}."}, "53199": {"num": 53199, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضحاك- في قوله: {وليستعفف الذين لا يجدون نكاحا} الآية، قال: ليتزوج مَن لا يجد؛ فإنّ الله سيغنيه."}, "53206": {"num": 53206, "aya": 33, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير -من طريق عطاء- {والذين يبتغون الكتاب}: يعني: الذين يطلبون المكاتبة مِن المملوكين."}, "53208": {"num": 53208, "aya": 33, "qail": "أنس بن مالك", "tabaqa": "صحابي", "bab": "", "text": "عن أنس بن مالك، قال: سألني سيرينُ المكاتبةَ، فأَبَيْتُ عليه، فأتى عمرَ بن الخطاب، فأقبل عَلَيَّ بالدِّرَّة، وقال: كاتِبْه. وتلا: {فكاتبوهم إن علمتم فيهم خيرا}، فكاتبتُه."}, "53209": {"num": 53209, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- قال: لا ينبغي لرجل إذا كان عنده المملوك الصالح الذي له المال، يريد أن يكاتَب، ألّا يكاتبه."}, "53212": {"num": 53212, "aya": 33, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن ابن جريج، قال: قلت لعطاء [بن أبي رباح]: أواجِبٌ عَلَيَّ إذا علِمتُ مالًا أن أكاتبه؟ قال: ما أراه إلا واجبًا. ="}, "53217": {"num": 53217, "aya": 33, "qail": "مالك بن أنس", "tabaqa": "تابع التابعين", "bab": "", "text": "عن مالك بن أنس -من طريق ابن وهب-: الأمر عندنا: أن ليس على سيِّد العبد أن يكاتبه إذا سأله ذلك، ولم أسمع بأحدٍ مِن الأئمة أكرَه أحدًا على أن يُكاتب عبدَه. وقد سمعت بعض أهل العلم إذا سُئِل عن ذلك؛ فقيل له: إن الله تبارك وتعالى يقول في كتابه: {فكاتبوهم إن علمتم فيهم خيرا}. يتلو هاتين الآيتين: {وإذا حللتم فاصطادوا} [المائدة: 2]، {فإذا قضيت الصلاة فانتشروا في الأرض وابتغوا من فضل الله} [الجمعة: 10]. قال مالك: فإنّما ذلك أمرٌ أذِن اللهُ فيه للناس، وليس بواجب على الناس، ولا يَلْزَمُ أحدًا."}, "53218": {"num": 53218, "aya": 33, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {فكاتبوهم إن علمتم فيهم خيرا}، قال: ليس بواجب عليه أن يكاتبه، إنما هذا أمر أذن الله فيه، ودليل."}, "53222": {"num": 53222, "aya": 33, "qail": "ابن جريج", "tabaqa": "تابع التابعين", "bab": "", "text": "عن ابن جُرَيج، قال: بلغني عن ابن عباس في قوله: {إن علمتم فيهم خيرا}، قال: المال."}, "53223": {"num": 53223, "aya": 33, "qail": "علي بن أبي طالب", "tabaqa": "صحابي", "bab": "", "text": "عن علي بن أبي طالب -من طريق أبي عبد الرحمن السلمي- قال في قوله: {إن علمتم فيهم خيرا}، قال: مالًا."}, "53224": {"num": 53224, "aya": 33, "qail": "علي بن أبي طالب", "tabaqa": "صحابي", "bab": "", "text": "عن علي [بن أبي طالب]، مثله."}, "53225": {"num": 53225, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح، والحكم-، مثله."}, "53226": {"num": 53226, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {إن علمتم فيهم خيرا}، قال: أمانة، ووفاء."}, "53227": {"num": 53227, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق يزيد بن أبي حبيب- {فكاتبوهم إن علمتم فيهم خيرا}: إن علمت أنّ مكاتبك يقضيك."}, "53228": {"num": 53228, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {إن علمتم فيهم خيرا}، قال: إن علمتم لهم حيلةً، ولا تُلْقوا مُؤْنتَهم على المسلمين."}, "53229": {"num": 53229, "aya": 33, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عمر، في قوله {إن علمتم فيهم خيرا}: قوة على الكسب."}, "53232": {"num": 53232, "aya": 33, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم [النخعي] ="}, "53233": {"num": 53233, "aya": 33, "qail": "أبي صالح باذام", "tabaqa": "تابعي", "bab": "", "text": "وأبي صالح [باذام] ="}, "53237": {"num": 53237, "aya": 33, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جبير ="}, "53240": {"num": 53240, "aya": 33, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم [النخعي]-من طريق مغيرة- قال: صِدْقًا، ووفاء."}, "53241": {"num": 53241, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق الحكم- قال: مالًا."}, "53242": {"num": 53242, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق القاسم- {فكاتبوهم إن علمتم فيهم خيرًا}، قال: المال، والوفاء، والصدق."}, "53243": {"num": 53243, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق عن ابن أبي نجيح- {فكاتبوهم إن علمتم فيهم خيرا}، قال: كاتبوهم كائنة أخلاقهم ودينهم ما كان."}, "53244": {"num": 53244, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر ="}}, "n_athar": {"0": 11, "1": 24, "2": 79, "3": 58, "4": 26, "5": 58, "6": 41, "10": 11, "11": 72, "12": 14, "13": 7, "14": 8, "15": 17, "16": 9, "17": 7, "18": 5, "19": 20, "20": 8, "21": 15, "22": 23, "23": 24, "24": 12, "25": 11, "26": 31, "27": 61, "28": 13, "29": 36, "30": 36, "31": 219, "32": 28, "33": 186, "34": 17, "35": 165, "36": 55, "37": 46, "38": 7, "39": 21, "40": 23, "41": 8, "42": 2, "43": 36, "44": 8, "45": 7, "46": 4, "47": 5, "48": 6, "49": 4, "50": 6, "51": 5, "52": 5, "53": 11, "54": 17, "55": 41, "56": 2, "57": 8, "58": 75, "59": 13, "60": 83, "61": 126, "62": 40, "63": 56, "64": 10}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});